INSERT INTO course_group (id, no, name_th, code_prefix, credits, course_count, is_elective_pool, pick_count, note) VALUES
  ('ge', '1', 'หมวดวิชาศึกษาทั่วไป', 'GE-010 / GE-020', 24, 8, false, NULL, 'บังคับ 6 วิชา 18 นก. · เลือก 2 วิชา 6 นก.'),
  ('eng', '2.1', 'กลุ่มวิชาพื้นฐานและปฏิบัติการทางวิศวกรรม', 'EN-714-11001–11010', 24, 10, false, NULL, 'หมวด 1 วิชาแกนหรือวิชาพื้นฐาน · วิชาบรรยาย 7 วิชา 21 นก. + ปฏิบัติการบูรณาการ I–III 3 นก.'),
  ('ai', '2.2', 'กลุ่มวิชาแกนปัญญาประดิษฐ์และระบบอัจฉริยะ', 'EN-714-12001–12008', 22, 8, false, NULL, 'หมวด 2 วิชาชีพบังคับ · แกน AI บังคับทุกแขนง 8 วิชา (บรรยาย 7 + ปฏิบัติการ 1)'),
  ('track', '2.3', 'กลุ่มวิชาชีพบังคับ', 'EN-714-12009–12016', 22, 8, false, NULL, 'หมวด 2 วิชาชีพบังคับ · 8 วิชา (บรรยาย 7 + ปฏิบัติการ 1)'),
  ('elec', '2.4', 'กลุ่มวิชาชีพเลือก', 'EN-714-14001–14052', 15, 5, true, 5, 'หมวด 4 วิชาเลือก · เลือก 5 วิชาจาก pool 52 วิชา (T1 14001–14015 · T2 14016–14035 · T3 14036–14050 · หัวข้อพิเศษ 14051–14052)'),
  ('proj', '2.5', 'กลุ่มวิชาโครงงานและสัมมนา', 'EN-714-12017–12020', 5, 4, false, NULL, 'หมวด 2 วิชาชีพบังคับ · สัมมนา · เตรียมโครงงาน · โครงงาน (Capstone) แผน ก/ข'),
  ('field', '2.6', 'กลุ่มวิชาสหกิจศึกษา', 'EN-714-17001–17002', 7, 2, false, NULL, 'หมวด 7 สหกิจศึกษา · เตรียมสหกิจ 1 นก. · สหกิจศึกษา 6 นก. (≥16 สัปดาห์)'),
  ('free', '3', 'หมวดวิชาเลือกเสรี', '—', 6, 2, false, NULL, 'เลือกจากรายวิชาที่มหาวิทยาลัยเปิดสอน');
