INSERT INTO course (code, programme_id, group_id, short_name, name_th, name_en, credit_text, credits, lecture_hours, lab_hours, self_hours, study_year, semester, pending_semester, description_th, description_en) VALUES
  ('GE-001-13002', 'AISE-2570', 'ge', 'อังกฤษ 1', 'ภาษาอังกฤษสำหรับโลกสมัยใหม่', 'English for Modern World', '3(2-2-5)', 3, 2, 2, 5, 1, 1, false, 'คำศัพท์ วลีและโครงสร้างประโยคภาษาอังกฤษเพื่อการสื่อสารในชีวิตประจำวัน ทักษะการฟังและสนทนาประโยคภาษาอังกฤษในสถานการณ์ต่าง ๆ การอ่านข้อความหรือเนื้อหาสั้น ๆ ที่น่าสนใจ', 'English vocabulary, phrases, and sentence structures for everyday communication; listening and speaking practice in common situations; reading short, engaging texts'),
  ('GE-001-13005', 'AISE-2570', 'ge', 'คุณค่า มกส.', 'มรดกภูมิปัญญาทางวัฒนธรรมเพื่อการพัฒนา', 'Intangible Cultural Heritage for Development', '3(2-2-5)', 3, 2, 2, 5, 1, 1, false, 'ความสำคัญของค่านิยมและวัฒนธรรมองค์กรในระดับหน่วยงาน สังคม และประเทศ เอกลักษณ์ของมหาวิทยาลัย องค์ประกอบการเรียนรู้ทางสังคม จิตตปัญญาศึกษาเพื่อการพัฒนาความเป็นมนุษย์สำหรับสังคมคุณภาพ จิตสาธารณะ ผู้ประกอบการเพื่อการพัฒนาท้องถิ่น', 'The importance of organizational and social values and culture at institutional, social, and national levels; university identity; components of social learning; contemplative education for human development; public-mindedness; entrepreneurship for local development'),
  ('GE-001-13001', 'AISE-2570', 'ge', 'ดิจิทัล', 'เทคโนโลยีดิจิทัลและปัญญาประดิษฐ์เบื้องต้น', 'Fundamentals of Digital Technology and Artificial Intelligence', '3(2-2-5)', 3, 2, 2, 5, 1, 2, false, 'ความเข้าใจในการใช้เทคโนโลยีดิจิทัลขั้นพื้นฐาน การประยุกต์ใช้เทคโนโลยีและนวัตกรรมดิจิทัล ความมั่นคงและปลอดภัยทางไซเบอร์ การพัฒนาแพลตฟอร์มออนไลน์ การรู้ดิจิทัล การพัฒนาทักษะดิจิทัล การใช้เทคโนโลยีดิจิทัล ความเป็นพลเมืองดิจิทัล การเป็นผู้ใช้ดิจิทัลอย่างชาญฉลาด', 'Fundamental digital technology literacy; applications of digital technology and innovation; cybersecurity and online safety; online platform development; digital skills for learning, work, and responsible participation in contemporary society'),
  ('GE-001-13004', 'AISE-2570', 'ge', 'สุขภาพและการจัดการตนเอง', 'สุขภาพและการจัดการตนเอง', 'Health and Self-Management', '3(2-2-5)', 3, 2, 2, 5, 2, 3, false, 'ปัจจัยและความสำคัญของแรงบันดาลใจในการใช้ชีวิต เทคนิคและวิธีคิดของผู้ประสบความสำเร็จ การเรียนรู้สถานการณ์ต่าง ๆ ด้วยตนเอง การวิเคราะห์และวางแผนเป้าหมายชีวิต การสร้างความสัมพันธ์ระหว่างบุคคล การแสดงลักษณะท่าทาง การวางตัว การมีมนุษยสัมพันธ์', 'Sources and roles of inspiration in life; mindsets and techniques of successful people; self-directed learning from life situations; life-goal analysis and planning; interpersonal relationships; personal conduct and human relations'),
  ('GE-002-14005', 'AISE-2570', 'ge', 'อังกฤษ 2', 'ภาษาอังกฤษเพื่อการสื่อสารระดับสากลและวิชาชีพ', 'English for Global and Professional Communication', '3(2-2-5)', 3, 2, 2, 5, 2, 2, false, 'การสื่อสารและใช้ภาษาอังกฤษในบริบทต่าง ๆ คำศัพท์ ประโยค ไวยากรณ์และสำนวนภาษาอังกฤษในสังคมพหุวัฒนธรรม การฟัง การเขียนและโต้ตอบในบริบทการท่องเที่ยว การเดินทาง และเพื่อนต่างวัฒนธรรม', 'English communication in a range of contexts; vocabulary, sentence patterns, grammar, and idiomatic expressions in multicultural society; listening, writing, and interaction in the contexts of tourism, travel, and cross-cultural friendship'),
  ('GE-002-14015', 'AISE-2570', 'ge', 'ปรัชญา/เศรษฐฯ', 'สิ่งแวดล้อมชุมชน ธุรกิจสีเขียว และการปรับตัวต่อภูมิอากาศ', 'Community Environment, Green Business, and Climate Adaptation', '3(2-2-5)', 3, 2, 2, 5, 2, 3, false, 'สภาพแวดล้อมทางสังคม เศรษฐกิจ และการเมือง การปกครองทั้งภายในและภายนอกประเทศ หลักการบริหาร หลักกฎหมายเบื้องต้น การวิเคราะห์ปัญหาด้านจริยธรรมทางเศรษฐกิจระดับบุคคล ระดับองค์กร ระดับประเทศและระดับโลกที่เกิดขึ้นในสังคมปัจจุบัน อุปสงค์ อุปทาน ทฤษฎีพฤติกรรมผู้บริโภค การบริโภค การออมและการลงทุน ปัญหาเงินเฟ้อ เงินฝืด การว่างงาน ปรัชญาเศรษฐกิจพอเพียง', 'Philosophical inquiry concerning humanity, society, and economics; social, economic, and political environments; principles of administration and introductory law; analysis of economic-ethical problems at individual, organizational, national, and global levels; supply and demand; consumer behavior; saving and investment; inflation, deflation, unemployment; the philosophy of sufficiency economy'),
  ('GE-001-13003', 'AISE-2570', 'ge', 'ธุรกิจดิจิทัล', 'การเป็นผู้ประกอบการในยุคดิจิทัล', 'Entrepreneurship in Digital Era', '3(3-0-6)', 3, 3, 0, 6, 2, 5, false, 'หลักการเป็นผู้ประกอบการ การบริหารทรัพยากร เวลา การเงิน การบัญชีและระบบการขนส่งเบื้องต้น การตลาดดิจิทัล การสร้างเนื้อหาที่น่าสนใจเพื่อการตลาด การวางแผนการเงิน', 'Principles of entrepreneurship; management of resources, time, and finance; introductory accounting and logistics systems; digital marketing; creation of engaging marketing content; financial planning for business development in a digital society'),
  ('GE-002-14011', 'AISE-2570', 'ge', 'ผู้นำ 21', 'การลงทุนอย่างชาญฉลาด', 'Smart Investment', '3(3-0-6)', 3, 3, 0, 6, 2, 4, false, 'ผู้นำและผู้ตามที่ดี บุคลิกภาพ การทำงานเป็นทีม บริบทความเปลี่ยนแปลงของสังคมโลก การแก้ปัญหา การคิดวิเคราะห์ การสื่อสาร คุณธรรม จริยธรรม หลักธรรมาภิบาลสำหรับผู้นำ การวางแผนการเงินอย่างเป็นระบบ การเป็นนวัตกรสังคม', 'Effective leadership and followership; personality and teamwork; the changing global context; problem solving, analytical thinking, and communication; morality, ethics, and good governance for leaders; systematic financial planning; becoming a social innovator'),
  ('EN-714-11007', 'AISE-2570', 'eng', 'สถิติ', 'สถิติและการวิเคราะห์ข้อมูลสำหรับวิศวกรรม', 'Statistics and Data Analysis for Engineering', '3(3-0-6)', 3, 3, 0, 6, 1, 2, false, 'ความน่าจะเป็น ตัวแปรสุ่ม และการแจกแจงความน่าจะเป็น สถิติเชิงพรรณนาและเชิงอนุมาน การสุ่มตัวอย่าง การประมาณค่า และการทดสอบสมมติฐาน การวิเคราะห์ความแปรปรวน การถดถอย สหสัมพันธ์ และอนุกรมเวลา การออกแบบการทดลองและการควบคุมกระบวนการเชิงสถิติ การประเมินตัวแบบปัญญาประดิษฐ์ และการตรวจสอบการรั่วไหลและความเอนเอียงของข้อมูล', 'Probability, random variables, and probability distributions; descriptive and inferential statistics; sampling, estimation, confidence intervals, and hypothesis testing; analysis of variance, regression, correlation, and time series; design of experiments, measurement-system analysis, and statistical process control; uncertainty and sensitivity analysis; evaluation of AI models; detection of data leakage and bias'),
  ('EN-714-11001', 'AISE-2570', 'eng', 'เขียนแบบ', 'การเขียนแบบวิศวกรรมและการวางผังระบบ', 'Engineering Drawing and System Layout Design', '3(2-2-5)', 3, 2, 2, 5, 1, 1, false, 'หลักการและมาตรฐานการเขียนแบบวิศวกรรม การฉายภาพ ภาพตัด ภาพสามมิติ การกำหนดขนาดและพิกัดความเผื่อ การเขียนแบบชิ้นส่วนและแบบประกอบ การสร้างแบบจำลองสองมิติและสามมิติด้วยคอมพิวเตอร์ช่วยออกแบบ การออกแบบผังฟาร์ม โรงเรือน สถานีตรวจวัด และสายการผลิต แบบท่อ แบบไฟฟ้า และวงจรควบคุม และการส่งมอบข้อมูลแบบสู่การจำลองและดิจิทัลทวิน', 'Principles and standards of engineering drawing; orthographic, sectional, and pictorial projection; dimensioning and tolerancing; part and assembly drawings; two- and three-dimensional computer-aided modeling; layout design for farms, greenhouses, sensing stations, and production lines; piping and instrumentation diagrams; electrical and control-circuit drawings; equipment layout for safety and maintenance; handover of drawing data to simulation and digital twins'),
  ('EN-714-11002', 'AISE-2570', 'eng', 'Programming', 'การเขียนโปรแกรมพื้นฐานสำหรับปัญญาประดิษฐ์', 'Foundational Programming for Artificial Intelligence', '3(2-2-5)', 3, 2, 2, 5, 1, 1, false, 'การคิดเชิงขั้นตอนวิธีและการแก้ปัญหาด้วยโปรแกรม การเขียนโปรแกรมภาษาไพทอน ตัวแปร ชนิดข้อมูล โครงสร้างควบคุม ฟังก์ชัน และการเขียนโปรแกรมเชิงวัตถุ การจัดการแฟ้มข้อมูล ฐานข้อมูล และส่วนต่อประสานโปรแกรมประยุกต์ การใช้ไลบรารีข้อมูลและปัญญาประดิษฐ์ การควบคุมรุ่นและการทดสอบหน่วย และการใช้เครื่องมือช่วยเขียนโปรแกรมอย่างมีวิจารณญาณ', 'Algorithmic thinking and problem solving through programming; programming with Python, variables, data types, control structures, functions, data structures, and object-oriented programming; file handling, relational databases, and use of application programming interfaces; data and AI libraries; version control with Git; unit testing and documentation; critical use of AI coding assistants with verification of correctness and security'),
  ('EN-714-11004', 'AISE-2570', 'eng', 'Workshop 1', 'ปฏิบัติการวิศวกรรมเชิงบูรณาการ 1: การสร้างชิ้นงานและการติดตั้งเซนเซอร์', 'Integrated Engineering Workshop 1: Fabrication and Sensor Installation', '1(0-2-1)', 1, 0, 3, 2, 1, 1, false, 'ความปลอดภัยในการใช้เครื่องมือและพื้นที่ปฏิบัติงาน การอ่านแบบและการวางแผนการสร้าง การวัด ตัด เจาะ ยึด และประกอบโครงสร้าง การเดินท่อและสายไฟ การบัดกรีและติดตั้งอุปกรณ์ การติดตั้งและสอบเทียบเซนเซอร์ การสร้างต้นแบบสถานีตรวจวัด การตรวจสอบคุณภาพชิ้นงาน และการบันทึกแบบ รายการวัสดุ และผลการสอบเทียบจากการปฏิบัติงานเป็นทีม', 'Safety in the use of tools and workshop spaces; interpretation of drawings and build planning; measurement, cutting, drilling, fastening, and structural assembly; piping and electrical wiring; soldering and equipment installation; sensor installation and calibration; prototyping of a sensing station or intelligent-system structure; workmanship quality inspection; documentation of drawings, bills of materials, calibration results, and lessons learned from teamwork'),
  ('EN-714-11009', 'AISE-2570', 'eng', 'เศรษฐศาสตร์วิศวฯ', 'เศรษฐศาสตร์วิศวกรรมและการวิเคราะห์ต้นทุน', 'Engineering Economics and Cost Analysis', '3(3-0-6)', 3, 3, 0, 6, 2, 3, false, 'หลักเศรษฐศาสตร์วิศวกรรม มูลค่าเงินตามเวลา อัตราดอกเบี้ยและการคิดลด มูลค่าปัจจุบันสุทธิ อัตราผลตอบแทนภายใน และระยะเวลาคืนทุน การประมาณต้นทุนระบบข้อมูล คลาวด์ และปัญญาประดิษฐ์ ต้นทุนรวมในการเป็นเจ้าของและวงจรชีวิต จุดคุ้มทุนและเศรษฐศาสตร์ต่อหน่วย การวิเคราะห์ความไวและความเสี่ยง และการจัดทำกรณีธุรกิจและข้อเสนอการลงทุน', 'Principles of engineering economics; time value of money; interest and discounting; net present value, internal rate of return, and payback period; cost estimation for data, cloud, automation, and AI systems; total cost of ownership and life-cycle costing; depreciation, break-even analysis, and unit economics; sensitivity, risk, and uncertainty analysis; preparation of business cases and investment proposals for smart agriculture and smart factories'),
  ('EN-714-11005', 'AISE-2570', 'eng', 'ความร้อน-ของไหล', 'วิศวกรรมความร้อนและของไหลในระบบอัจฉริยะ', 'Thermal-Fluid Engineering in Smart Systems', '3(3-0-6)', 3, 3, 0, 6, 1, 2, false, 'หลักการพื้นฐานของอุณหพลศาสตร์ สมบัติและสถานะของสาร กฎข้อที่หนึ่งและข้อที่สอง และสมดุลมวลและพลังงาน การนำ การพา และการแผ่รังสีความร้อน เครื่องแลกเปลี่ยนความร้อน ระบบทำความเย็นและการอบแห้ง สมบัติของของไหล สมการความต่อเนื่องและแบร์นูลลี การไหลในท่อ ปั๊มและพัดลม และการประยุกต์ในระบบอบแห้งผลผลิตเกษตร ห้องเย็น และการระบายความร้อน', 'Fundamental principles of thermodynamics; properties and states of matter; the first and second laws; mass and energy balances; conduction, convection, and thermal radiation; heat exchangers; refrigeration and air-conditioning systems; drying processes; fluid properties; the continuity and Bernoulli equations; pipe flow and head losses; pumps and fans; applications to agricultural drying systems, irrigation, cold rooms, and cooling systems for AI servers'),
  ('EN-714-11003', 'AISE-2570', 'eng', 'กลศาสตร์วัสดุ', 'กลศาสตร์วัสดุและการออกแบบโครงสร้าง', 'Mechanics of Materials and Structural Design', '3(3-0-6)', 3, 3, 0, 6, 1, 1, false, 'แรงและระบบแรง สมดุลของวัตถุแข็งเกร็ง การวิเคราะห์โครงสร้างและโครง ความเค้นและความเครียดในแนวแกน แรงเฉือน การดัด การบิด และการโก่งตัว ความล้าและรูปแบบความเสียหาย สมบัติวัสดุและการเลือกวัสดุ ค่าความปลอดภัยและเกณฑ์การออกแบบ และการออกแบบโครง เครื่องยึด ฐานติดตั้ง และกล่องหุ้มสำหรับเซนเซอร์ เครื่องจักร หุ่นยนต์ และอากาศยานไร้คนขับ', 'Forces and force systems; equilibrium of rigid bodies; analysis of structures and frames; axial stress and strain; shear, bending, torsion, and deflection; combined stresses, fatigue, and failure modes; material properties and selection; factors of safety and design criteria; design of frames, fixtures, mounting bases, and enclosures for sensors, machinery, robots, and unmanned aerial vehicles; consideration of manufacturability, maintainability, and service life'),
  ('EN-714-11006', 'AISE-2570', 'eng', 'ไฟฟ้า-อิเล็ก', 'พื้นฐานไฟฟ้าและอิเล็กทรอนิกส์สำหรับระบบอัจฉริยะ', 'Electrical and Electronic Fundamentals for Intelligent Systems', '3(3-0-6)', 3, 3, 0, 6, 1, 2, false, 'วงจรไฟฟ้ากระแสตรงและกระแสสลับ กฎของเคอร์ชอฟฟ์และการวิเคราะห์วงจร อุปกรณ์อิเล็กทรอนิกส์ ระบบดิจิทัลและตรรกะ เซนเซอร์ ทรานสดิวเซอร์ และการปรับสภาพสัญญาณ การแปลงสัญญาณแอนะล็อกและดิจิทัล ตัวกระตุ้น มอเตอร์ และอิเล็กทรอนิกส์กำลังเบื้องต้น ความปลอดภัยทางไฟฟ้า และการออกแบบวงจรตรวจวัดและขับเคลื่อนสำหรับไอโอที หุ่นยนต์ และฟาร์มอัจฉริยะ', 'Direct- and alternating-current circuits; Kirchhoff laws and circuit analysis; electronic components; digital and logic systems; sensors, transducers, signal conditioning, calibration, and data acquisition; analog-to-digital conversion; actuators, motors, and introductory power electronics; power supplies, grounding, and electrical safety; design of sensing and actuation circuits for IoT systems, robots, and smart farms'),
  ('EN-714-11008', 'AISE-2570', 'eng', 'Workshop 2', 'ปฏิบัติการวิศวกรรมเชิงบูรณาการ 2: ระบบขับเคลื่อนและการควบคุมอัตโนมัติ', 'Integrated Engineering Workshop 2: Drive Systems and Automatic Control', '1(0-2-1)', 1, 0, 3, 2, 1, 2, false, 'หลักปฏิบัติระบบขับเคลื่อนและกำลังของไหล การเลือกและต่อมอเตอร์ ชุดขับ วาล์ว และกระบอกสูบนิวแมติกส์และไฮดรอลิกส์ การต่อวงจรไฟฟ้าและวงจรลม การเชื่อมต่อเซนเซอร์ ตัวกระตุ้น ไมโครคอนโทรลเลอร์ และตัวควบคุมแบบโปรแกรมได้ การเขียนโปรแกรมควบคุมเบื้องต้น การออกแบบอินเตอร์ล็อกและการหยุดฉุกเฉิน และการทดสอบการทำงานและแก้ไขข้อขัดข้องเป็นทีม', 'Practice with drive systems and fluid power; selection and connection of motors, drives, valves, and pneumatic and hydraulic cylinders; wiring of electrical and pneumatic circuits; connection of sensors, actuators, microcontrollers, and programmable logic controllers; introductory control programming and user interfaces; design of interlocks and emergency stops; functional and safety testing and team troubleshooting'),
  ('EN-714-11010', 'AISE-2570', 'eng', 'Workshop 3', 'ปฏิบัติการวิศวกรรมเชิงบูรณาการ 3: การบูรณาการระบบและการส่งมอบ', 'Integrated Engineering Workshop 3: System Integration and Handover', '1(0-2-1)', 1, 0, 3, 2, 2, 3, false, 'การวิเคราะห์ข้อกำหนดและออกแบบสถาปัตยกรรมระบบบูรณาการ การประกอบตู้ควบคุมและเชื่อมต่อเซนเซอร์ เอดจ์ปัญญาประดิษฐ์ ตัวควบคุมแบบโปรแกรมได้ ระบบสกาดา และตัวกระตุ้น การเชื่อมลำดับการทำงานตั้งแต่การตรวจวัด การประมวลผล การตัดสินใจ ไปจนถึงแผงควบคุม การทดสอบส่วนต่อประสาน สมรรถนะ และความปลอดภัย และการสาธิตระบบแบบครบวงจรพร้อมเอกสารส่งมอบ', 'Requirements analysis and architecture design of integrated systems; assembly of control panels and connection of sensors, AI edge devices, programmable logic controllers, SCADA, and actuators; linking the chain from sensing and processing to decision-making, control, and dashboards; interface, performance, and safety testing; preparation of architecture documentation and operating manuals; end-to-end system demonstration with handover documentation'),
  ('EN-714-12001', 'AISE-2570', 'ai', 'Intro AI', 'ความรู้เบื้องต้นสำหรับปัญญาประดิษฐ์', 'Introduction to Artificial Intelligence', '3(3-0-6)', 3, 3, 0, 6, 1, 1, false, 'ประวัติและพัฒนาการของปัญญาประดิษฐ์ การค้นหา การแทนความรู้ และการให้เหตุผล การเรียนรู้ของเครื่อง คอมพิวเตอร์วิทัศน์ ปัญญาประดิษฐ์เชิงสร้าง และระบบเอเจนต์ วงจรชีวิตของระบบตั้งแต่การกำหนดปัญหาถึงการติดตามหลังนำไปใช้ ข้อจำกัด ความเอนเอียง และการกำกับดูแลของมนุษย์ จริยธรรมและธรรมาภิบาล และการประยุกต์ใช้ในเกษตรและอุตสาหกรรม', 'History and evolution of artificial intelligence; search, knowledge representation, and reasoning; machine learning, computer vision, generative AI, and agentic systems; the system lifecycle from problem formulation to post-deployment monitoring; limitations, bias, and human oversight; AI ethics and governance; applications in agriculture, industry, and enterprise'),
  ('EN-714-12002', 'AISE-2570', 'ai', 'คณิต AI', 'คณิตศาสตร์วิศวกรรมปัญญาประดิษฐ์', 'Mathematics for Artificial Intelligence', '3(3-0-6)', 3, 3, 0, 6, 1, 2, false, 'พีชคณิตเชิงเส้น เวกเตอร์ เมทริกซ์ และการแยกค่าเอกพจน์ แคลคูลัสหลายตัวแปรและอนุพันธ์ย่อย ความน่าจะเป็น การแจกแจง และการอนุมานแบบเบย์ วิธีเชิงตัวเลขและการวิเคราะห์เสถียรภาพ การหาค่าเหมาะที่สุด การลดตามความชัน และการแพร่กระจายย้อนกลับ พื้นฐานการวิจัยดำเนินงาน และการประยุกต์คณิตศาสตร์เพื่อพัฒนาและวิเคราะห์ตัวแบบปัญญาประดิษฐ์', 'Linear algebra, vectors, matrices, and singular value decomposition; multivariable calculus and partial derivatives; probability, distributions, and Bayesian inference; numerical methods and stability analysis; optimization, gradient descent, and backpropagation; foundations of operations research; application of mathematics to developing and analyzing AI models'),
  ('EN-714-12003', 'AISE-2570', 'ai', 'ML/DL', 'การเรียนรู้ของเครื่องและการเรียนรู้เชิงลึก', 'Machine Learning and Deep Learning', '3(2-2-5)', 3, 2, 2, 5, 2, 3, false, 'กระบวนการพัฒนาตัวแบบการเรียนรู้ของเครื่องแบบมีผู้สอนและไม่มีผู้สอน การถดถอย การจำแนก การจัดกลุ่ม และการลดมิติ โครงข่ายประสาทเทียม สถาปัตยกรรมคอนโวลูชันและทรานสฟอร์เมอร์ การแบ่งชุดข้อมูล ตัวชี้วัด และการตรวจสอบข้าม การจัดการข้อมูลรั่วและไม่สมดุล การประเมินความทนทานและความสามารถในการอธิบาย และการทดลองที่ทำซ้ำได้', 'The model-development process for supervised and unsupervised learning; regression, classification, clustering, and dimensionality reduction; neural networks with convolutional and transformer architectures; transfer learning; dataset splitting, metrics, and cross-validation; management of data leakage and class imbalance; evaluation of uncertainty, robustness, and explainability; reproducible experimentation'),
  ('EN-714-12004', 'AISE-2570', 'ai', 'Data Eng', 'วิศวกรรมข้อมูลและข้อมูลขนาดใหญ่', 'Data Engineering and Big Data', '3(3-0-6)', 3, 3, 0, 6, 2, 3, false, 'วงจรชีวิตและสถาปัตยกรรมข้อมูล ข้อกำหนดและสัญญาของชุดข้อมูล ฐานข้อมูลเชิงสัมพันธ์และโนเอสคิวแอล คลังข้อมูล ทะเลข้อมูล และเลกเฮาส์ การออกแบบไปป์ไลน์แบบแบตช์และสตรีม กระบวนการสกัด แปลง และโหลดข้อมูล การตรวจสอบคุณภาพข้อมูล การกำกับข้อมูลและสายธารที่มา และการเชื่อมข้อมูลเซนเซอร์ ฟาร์ม การผลิต และองค์กร', 'Data lifecycle and architecture; dataset specifications and data contracts; relational and NoSQL databases, data warehouses, data lakes, and lakehouse architecture; batch and streaming pipeline design; extract, transform, and load processes; data-quality validation; data governance and lineage; integration of sensor, farm, production, and enterprise data for AI systems'),
  ('EN-714-12006', 'AISE-2570', 'ai', 'Computer Vision', 'คอมพิวเตอร์วิทัศน์และการวิเคราะห์ภาพ', 'Computer Vision and Image Analysis', '3(2-2-5)', 3, 2, 2, 5, 2, 4, false, 'การเกิดภาพ การสอบเทียบกล้อง และการแทนข้อมูลภาพ การประมวลผลภาพดิจิทัล การปรับปรุง การกรอง และการแบ่งส่วนภาพ การสกัดคุณลักษณะ การตรวจจับ การจำแนก และการติดตามวัตถุด้วยการเรียนรู้เชิงลึก การวิเคราะห์ภาพมัลติสเปกตรัมและเทอร์มอล การประเมินสมรรถนะและความสามารถในการอธิบายของตัวแบบ และการประยุกต์กับโรคพืช การคัดเกรด และการตรวจสอบคุณภาพ', 'Image formation, camera calibration, and image representation; digital image and video processing; enhancement, filtering, and segmentation; feature extraction, object detection, classification, and tracking with deep learning; analysis of multispectral and thermal imagery; evaluation of model performance and explainability; applications to plant disease, grading, and quality inspection'),
  ('EN-714-12005', 'AISE-2570', 'ai', 'Sensing/IoT', 'ระบบตรวจวัด ขับเคลื่อน และไอโอทีอัจฉริยะ', 'Smart Sensing, Actuation and Internet of Things Systems', '3(2-2-5)', 3, 2, 2, 5, 2, 3, false, 'สถาปัตยกรรมระบบกายภาพ–ไซเบอร์และอินเทอร์เน็ตของสรรพสิ่ง การเลือก ติดตั้ง และสอบเทียบเซนเซอร์ การปรับสภาพสัญญาณและการวิเคราะห์ความไม่แน่นอน ตัวกระตุ้นและระบบขับเคลื่อน ไมโครคอนโทรลเลอร์ ระบบฝังตัว และตัวควบคุมแบบโปรแกรมได้ โพรโทคอลอุตสาหกรรม การประมวลผลที่ขอบเครือข่าย และการบูรณาการสถานีตรวจวัดสำหรับฟาร์มและโรงงาน', 'Architecture of cyber-physical and Internet of Things systems; sensor selection, installation, and calibration; signal conditioning and uncertainty analysis; actuators and drive systems; microcontrollers, embedded systems, and programmable logic controllers; IoT and industrial protocols; edge computing; integration of sensing-actuation stations for farms and factories'),
  ('EN-714-12007', 'AISE-2570', 'ai', 'Cloud/MLOps', 'โครงสร้างพื้นฐานคลาวด์และการดำเนินการเรียนรู้ของเครื่อง', 'Cloud Infrastructure and Machine Learning Operations', '3(2-2-5)', 3, 2, 2, 5, 2, 4, false, 'สถาปัตยกรรมและรูปแบบบริการคลาวด์ คอนเทนเนอร์ และตัวเร่งการประมวลผลปัญญาประดิษฐ์ การออกแบบระบบที่ขยายขนาดได้และมีความพร้อมใช้สูง ความมั่นคงปลอดภัยของโครงสร้างพื้นฐาน การสร้างไปป์ไลน์ฝึก ทดสอบ นำขึ้นใช้ และปรับปรุงตัวแบบ การติดตามสมรรถนะและการเลื่อนของตัวแบบ และการปรับสมดุลความแม่นยำ ต้นทุน และพลังงาน', 'Cloud architectures and service models, containers, and AI accelerators; design of scalable and highly available systems; infrastructure security; experiment tracking and model registries; construction of training, testing, deployment, and update pipelines; monitoring of performance and model drift; balancing accuracy, cost, and energy'),
  ('EN-714-12008', 'AISE-2570', 'ai', 'Workshop 4', 'ปฏิบัติการวิศวกรรมเชิงบูรณาการ 4: เครือข่ายและโครงสร้างพื้นฐานสำหรับปัญญาประดิษฐ์', 'Integrated Engineering Workshop 4: Networking and AI Infrastructure', '1(0-2-1)', 1, 0, 3, 2, 2, 4, false, 'การเข้าหัวสายและทดสอบสายสัญญาณ การตั้งค่าสวิตช์และเราเตอร์ การกำหนดหมายเลขไอพี ซับเน็ต และเครือข่ายเสมือน การเชื่อมอุปกรณ์อินเทอร์เน็ตของสรรพสิ่งและบอร์ดเอดจ์เข้าสู่เครือข่าย การติดตั้งคอนเทนเนอร์และการเชื่อมต่อบริการคลาวด์ การแก้ปัญหาเครือข่าย การตั้งค่าความมั่นคงปลอดภัยเบื้องต้น และการจัดทำเอกสารการติดตั้ง', 'Cable termination and signal testing; switch and router configuration; IP addressing, subnetting, and virtual LANs; connecting IoT devices and edge boards to the network; container deployment and cloud connectivity; throughput and latency measurement; network troubleshooting; introductory security configuration; installation documentation'),
  ('EN-714-12009', 'AISE-2570', 'track', 'AI BI/Product', 'ธุรกิจอัจฉริยะและการออกแบบผลิตภัณฑ์ปัญญาประดิษฐ์', 'AI Business Intelligence and Product Design', '3(2-2-5)', 3, 2, 2, 5, 2, 4, false, 'การค้นหาและกำหนดปัญหาที่เหมาะสมกับปัญญาประดิษฐ์ การวิจัยผู้ใช้และผู้มีส่วนได้ส่วนเสีย การทำแผนที่ห่วงโซ่คุณค่า การกำหนดข้อกำหนดด้านหน้าที่ ข้อมูล ตัวแบบ และการปฏิบัติการ การประเมินความเป็นไปได้ด้านเทคโนโลยี กฎหมาย และธุรกิจ การออกแบบสถาปัตยกรรมและต้นแบบผลิตภัณฑ์ การออกแบบโมเดลธุรกิจและผลตอบแทน และการออกแบบที่รับผิดชอบและยั่งยืน', 'Discovery and formulation of problems suitable for artificial intelligence; user and stakeholder research; process and value-chain mapping; definition of functional, data, model, and operational requirements; assessment of technology, legal, and business feasibility; architecture and product prototyping; business-model and return design; responsible and sustainable design'),
  ('EN-714-12011', 'AISE-2570', 'track', 'Smart Farming', 'ระบบฟาร์มอัจฉริยะและเกษตรแม่นยำ', 'Smart Farming Systems and Precision Agriculture', '3(2-2-5)', 3, 2, 2, 5, 3, 5, false, 'สถาปัตยกรรมและองค์ประกอบของระบบฟาร์มอัจฉริยะและเกษตรแม่นยำ การออกแบบระบบตรวจวัดดิน น้ำ อากาศ และการเจริญเติบโต การบูรณาการข้อมูลอินเทอร์เน็ตของสรรพสิ่ง คลาวด์ และภูมิสารสนเทศ ระบบชลประทานอัตโนมัติ การพยากรณ์ผลผลิต โรค และแมลง ระบบสนับสนุนการตัดสินใจฟาร์ม และการบูรณาการหุ่นยนต์และอากาศยานไร้คนขับเข้ากับระบบฟาร์ม', 'Architecture and components of smart farming and precision agriculture; design of systems measuring soil, water, weather, and growth; integration of IoT, cloud, and geospatial data; automated irrigation; forecasting of yields, diseases, and pests; farm decision-support systems; integration of robots and unmanned aerial vehicles with farm systems; assessment of resource-use efficiency'),
  ('EN-714-12013', 'AISE-2570', 'track', 'Software & AI Eng', 'วิศวกรรมซอฟต์แวร์และปัญญาประดิษฐ์', 'Software and AI Engineering', '3(2-2-5)', 3, 2, 2, 5, 3, 5, false, 'วงจรชีวิตการพัฒนาซอฟต์แวร์ปัญญาประดิษฐ์และกระบวนการวิศวกรรมซอฟต์แวร์สมัยใหม่ การวิเคราะห์ความต้องการและการออกแบบสถาปัตยกรรมระบบ การพัฒนาไมโครเซอร์วิสและส่วนต่อประสานโปรแกรมประยุกต์ การออกแบบซอฟต์แวร์ที่บำรุงรักษาได้ การทดสอบและการประกันคุณภาพตัวแบบ การควบคุมเวอร์ชัน และการนำขึ้นใช้บนคลาวด์ คอนเทนเนอร์ และอุปกรณ์เอดจ์', 'The AI software development lifecycle and modern software-engineering processes; requirements analysis and system architecture design; microservices and application programming interfaces; maintainable software design; software testing and model quality assurance; version control and team collaboration; deployment on cloud, container, and edge platforms'),
  ('EN-714-12010', 'AISE-2570', 'track', 'Decision/Supply Chain', 'ระบบตัดสินใจอัจฉริยะและการจัดการห่วงโซ่อุปทาน', 'Decision Intelligence and Supply Chain Management', '3(2-2-5)', 3, 2, 2, 5, 2, 4, false, 'ระบบสนับสนุนการตัดสินใจและปัญญาประดิษฐ์ ตัวชี้วัดสำหรับการดำเนินงาน การวิเคราะห์เชิงพยากรณ์และเชิงกำหนด การพยากรณ์อุปสงค์และกำลังการผลิต การวางแผนวัตถุดิบ สินค้าคงคลัง และโลจิสติกส์ การตรวจสอบย้อนกลับและการบริหารความเสี่ยง การหาค่าเหมาะที่สุดด้วยการวิจัยดำเนินงาน และการออกแบบระบบแนะนำที่มีมนุษย์กำกับ', 'Principles of decision-support systems and decision intelligence; operational indicators; predictive and prescriptive analytics; forecasting of demand, supply, and capacity; planning of materials, inventory, and logistics; traceability and risk management; operations-research optimization; sustainability assessment; design of human-in-the-loop recommendation systems'),
  ('EN-714-12015', 'AISE-2570', 'track', 'UAV/Remote Sensing', 'อากาศยานไร้คนขับสำหรับวิศวกรรมเกษตรอัจฉริยะ', 'Unmanned Aerial Vehicles for Smart Agricultural Engineering', '3(2-2-5)', 3, 2, 2, 5, 3, 6, false, 'กฎหมาย ความปลอดภัย และการขึ้นทะเบียนอากาศยานไร้คนขับตามมาตรฐานของสำนักงานการบินพลเรือน หลักการทำงานและประเภทของอากาศยานไร้คนขับ การวางแผนภารกิจและเส้นทางบิน การเก็บข้อมูลด้วยกล้องมัลติสเปกตรัมและเทอร์มอล การวิเคราะห์ภาพถ่ายทางอากาศด้วยปัญญาประดิษฐ์ การประเมินสุขภาพพืชและการฉีดพ่นแม่นยำ และการทดสอบภาคสนาม', 'Working principles and types of unmanned aerial vehicles; law, safety, and registration under Civil Aviation Authority of Thailand standards; mission and flight-path planning; data acquisition with multispectral and thermal cameras; remote sensing and digital mapping; AI-based aerial image analysis; crop-health assessment with vegetation indices and precision spraying; field testing with performance evaluation'),
  ('EN-714-12012', 'AISE-2570', 'track', 'Smart Mfg/Robotics', 'ระบบการผลิตอัจฉริยะและหุ่นยนต์อุตสาหกรรม', 'Smart Manufacturing and Industrial Robotics Systems', '3(2-2-5)', 3, 2, 2, 5, 3, 5, false, 'หลักวิศวกรรมกระบวนการผลิต การสร้างแบบจำลองกระบวนการและดิจิทัลทวิน สถาปัตยกรรมโรงงานอัจฉริยะและการบูรณาการเทคโนโลยีปฏิบัติการกับสารสนเทศ ตัวควบคุมแบบโปรแกรมได้ ระบบสกาดา และเครือข่ายอุตสาหกรรม หุ่นยนต์อุตสาหกรรมและการออกแบบเซลล์หุ่นยนต์ ประสิทธิผลโดยรวมของเครื่องจักรและการบำรุงรักษาเชิงพยากรณ์ และความปลอดภัยของเครื่องจักร', 'Principles of process and production engineering; process modeling and digital twins; smart-factory architecture and integration of operational and information technology; programmable logic controllers, SCADA, and industrial networks; industrial robots and robotic-cell design; overall equipment effectiveness, statistical process control, and predictive maintenance; machine safety; assessment of energy and carbon'),
  ('EN-714-12014', 'AISE-2570', 'track', 'Agentic AI', 'ระบบเอเจนต์ปัญญาประดิษฐ์', 'Agentic AI Systems', '3(2-2-5)', 3, 2, 2, 5, 3, 6, false, 'แนวคิดและสถาปัตยกรรมของระบบเอเจนต์ปัญญาประดิษฐ์ตั้งแต่แบบตอบสนองถึงแบบวางแผน ระบบหลายเอเจนต์และกลไกประสานงาน การเสริมความสามารถตัวแบบภาษาขนาดใหญ่ด้วยเอเจนต์ การเรียกใช้เครื่องมือและฟังก์ชันภายนอก การออกแบบระบบเอเจนต์เพื่อการตัดสินใจอัตโนมัติ การสร้างข้อความเสริมด้วยการสืบค้น และความมั่นคงปลอดภัยและจริยธรรมของเอเจนต์', 'Concepts and architectures of AI agents from reactive to deliberative planning; multi-agent architectures and coordination; augmenting large language models with agents; tool use and external function calling; design of agentic systems for planning and autonomous decision-making; retrieval-augmented generation; and security and ethics of agents'),
  ('EN-714-16001', 'AISE-2570', 'elec', 'CWIE 1', 'การเรียนรู้ร่วมการทำงานด้านวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ 1', 'Work-Integrated Learning in Artificial Intelligence and Intelligent System Engineering 1', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การวิเคราะห์โจทย์และข้อกำหนดจากสถานประกอบการ การศึกษากระบวนการทำงานและข้อจำกัดขององค์กร การกำหนดขอบเขตงานและเกณฑ์การยอมรับร่วมกับพี่เลี้ยง การวางแผนงานและบริหารเวลาภายใต้เงื่อนไขขององค์กร การใช้ข้อมูลขององค์กรอย่างมีจริยธรรมและรักษาความลับ และการรายงานความก้าวหน้าต่ออาจารย์นิเทศและพี่เลี้ยง', 'Analysis of problems and requirements from the host organization; work planning and time management under organizational constraints; design and development of AI or intelligent systems in a real work context; ethical and confidential use of organizational data and resources; testing, delivery, and handover to users; progress reporting and presentation to the academic supervisor and workplace mentor; joint assessment by the university and the host organization'),
  ('EN-714-16002', 'AISE-2570', 'elec', 'CWIE 2', 'การเรียนรู้ร่วมการทำงานด้านวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ 2', 'Work-Integrated Learning in Artificial Intelligence and Intelligent System Engineering 2', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การออกแบบสถาปัตยกรรมและแนวทางแก้ปัญหาตามข้อกำหนดของสถานประกอบการ การเลือกเทคโนโลยีและเครื่องมือให้เหมาะกับข้อจำกัดขององค์กร การพัฒนาระบบปัญญาประดิษฐ์หรือระบบอัจฉริยะตามบริบทงานจริง การควบคุมรุ่นและการทำงานร่วมกับทีมพัฒนา การใช้ข้อมูลขององค์กรอย่างมีจริยธรรมและรักษาความลับ และการรายงานความก้าวหน้าต่ออาจารย์นิเทศและพี่เลี้ยง', 'Analysis of problems and requirements from the host organization; work planning and time management under organizational constraints; design and development of AI or intelligent systems in a real work context; ethical and confidential use of organizational data and resources; testing, delivery, and handover to users; progress reporting and presentation to the academic supervisor and workplace mentor; joint assessment by the university and the host organization'),
  ('EN-714-16003', 'AISE-2570', 'elec', 'CWIE 3', 'การเรียนรู้ร่วมการทำงานด้านวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ 3', 'Work-Integrated Learning in Artificial Intelligence and Intelligent System Engineering 3', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การวางแผนและดำเนินการทดสอบระบบในสภาพใช้งานจริง การทวนสอบผลลัพธ์กับข้อกำหนดและเกณฑ์การยอมรับ การประเมินสมรรถนะ ความน่าเชื่อถือ และความปลอดภัยของระบบ การวิเคราะห์และแก้ไขข้อบกพร่องร่วมกับทีม การจัดทำหลักฐานคุณภาพและธรรมาภิบาลของระบบ และการรายงานความก้าวหน้าต่ออาจารย์นิเทศและพี่เลี้ยง', 'Analysis of problems and requirements from the host organization; work planning and time management under organizational constraints; design and development of AI or intelligent systems in a real work context; ethical and confidential use of organizational data and resources; testing, delivery, and handover to users; progress reporting and presentation to the academic supervisor and workplace mentor; joint assessment by the university and the host organization'),
  ('EN-714-16004', 'AISE-2570', 'elec', 'CWIE 4', 'การเรียนรู้ร่วมการทำงานด้านวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ 4', 'Work-Integrated Learning in Artificial Intelligence and Intelligent System Engineering 4', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การนำระบบขึ้นใช้งานในสภาพแวดล้อมขององค์กร การบูรณาการกับระบบเดิมและการจัดการการเปลี่ยนแปลง การจัดทำเอกสารระบบและคู่มือการใช้งาน การส่งมอบและถ่ายทอดงานแก่ผู้ใช้และทีมผู้ดูแล การประเมินการยอมรับของผู้ใช้ และการรายงานความก้าวหน้าต่ออาจารย์นิเทศและพี่เลี้ยง', 'Analysis of problems and requirements from the host organization; work planning and time management under organizational constraints; design and development of AI or intelligent systems in a real work context; ethical and confidential use of organizational data and resources; testing, delivery, and handover to users; progress reporting and presentation to the academic supervisor and workplace mentor; joint assessment by the university and the host organization'),
  ('EN-714-16005', 'AISE-2570', 'elec', 'CWIE 5', 'การเรียนรู้ร่วมการทำงานด้านวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ 5', 'Work-Integrated Learning in Artificial Intelligence and Intelligent System Engineering 5', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การติดตามและดูแลระบบที่ส่งมอบแล้วในการปฏิบัติงานจริง การเฝ้าระวังสมรรถนะและการเสื่อมของตัวแบบ การบำรุงรักษาและปรับปรุงระบบอย่างต่อเนื่อง การประเมินคุณค่าที่ระบบสร้างให้องค์กร การสรุปบทเรียนและข้อเสนอแนะเชิงพัฒนา และการประเมินผลร่วมกับสถานประกอบการ', 'Analysis of problems and requirements from the host organization; work planning and time management under organizational constraints; design and development of AI or intelligent systems in a real work context; ethical and confidential use of organizational data and resources; testing, delivery, and handover to users; progress reporting and presentation to the academic supervisor and workplace mentor; joint assessment by the university and the host organization'),
  ('EN-714-14051', 'AISE-2570', 'elec', 'Special Topics 1', 'หัวข้อพิเศษด้านเทคโนโลยีเกิดใหม่ทางปัญญาประดิษฐ์และระบบอัจฉริยะ 1', 'Special Topics in Emerging Artificial Intelligence and Intelligent System Technologies 1', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หัวข้อคัดสรรด้านเทคโนโลยีปัญญาประดิษฐ์และระบบอัจฉริยะที่เกิดใหม่ในขณะนั้น หลักการและสถาปัตยกรรมของเทคโนโลยีที่ศึกษา การทดลองใช้เครื่องมือและกรอบงานร่วมสมัย การวิเคราะห์ข้อจำกัด ความเสี่ยง และความเหมาะสมกับบริบทเกษตร อุตสาหกรรม หรือองค์กร การพัฒนาชิ้นงานหรือกรณีศึกษาเชิงประจักษ์ และการประเมินแนวโน้มการนำไปใช้จริง', 'Selected topics in emerging artificial intelligence and intelligent system technologies; principles and architectures of the technology under study; hands-on experimentation with contemporary tools and frameworks; analysis of limitations, risks, and suitability for agricultural, industrial, or enterprise contexts; development of an artifact or empirical case study; assessment of adoption trends; the course outline must be approved by the curriculum committee before each offering'),
  ('EN-714-14052', 'AISE-2570', 'elec', 'Special Topics 2', 'หัวข้อพิเศษด้านเทคโนโลยีเกิดใหม่ทางปัญญาประดิษฐ์และระบบอัจฉริยะ 2', 'Special Topics in Emerging Artificial Intelligence and Intelligent System Technologies 2', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หัวข้อคัดสรรด้านเทคโนโลยีปัญญาประดิษฐ์และระบบอัจฉริยะที่เกิดใหม่ในขณะนั้น หลักการและสถาปัตยกรรมของเทคโนโลยีที่ศึกษา การทดลองใช้เครื่องมือและกรอบงานร่วมสมัย การวิเคราะห์ข้อจำกัด ความเสี่ยง และความเหมาะสมกับบริบทเกษตร อุตสาหกรรม หรือองค์กร การพัฒนาชิ้นงานหรือกรณีศึกษาเชิงประจักษ์ และการประเมินแนวโน้มการนำไปใช้จริง โดยหัวข้อที่เปิดสอนต้องไม่ซ้ำกับหัวข้อของ EN-714-14051', 'Selected topics in emerging artificial intelligence and intelligent system technologies; principles and architectures of the technology under study; hands-on experimentation with contemporary tools and frameworks; analysis of limitations, risks, and suitability for agricultural, industrial, or enterprise contexts; development of an artifact or empirical case study; assessment of adoption trends; and the course outline must be approved by the curriculum committee before each offering, with a topic that does not duplicate that of EN-714-14051'),
  ('EN-714-12017', 'AISE-2570', 'proj', 'Seminar', 'สัมมนาวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ', 'Seminar in Artificial Intelligence Engineering and Intelligent Systems', '1(0-2-1)', 1, 0, 2, 1, 3, 5, false, 'แนวโน้มและเทคโนโลยีอุบัติใหม่ด้านปัญญาประดิษฐ์ กรณีศึกษาการประยุกต์ใช้ในภาคเกษตรกรรม อุตสาหกรรม และธุรกิจ การสืบค้น ประเมิน และวิจารณ์บทความวิชาการ การเปรียบเทียบแนวทางและระบุข้อจำกัดของเทคโนโลยี ผลกระทบด้านเทคนิค จริยธรรม และอุตสาหกรรม ความซื่อสัตย์ทางวิชาการ และการจัดทำรายงานและนำเสนอเชิงวิชาชีพทั้งภาษาไทยและภาษาอังกฤษ', 'Trends and emerging technologies in artificial intelligence at national and international levels; case studies in agriculture, industry, and business innovation; literature searching, evaluation, and critique; comparison of approaches and identification of technological limitations; consideration of technical, ethical, and industrial implications; academic integrity; academic reporting and professional presentation in Thai and English; preparation of an individual development plan for selecting professional electives and cooperative-education workplaces'),
  ('EN-714-12018', 'AISE-2570', 'proj', 'Project Prep', 'การเตรียมความพร้อมโครงงานวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ', 'Artificial Intelligence Engineering and Intelligent Systems Project Preparation', '1(0-2-1)', 1, 0, 2, 1, 3, 6, false, 'การระบุปัญหาจริงจากภาคอุตสาหกรรม เกษตรกรรม องค์กร หรือชุมชน การวิเคราะห์ผู้มีส่วนได้ส่วนเสียและข้อกำหนด การกำหนดขอบเขต วัตถุประสงค์ และเกณฑ์การยอมรับ การออกแบบแนวทางวิศวกรรม วิธีทดลอง และแผนทดสอบ การประเมินความเป็นไปได้ งบประมาณ และความยั่งยืนตามโมเดลเศรษฐกิจบีซีจี และการนำเสนอข้อเสนอโครงงานเพื่อขออนุมัติ', 'Identification of real problems from industry, agriculture, enterprise, or community; stakeholder and requirements analysis; definition of scope, objectives, acceptance criteria, and track-specific indicators; literature and technology review; design of engineering approaches, experimental methods, and test plans; assessment of feasibility, budget, and sustainability under the BCG economic model; planning for quality, safety, ethics, and risk; preparation and presentation of the project proposal for approval'),
  ('EN-714-12020', 'AISE-2570', 'proj', 'WIL Capstone', 'โครงงานบูรณาการกับสถานประกอบการทางวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ', 'Workplace-Integrated Capstone Project in Artificial Intelligence and Intelligent System Engineering', '3(1-4-4)', 3, 1, 6, 5, 4, 7, false, 'การดำเนินโครงงานจากโจทย์จริงของสถานประกอบการ การทวนสอบปัญหาและเกณฑ์การยอมรับร่วมกับสถานประกอบการ การออกแบบ พัฒนา และบูรณาการระบบภายใต้ข้อจำกัดด้านข้อมูลและทรัพยากรขององค์กร การทดลองเพื่อประเมินสมรรถนะและความปลอดภัย การบริหารความเสี่ยงร่วมกับพี่เลี้ยง การรักษาความลับและธรรมาภิบาลข้อมูล และการสอบป้องกันต่อคณะกรรมการร่วม', 'Execution of an AI or intelligent-systems project on a real problem from the host organization; verification of the problem, requirements, and acceptance criteria jointly with the organization; design, development, and integration under the organization''s data, time, and resource constraints; design and conduct of experiments to evaluate performance, reliability, and safety; project and risk management with the workplace mentor; preparation of ethics, confidentiality, and data-governance evidence; demonstration and defense before a joint university-industry committee'),
  ('EN-714-12019', 'AISE-2570', 'proj', 'Capstone', 'โครงงานวิศวกรรมปัญญาประดิษฐ์และระบบอัจฉริยะ', 'Artificial Intelligence Engineering and Intelligent Systems Project', '3(1-4-4)', 3, 1, 6, 5, 4, 7, false, 'การดำเนินโครงงานวิศวกรรมปัญญาประดิษฐ์หรือระบบอัจฉริยะที่ได้รับอนุมัติ การทวนสอบปัญหา ข้อกำหนด และเกณฑ์การยอมรับ การออกแบบ พัฒนา และบูรณาการข้อมูล ปัญญาประดิษฐ์ ซอฟต์แวร์ อุปกรณ์ตรวจวัด หรือระบบควบคุม การทดลองเพื่อประเมินสมรรถนะ ความน่าเชื่อถือ และความปลอดภัย การบริหารโครงงานและความเสี่ยง และการสาธิตและสอบป้องกันต่อคณะกรรมการ', 'Execution of an approved AI or intelligent-systems project; verification of the problem, requirements, and acceptance criteria; design, development, and integration of data, AI, software, sensing devices, or control systems as appropriate; design and conduct of experiments to evaluate performance, reliability, and safety; iterative system improvement; project and risk management; preparation of ethics and governance evidence; demonstration and defense before the committee'),
  ('EN-714-17001', 'AISE-2570', 'field', 'Co-op Prep', 'เตรียมความพร้อมสหกิจศึกษา', 'Cooperative Education Preparation', '1(0-2-1)', 1, 0, 2, 1, 3, 5, false, 'ปรัชญา เป้าประสงค์ ระเบียบ และขั้นตอนของสหกิจศึกษา การค้นหาและเลือกสถานประกอบการที่เหมาะสม การจัดทำประวัติย่อ แฟ้มสะสมทักษะ และการสัมภาษณ์ทั้งภาษาไทยและภาษาอังกฤษ จรรยาบรรณวิชาชีพ กฎหมายแรงงาน ทรัพย์สินทางปัญญา ธรรมาภิบาลปัญญาประดิษฐ์ และความปลอดภัยในการทำงาน และการจัดทำแผนปฏิบัติงานและรูปแบบรายงานสหกิจศึกษา', 'Philosophy, objectives, regulations, and procedures of cooperative education; identifying and selecting workplaces in AI engineering, agriculture, industry, or enterprise; preparation of resumes, skill portfolios, and interviews in Thai and English; professional ethics, labor law, intellectual property, AI governance, and workplace safety; communication and teamwork; preparation of the work plan and cooperative-education report format'),
  ('EN-714-17002', 'AISE-2570', 'field', 'Co-op', 'สหกิจศึกษา', 'Cooperative Education', '6(0-40-0)', 6, 0, 40, 0, 4, 8, false, 'การปฏิบัติงานจริงในสถานประกอบการที่ได้รับอนุมัติไม่น้อยกว่าสิบหกสัปดาห์ การวิเคราะห์ปัญหา ข้อกำหนด และเกณฑ์การยอมรับของงาน การประยุกต์และบูรณาการความรู้ด้านวิศวกรรมและปัญญาประดิษฐ์ การเก็บข้อมูล ทดลอง และตีความผล การทำงานร่วมกับทีมสหวิทยาการ การบริหารงานและความเสี่ยง การปฏิบัติตามจรรยาบรรณและธรรมาภิบาล และการจัดทำรายงาน', 'Supervised professional practice in an approved workplace for at least sixteen weeks; analysis of the assigned problem, requirements, and acceptance criteria; application and integration of engineering and AI knowledge; data collection, experimentation, and interpretation of results; collaboration in a multidisciplinary team; management of work and risk; compliance with professional ethics and governance; preparation of the cooperative-education report'),
  ('EN-714-12016', 'AISE-2570', 'track', 'Workshop 5', 'ปฏิบัติการวิศวกรรมเชิงบูรณาการ 5: ระบบอัตโนมัติและการผลิตอัจฉริยะ', 'Integrated Engineering Workshop 5: Industrial Automation and Smart Manufacturing', '1(0-2-1)', 1, 0, 3, 2, 3, 6, false, 'การเขียนโปรแกรมตัวควบคุมแบบโปรแกรมได้ด้วยภาษาแลดเดอร์และฟังก์ชันบล็อก การต่อสัญญาณอินพุตและเอาต์พุตแบบดิจิทัลและแอนะล็อก การตั้งค่าส่วนต่อประสานมนุษย์กับเครื่องจักรและระบบสกาดา การเชื่อมต่อเซนเซอร์และอุปกรณ์ภาคสนามเข้ากับระบบควบคุม การทดสอบเซลล์หุ่นยนต์ การตรวจสอบความปลอดภัย และการจัดทำเอกสารส่งมอบ', 'Programming of programmable logic controllers with ladder and function block languages; wiring of digital and analog input and output signals; configuration of human-machine interfaces and SCADA; connection of sensors and field devices to control systems; robotic-cell testing; analysis of overall equipment effectiveness; safety verification; and handover documentation'),
  ('EN-714-14001', 'AISE-2570', 'elec', 'เกษตร-ชลประทาน', 'เกษตรกรรมอัจฉริยะและการจัดชลประทาน', 'Smart Agriculture and Irrigation Management', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการเกษตรกรรมอัจฉริยะและการเกษตรแม่นยำ การวิเคราะห์และจัดการทรัพยากรดินและน้ำด้วยปัญญาประดิษฐ์ การออกแบบระบบชลประทานอัจฉริยะทั้งน้ำหยดและสปริงเกลอร์ การตรวจวัดความชื้นดินด้วยเซนเซอร์และไอโอที การพยากรณ์ความต้องการน้ำของพืชด้วยการเรียนรู้ของเครื่อง การควบคุมการให้น้ำอัตโนมัติ และระบบเตือนภัยแล้งและน้ำท่วม', 'Principles of smart and precision agriculture; analysis and management of soil and water resources with AI; design of smart irrigation systems including drip and sprinkler systems; soil-moisture measurement with sensors and IoT; crop water-demand forecasting with machine learning; automatic irrigation control and water conservation; drought and flood warning systems; and water management at plot and watershed levels'),
  ('EN-714-14002', 'AISE-2570', 'elec', 'AI เกษตรแม่นยำ', 'ปัญญาประดิษฐ์สำหรับเกษตรกรรมแม่นยำ', 'Artificial Intelligence for Precision Agriculture', '3(3-0-6)', 3, 3, 0, 6, NULL, NULL, false, 'แนวคิดเกษตรกรรมแม่นยำ การประยุกต์ใช้ปัญญาประดิษฐ์ในการผลิตพืชและปศุสัตว์ การจัดการและวิเคราะห์ข้อมูลจากเซนเซอร์ดิน สภาพอากาศ ดาวเทียม และอากาศยานไร้คนขับ การแนะนำการจัดการธาตุอาหารพืช การตรวจจับโรคพืชและแมลงศัตรูพืชด้วยคอมพิวเตอร์วิทัศน์และการเรียนรู้เชิงลึก และการพยากรณ์ผลผลิตและการวางแผนการผลิต', 'Principles and concepts of precision agriculture; application of AI to crop and livestock production; management and analysis of data from soil sensors, weather, satellites, and unmanned aerial imagery; crop-nutrient management recommendations; detection and classification of plant diseases and pests with computer vision and deep learning; yield forecasting and production planning; farm recommendation systems integrating multiple data sources'),
  ('EN-714-14003', 'AISE-2570', 'elec', 'GIS เกษตร', 'ระบบสารสนเทศภูมิศาสตร์และการวิเคราะห์พื้นที่ทางการเกษตร', 'Geographic Information Systems and Spatial Analysis for Agriculture', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการและองค์ประกอบของระบบสารสนเทศภูมิศาสตร์ ข้อมูลเชิงพื้นที่และระบบพิกัดอ้างอิง การจัดการและวิเคราะห์ข้อมูลแบบเวกเตอร์และแรสเตอร์ การประมวลผลข้อมูลจากดาวเทียมและภาพถ่ายทางอากาศ การวิเคราะห์พื้นที่ด้วยวิธีซ้อนทับ บัฟเฟอร์ และเครือข่าย และการประยุกต์วางแผนการใช้ที่ดินและประเมินความเหมาะสมของพื้นที่ปลูกพืช', 'Principles and components of geographic information systems; spatial data and reference coordinate systems; management and analysis of vector and raster data; creation and analysis of digital maps; processing of satellite and aerial imagery; spatial analysis with overlay, buffer, and network analysis; integration with machine learning for advanced spatial analysis; applications to agricultural land-use planning and crop-area suitability assessment'),
  ('EN-714-14004', 'AISE-2570', 'elec', 'หลังการเก็บเกี่ยว', 'เทคโนโลยีและนวัตกรรมการจัดการหลังการเก็บเกี่ยว', 'Postharvest Management Technology and Innovation', '3(3-0-6)', 3, 3, 0, 6, NULL, NULL, false, 'หลักการและกระบวนการจัดการผลผลิตเกษตรหลังการเก็บเกี่ยว สรีรวิทยาของผลผลิตหลังการเก็บเกี่ยว การสูญเสียผลผลิตและแนวทางการลดความสูญเสีย การคัดแยกและคัดเกรดด้วยคอมพิวเตอร์วิทัศน์ ระบบอบแห้งและการเก็บรักษาอัจฉริยะ การควบคุมอุณหภูมิและความชื้นในโรงเก็บด้วยไอโอที และระบบตรวจสอบย้อนกลับและการรับรองคุณภาพผลผลิต', 'Principles and processes of postharvest management; physiology and biochemistry of harvested produce; produce losses and loss-reduction approaches; sorting and grading with computer vision; smart drying and storage systems; temperature and humidity control in storage with IoT; smart packaging and shelf-life extension; and traceability and produce-quality certification systems'),
  ('EN-714-14005', 'AISE-2570', 'elec', 'พยากรณ์ฟาร์ม', 'การพยากรณ์และวิเคราะห์ข้อมูลฟาร์มด้วยปัญญาประดิษฐ์', 'AI-Based Farm Data Forecasting and Analytics', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการและวิธีการพยากรณ์ข้อมูลทางการเกษตรด้วยปัญญาประดิษฐ์ การจัดการข้อมูลขนาดใหญ่จากเครือข่ายเซนเซอร์ในฟาร์ม การวิเคราะห์อนุกรมเวลาสำหรับข้อมูลผลผลิตและสภาพอากาศ การสร้างตัวแบบพยากรณ์ผลผลิตด้วยการเรียนรู้เชิงลึก การพยากรณ์ราคาสินค้าเกษตร การวิเคราะห์ความเสี่ยง และการประเมินความถูกต้องของตัวแบบพยากรณ์', 'Principles and methods of forecasting agricultural data with AI; collection and management of big data from farm sensor networks; time-series analysis of yield and weather data; yield-forecasting models with deep learning; agricultural price forecasting and production planning; risk and uncertainty analysis; design of farm data dashboards; and validation of forecasting models'),
  ('EN-714-14006', 'AISE-2570', 'elec', 'Plant Factory', 'โรงงานผลิตพืชอัจฉริยะและเกษตรกรรมแนวดิ่ง', 'Smart Plant Factories and Vertical Farming', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'โรงงานผลิตพืชปิดและเกษตรกรรมแนวดิ่ง สถาปัตยกรรมและองค์ประกอบของโรงงานผลิตพืช ระบบแสงเทียมแอลอีดีและการควบคุมสเปกตรัมแสงด้วยปัญญาประดิษฐ์ ระบบปลูกพืชโดยไม่ใช้ดิน การควบคุมสภาพแวดล้อมในโรงเรือนอัตโนมัติ การตรวจสอบสุขภาพพืชด้วยคอมพิวเตอร์วิทัศน์ และการวิเคราะห์ต้นทุนและผลตอบแทนของการลงทุน', 'Principles and concepts of closed plant factories and vertical farming; architecture and components of plant factories; LED artificial lighting and AI-based light-spectrum control; soilless cultivation with hydroponics, aeroponics, and aquaponics; automated greenhouse environmental control; crop-health monitoring with computer vision; energy conservation and resource management; cost-benefit analysis of investment'),
  ('EN-714-14007', 'AISE-2570', 'elec', 'ปศุสัตว์อัจฉริยะ', 'เทคโนโลยีปัญญาประดิษฐ์เพื่อการปศุสัตว์อัจฉริยะ', 'Artificial Intelligence Technology for Smart Livestock', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การปศุสัตว์อัจฉริยะ การติดตามสุขภาพสัตว์ด้วยไอโอทีและเซนเซอร์สวมใส่ การวิเคราะห์พฤติกรรมสัตว์ด้วยคอมพิวเตอร์วิทัศน์ การพยากรณ์และตรวจจับโรคสัตว์ด้วยการเรียนรู้ของเครื่อง ระบบให้อาหารอัตโนมัติและการจัดการโภชนาการ การจัดการสภาพแวดล้อมในโรงเรือน และระบบตรวจสอบย้อนกลับผลิตภัณฑ์ปศุสัตว์', 'Principles and concepts of smart livestock farming; animal-health monitoring with IoT and wearable sensors; animal-behavior analysis with computer vision; disease prediction and detection with machine learning; automatic feeding systems and nutrition management; environmental management of livestock housing; herd tracking with GPS; analysis of farm efficiency; and livestock-product traceability systems'),
  ('EN-714-14008', 'AISE-2570', 'elec', 'CV คัดเกรดเกษตร', 'คอมพิวเตอร์วิทัศน์สำหรับการจำแนกและคัดเกรดทางการเกษตร', 'Computer Vision for Agricultural Classification and Grading', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'คอมพิวเตอร์วิทัศน์สำหรับการจำแนกและคัดเกรดผลผลิตเกษตร การออกแบบระบบกล้องและแสง การสร้างและจัดการชุดข้อมูลภาพเพื่อฝึกตัวแบบ การฝึกและปรับแต่งตัวแบบการเรียนรู้เชิงลึกเพื่อจำแนกประเภทและตรวจจับตำหนิ การวัดขนาดด้วยการประมวลผลภาพ การใช้ภาพหลายช่วงคลื่นประเมินคุณภาพภายใน และการบูรณาการกับระบบคัดแยกอัตโนมัติ', 'Principles of computer vision for classification and grading of agricultural produce; design of camera and lighting systems for produce inspection; creation and management of image datasets for model training; training and fine-tuning of deep learning models for classification and defect detection; size and weight measurement through image processing; multispectral imaging and near-infrared spectroscopy for internal quality assessment with laboratory calibration; development of purpose-built applications; and integration with automatic sorting systems'),
  ('EN-714-14009', 'AISE-2570', 'elec', 'ML เซนเซอร์ฟาร์ม', 'การเรียนรู้ของเครื่องและการวิเคราะห์ข้อมูลเซนเซอร์ในฟาร์ม', 'Machine Learning and Farm Sensor Data Analytics', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการและสถาปัตยกรรมของเครือข่ายเซนเซอร์ในฟาร์ม การเก็บและส่งข้อมูลจากเซนเซอร์ดิน น้ำ อากาศ และพืช การประมวลผลและกรองสัญญาณรบกวน การเตรียมข้อมูลเซนเซอร์เพื่อการวิเคราะห์ การวิเคราะห์อนุกรมเวลาและการหารูปแบบ การสร้างตัวแบบเพื่อการพยากรณ์และการตัดสินใจ และการตรวจจับความผิดปกติพร้อมแสดงผลผ่านแผงควบคุม', 'Principles and architecture of farm sensor networks; collection and transmission of soil, water, air, and crop sensor data; signal processing and noise filtering; cleaning and preparation of sensor data for analysis; time-series analysis and pattern discovery; machine learning models for forecasting and decision-making; anomaly detection and smart alerting; visualization of sensor data through dashboards'),
  ('EN-714-14010', 'AISE-2570', 'elec', 'จัดการผลิตพืช AI', 'การจัดการการผลิตพืชอัจฉริยะด้วยปัญญาประดิษฐ์', 'Artificial Intelligence for Smart Crop Production Management', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การผลิตพืชอัจฉริยะ การวิเคราะห์สมบัติของดินและการประเมินความอุดมสมบูรณ์ การวางแผนการใช้ปุ๋ยเฉพาะพื้นที่ การจัดการน้ำและการให้น้ำอย่างแม่นยำ การใช้ข้อมูลจากเซนเซอร์และอากาศยานไร้คนขับติดตามการเจริญเติบโต การวิเคราะห์โรคพืชด้วยการเรียนรู้เชิงลึก และการพัฒนาระบบสนับสนุนการตัดสินใจด้วยปัญญาประดิษฐ์เชิงสร้าง', 'Principles and concepts of smart crop production; soil-property analysis and fertility assessment; crop-nutrient analysis and site-specific fertilizer planning; water management and precision irrigation; use of sensor, IoT, and unmanned aerial imagery to monitor crop growth; analysis of plant diseases and pests with deep learning; yield forecasting and production-cost analysis; development of decision-support systems with generative AI'),
  ('EN-714-14011', 'AISE-2570', 'elec', 'หุ่นยนต์เกษตร', 'หุ่นยนต์และระบบอัตโนมัติทางการเกษตร', 'Agricultural Robotics and Automation', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หุ่นยนต์และระบบอัตโนมัติทางการเกษตร องค์ประกอบของระบบหุ่นยนต์ทั้งเซนเซอร์ ตัวกระตุ้น และระบบควบคุม การประยุกต์ใช้ปัญญาประดิษฐ์และคอมพิวเตอร์วิทัศน์ในหุ่นยนต์เกษตร การนำทางอัตโนมัติและการวางแผนเส้นทาง การพ่นสาร การกำจัดวัชพืช และการเก็บเกี่ยว และการบูรณาการหุ่นยนต์เข้ากับระบบฟาร์มอัจฉริยะ', 'Principles of agricultural robotics and automation; components of robotic systems including sensors, actuators, and control systems; application of AI and computer vision in agricultural robots; autonomous navigation, localization, and path planning; field data collection, spraying, fertilizing, weeding, and harvesting; use of robotic arms and mobile robots; integration of robots with unmanned aerial vehicles and smart-farm systems'),
  ('EN-714-14012', 'AISE-2570', 'elec', 'UAV/Remote เกษตร', 'เทคโนโลยีอากาศยานไร้คนขับและการสำรวจระยะไกลเพื่อการเกษตร', 'UAV Technology and Remote Sensing for Agriculture', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการทำงานและประเภทของอากาศยานไร้คนขับ การวางแผนเส้นทางการบินเพื่อการสำรวจทางการเกษตร การใช้เซนเซอร์ภาพหลายช่วงคลื่นและภาพความร้อนติดตามความสมบูรณ์ของพืช การวิเคราะห์ภาพถ่ายทางอากาศด้วยการเรียนรู้ของเครื่อง การจัดทำแผนที่ดัชนีพืชพรรณและการให้ปัจจัยการผลิตแบบผันแปร และกฎหมาย ใบอนุญาต และความปลอดภัยในการใช้งาน', 'Working principles and types of unmanned aerial vehicles; flight-path planning for agricultural surveying; multispectral and thermal imaging sensors to monitor crop health; processing and analysis of aerial imagery with machine learning; classification of soil properties and moisture for variable-rate input maps; creation of vegetation-index maps; precision liquid spraying; aircraft inspection and maintenance; laws, licensing, and operational safety'),
  ('EN-714-14013', 'AISE-2570', 'elec', 'ห่วงโซ่อุปทานเกษตร', 'การจัดการห่วงโซ่อุปทานสินค้าเกษตรด้วยเทคโนโลยีอัจฉริยะ', 'Smart Agricultural Supply Chain Management', '3(3-0-6)', 3, 3, 0, 6, NULL, NULL, false, 'หลักการจัดการห่วงโซ่อุปทานและโลจิสติกส์สำหรับสินค้าเกษตร การใช้ปัญญาประดิษฐ์วางแผนการจัดหาและการกระจายผลผลิต การจัดการคลังสินค้าเกษตรอัจฉริยะด้วยไอโอที การตรวจสอบย้อนกลับด้วยเทคโนโลยีบล็อกเชน การพยากรณ์ความต้องการของตลาดเพื่อลดความสูญเสียอาหาร และการจัดเส้นทางการขนส่งเพื่อความโปร่งใสและความยั่งยืน', 'Principles of supply-chain and logistics management for agricultural goods; use of AI in planning produce sourcing and distribution; smart agricultural warehouse management with IoT; produce tracking and traceability with blockchain; market-demand forecasting with machine learning to reduce food loss; efficient transport routing; and technology integration for transparency and sustainability'),
  ('EN-714-14014', 'AISE-2570', 'elec', 'AI เทคโนชีวภาพเกษตร', 'การประยุกต์ใช้ปัญญาประดิษฐ์ในเทคโนโลยีชีวภาพการเกษตร', 'AI Applications in Agricultural Biotechnology', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'ความสัมพันธ์ระหว่างปัญญาประดิษฐ์และเทคโนโลยีชีวภาพการเกษตร การใช้การเรียนรู้ของเครื่องวิเคราะห์ข้อมูลพันธุกรรมพืชและสัตว์ การวิเคราะห์ลำดับดีเอ็นเอเพื่อคัดเลือกสายพันธุ์ที่ทนทาน การใช้ปัญญาประดิษฐ์ค้นหาสารออกฤทธิ์ทางชีวภาพเพื่อใช้เป็นชีวภัณฑ์ และจริยธรรมและความปลอดภัยทางชีวภาพ', 'The relationship between artificial intelligence and agricultural biotechnology; machine learning for analyzing plant and animal genetic data; DNA-sequence analysis for selecting disease- and climate-resistant varieties; AI-based discovery of bioactive compounds for agricultural bio-products; simulation and prediction of interactions between organisms and their environment; and ethics and biosafety'),
  ('EN-714-14015', 'AISE-2570', 'elec', 'ความเสี่ยง/ภูมิอากาศ AI', 'การจัดการความเสี่ยงทางการเกษตรและการเปลี่ยนแปลงสภาพภูมิอากาศด้วยปัญญาประดิษฐ์', 'Agricultural Risk and Climate Change Management with AI', '3(3-0-6)', 3, 3, 0, 6, NULL, NULL, false, 'ผลกระทบของการเปลี่ยนแปลงสภาพภูมิอากาศต่อการเกษตร การประยุกต์ใช้ปัญญาประดิษฐ์วิเคราะห์ข้อมูลภูมิอากาศขนาดใหญ่ การพยากรณ์สภาพอากาศสุดขั้ว ภัยแล้ง และอุทกภัย การประเมินความเสี่ยงต่อผลผลิตด้วยตัวแบบคอมพิวเตอร์ การออกแบบระบบเตือนภัยล่วงหน้า กลยุทธ์การปรับตัวของภาคการเกษตร และการประกันภัยพืชผลด้วยข้อมูลดาวเทียม', 'Impacts of climate change on agriculture; application of AI to large-scale climate data analysis; forecasting of extreme weather, drought, and flooding; risk analysis and assessment for agricultural yields with computer models; design of smart early-warning systems; adaptation strategies for the agricultural sector; satellite- and AI-based crop insurance; agricultural policy and sustainability'),
  ('EN-714-14016', 'AISE-2570', 'elec', 'Advanced Control/DCS', 'การควบคุมกระบวนการขั้นสูงและระบบควบคุมแบบกระจาย', 'Advanced Process Control and Distributed Control Systems', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การสร้างแบบจำลองพลวัตและการระบุระบบของกระบวนการอุตสาหกรรม การวิเคราะห์เสถียรภาพของวงควบคุม การปรับตั้งตัวควบคุมพีไอดีขั้นสูง การควบคุมแบบป้อนไปข้างหน้าและแบบหลายตัวแปร การควบคุมเชิงทำนายด้วยแบบจำลอง สถาปัตยกรรมระบบควบคุมแบบกระจายและการจัดการสัญญาณเตือน และการเชื่อมต่อกับสกาดาพร้อมประเมินสมรรถนะ', 'Dynamic modeling and system identification of industrial processes; control-loop stability analysis; advanced PID tuning; feedforward and multivariable control; model-predictive control and AI-assisted process control; distributed control system architecture; alarm management; integration with SCADA and manufacturing execution systems; and commissioning and performance evaluation'),
  ('EN-714-14017', 'AISE-2570', 'elec', 'Predictive Maintenance', 'การบำรุงรักษาเชิงพยากรณ์และป้องกันด้วยปัญญาประดิษฐ์', 'AI-Based Predictive and Preventive Maintenance', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการและกลยุทธ์การบำรุงรักษาเครื่องจักรเชิงแก้ไข เชิงป้องกัน และเชิงพยากรณ์ การเก็บข้อมูลการสั่นสะเทือน เสียง และอุณหภูมิ การประมวลผลสัญญาณและการสกัดคุณลักษณะเพื่อวินิจฉัยเครื่องจักร ตัวแบบการเรียนรู้ของเครื่องเพื่อตรวจจับความผิดปกติและพยากรณ์ความเสียหาย ดิจิทัลทวินสำหรับจำลองสภาพเครื่องจักร และการวางแผนบำรุงรักษาอัตโนมัติ', 'Principles and strategies of corrective, preventive, and predictive maintenance for industrial machinery; collection of vibration, acoustic, temperature, and current signals; signal processing and feature extraction for machine diagnosis; machine learning models for anomaly detection and failure prediction; digital twins for simulating machine condition; automatic alerting and maintenance planning; return-on-investment assessment'),
  ('EN-714-14018', 'AISE-2570', 'elec', 'คลังสินค้าอัจฉริยะ', 'การออกแบบและการจัดการคลังสินค้าอัจฉริยะ', 'Smart Warehouse Design and Management', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการและประเภทของระบบคลังสินค้าอัตโนมัติ การออกแบบและวางผังคลังสินค้าสำหรับโรงงานเกษตรอุตสาหกรรม ระบบจัดเก็บและเรียกคืนสินค้าอัตโนมัติ สายพานลำเลียง และรถลำเลียงอัตโนมัติ การใช้คอมพิวเตอร์วิทัศน์ตรวจสอบและคัดแยกสินค้า การติดตามสินค้าด้วยอาร์เอฟไอดี และการจัดการสินค้าคงคลังด้วยปัญญาประดิษฐ์', 'Principles and types of automated warehouse systems; warehouse design and layout for agro-industrial plants; automated storage and retrieval systems, conveyors, and automated guided vehicles; computer vision for goods inspection and sorting; warehouse management systems; goods tracking with RFID and barcodes; AI-based inventory management; optimization of goods flow through simulation'),
  ('EN-714-14019', 'AISE-2570', 'elec', 'Advanced OR/Optimization', 'การวิจัยดำเนินงานขั้นสูงและการหาค่าเหมาะที่สุดทางอุตสาหกรรม', 'Advanced Operations Research and Industrial Optimization', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การสร้างตัวแบบเพื่อการตัดสินใจทางอุตสาหกรรม การโปรแกรมเชิงเส้น จำนวนเต็มผสม ไม่เชิงเส้น และหลายวัตถุประสงค์ ตัวแบบโครงข่ายและการขนส่ง การจัดสรรทรัพยากร การจัดตารางการผลิต และการวางแผนสินค้าคงคลัง ทฤษฎีแถวคอยและการจำลองเหตุการณ์ไม่ต่อเนื่อง วิธีฮิวริสติกและเมตาฮิวริสติก และการใช้ซอฟต์แวร์ตัวแก้ปัญหาวิเคราะห์ความไว', 'Industrial decision modeling; linear, mixed-integer, nonlinear, and multi-objective programming; network and transportation models; resource allocation, production scheduling, and inventory planning; queueing theory and discrete-event simulation; stochastic and robust optimization; heuristic and metaheuristic methods; Python and optimization solvers; sensitivity analysis for comparing alternatives'),
  ('EN-714-14020', 'AISE-2570', 'elec', 'อุตฯเกษตรแปรรูป', 'เทคโนโลยีอุตสาหกรรมเกษตรและการแปรรูป', 'Agro-Industrial and Processing Technology', '3(3-0-6)', 3, 3, 0, 6, NULL, NULL, false, 'หลักการและกระบวนการแปรรูปผลผลิตเกษตรในภาคอุตสาหกรรม มาตรฐานคุณภาพและความปลอดภัยอาหารตามจีเอ็มพี เอชเอซีซีพี และไอเอสโอ 22000 เทคโนโลยีการผลิตน้ำตาล แป้งมันสำปะหลัง และการสีข้าว การจัดการของเสียและน้ำเสีย การใช้พลังงานอย่างมีประสิทธิภาพ และการประยุกต์ใช้ปัญญาประดิษฐ์เพื่อเพิ่มประสิทธิภาพและลดต้นทุน', 'Principles and processes of agricultural produce processing in industry; food quality and safety standards under GMP, HACCP, and ISO 22000; technologies for sugarcane and sugar production, cassava starch extraction, and rice milling and processing; management of waste and wastewater in agro-processing industry; energy efficiency and cogeneration systems; application of AI to improve processing efficiency and reduce cost'),
  ('EN-714-14021', 'AISE-2570', 'elec', 'โรงสีข้าวอัจฉริยะ', 'ปัญญาประดิษฐ์และการจัดการโรงสีข้าวอัจฉริยะ', 'Artificial Intelligence and Smart Rice Mill Management', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'กระบวนการสีข้าวครบวงจรตั้งแต่การรับซื้อข้าวเปลือก การทำความสะอาด การกะเทาะเปลือก การขัดขาว การคัดแยก และการบรรจุ ระบบคอมพิวเตอร์วิทัศน์ตรวจสอบคุณภาพข้าวด้านความขาว ความชื้น และเมล็ดหัก ระบบอบแห้งข้าวเปลือกอัจฉริยะ การจัดการไซโลด้วยไอโอที การบำรุงรักษาเชิงพยากรณ์ และระบบตรวจสอบย้อนกลับคุณภาพข้าว', 'The complete rice-milling process from paddy receiving, cleaning, husking, whitening, and grading to packaging; computer vision for inspecting whiteness, moisture, broken grains, and impurities; smart paddy drying with automatic moisture control; IoT-based silo management; predictive maintenance for mill machinery; digital twins and production-line simulation; rice quality traceability systems'),
  ('EN-714-14022', 'AISE-2570', 'elec', 'อ้อย-น้ำตาลอัจฉริยะ', 'เทคโนโลยีอัจฉริยะในกระบวนการผลิตอ้อยและน้ำตาล', 'Smart Technology in Sugarcane and Sugar Production Processes', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'กระบวนการผลิตน้ำตาลครบวงจรตั้งแต่การรับอ้อย การหีบอ้อย การทำความสะอาดน้ำอ้อย การต้มเคี่ยว การตกผลึก และการบรรจุ ระบบปัญญาประดิษฐ์วิเคราะห์คุณภาพอ้อยและพยากรณ์ค่าความหวานซีซีเอส การควบคุมกระบวนการหีบด้วยตัวควบคุมแบบโปรแกรมได้ ระบบผลิตพลังงานร่วมจากชีวมวล และดิจิทัลทวินสำหรับโรงงานน้ำตาล', 'The complete sugar production process from cane receiving and quality analysis through milling, juice clarification, evaporation, crystallization, and packaging; AI-based cane quality analysis and CCS sweetness forecasting at receiving points; milling control with programmable logic controllers; biomass cogeneration; management of waste and by-products; digital twins for sugar plants; sugar quality traceability systems'),
  ('EN-714-14023', 'AISE-2570', 'elec', 'มันสำปะหลัง-แป้ง', 'เทคโนโลยีอัจฉริยะในกระบวนการผลิตมันสำปะหลังและแป้ง', 'Smart Technology in Cassava and Starch Production Processes', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'กระบวนการผลิตแป้งมันสำปะหลังครบวงจรตั้งแต่การรับวัตถุดิบ การล้างและปอกเปลือก การบดและสกัดแป้ง การอบแห้ง และการบรรจุ ระบบคอมพิวเตอร์วิทัศน์สำหรับตรวจรับและพยากรณ์ปริมาณแป้ง การควบคุมกระบวนการสกัดเพื่อเพิ่มอัตราการสกัด ระบบอบแห้งอัจฉริยะและการจัดการน้ำเสีย และการผลิตแป้งดัดแปรมูลค่าสูง', 'The complete cassava-starch production process from raw-material receiving, washing and peeling, grinding and starch extraction, pulp separation, drying, and packaging; computer vision and AI for quality inspection and starch-yield forecasting; extraction control with programmable logic controllers to raise extraction rates; smart drying and energy conservation; wastewater management; digital twins for starch plants; production of modified starch and high-value products'),
  ('EN-714-14024', 'AISE-2570', 'elec', 'IoT เก็บรักษาผลผลิต', 'เทคโนโลยีอินเทอร์เน็ตของสรรพสิ่งสำหรับการเก็บรักษาผลผลิตเกษตร', 'Internet of Things Technology for Agricultural Produce Storage', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการและเทคโนโลยีไอโอทีสำหรับการเก็บรักษาผลผลิตเกษตร การออกแบบและติดตั้งเครือข่ายเซนเซอร์ในโรงเก็บ ไซโล และห้องเย็น เซนเซอร์อุณหภูมิ ความชื้น คาร์บอนไดออกไซด์ และเอทิลีน ระบบควบคุมสภาพแวดล้อมอัตโนมัติด้วยปัญญาประดิษฐ์ การพยากรณ์อายุการเก็บรักษา และการบูรณาการกับคลาวด์เพื่อการติดตามแบบเวลาจริง', 'Principles and IoT technologies for agricultural produce storage; design and installation of sensor networks in warehouses, silos, and cold rooms; temperature, humidity, carbon dioxide, oxygen, and ethylene sensors; AI-based automatic environmental control; analysis of produce quality during storage; alerting and emergency management; shelf-life forecasting with machine learning; integration with cloud platforms for real-time monitoring'),
  ('EN-714-14025', 'AISE-2570', 'elec', 'อบแห้งอัจฉริยะ', 'ระบบอบแห้งอัจฉริยะในอุตสาหกรรมเกษตร', 'Smart Drying Systems in Agro-Industry', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการถ่ายเทความร้อนและมวลสารในกระบวนการอบแห้ง สมบัติทางอุณหพลศาสตร์และการถ่ายเทความชื้นของผลผลิตเกษตร เทคโนโลยีการอบแห้งด้วยลมร้อน ไมโครเวฟ อินฟราเรด และปั๊มความร้อน การออกแบบและคำนวณระบบอบแห้ง การควบคุมกระบวนการอัตโนมัติ การตรวจวัดความชื้นแบบเวลาจริง และการเพิ่มประสิทธิภาพและประหยัดพลังงาน', 'Principles of heat and mass transfer in drying; thermodynamic properties and moisture transfer of agricultural produce; hot-air, microwave, infrared, heat-pump, and freeze drying technologies; design and calculation of drying systems; automatic process control with programmable logic controllers and AI; real-time moisture measurement; machine learning models for drying optimization; energy conservation with cogeneration systems'),
  ('EN-714-14026', 'AISE-2570', 'elec', 'ขนถ่ายวัสดุ/บรรจุภัณฑ์', 'วิศวกรรมระบบขนถ่ายวัสดุและบรรจุภัณฑ์อัตโนมัติ', 'Automated Material Handling and Packaging Systems Engineering', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการและการออกแบบระบบขนถ่ายวัสดุและบรรจุภัณฑ์สำหรับโรงงานเกษตรอุตสาหกรรม การเลือกใช้สายพานลำเลียง สกรูลำเลียง ลิฟต์ถัง และระบบลำเลียงด้วยลม การคำนวณความดันสูญเสียสำหรับวัสดุผง ความปลอดภัยจากฝุ่นระเบิด การออกแบบเครื่องจักรบรรจุภัณฑ์อัตโนมัติและการควบคุมด้วยสกาดา และการบำรุงรักษาเชิงพยากรณ์', 'Principles and design of material-handling and packaging systems for agro-industrial plants; selection of belt conveyors, screw conveyors, bucket elevators, and pneumatic conveying; calculation of pressure loss and conveying air velocity for powdered materials; dust-explosion safety and grounding; design of automatic packaging machinery; control with programmable logic controllers and SCADA; computer vision for material-flow inspection; predictive maintenance'),
  ('EN-714-14027', 'AISE-2570', 'elec', 'Motion/Cobot Cell', 'การควบคุมการเคลื่อนที่และวิศวกรรมเซลล์หุ่นยนต์ร่วมปฏิบัติงาน', 'Motion Control and Collaborative Robot Cell Engineering', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การเลือกและกำหนดขนาดมอเตอร์ เซอร์โวมอเตอร์ สเต็ปเปอร์มอเตอร์ และระบบส่งกำลัง การควบคุมตำแหน่ง ความเร็ว แรงบิด และการเคลื่อนที่หลายแกน การสร้างเส้นทางและโปรไฟล์การเคลื่อนที่ การประสานงานกับตัวควบคุมแบบโปรแกรมได้และระบบวิสัยทัศน์ หุ่นยนต์ร่วมปฏิบัติงานและการออกแบบผังเซลล์หุ่นยนต์ และการประเมินความเสี่ยงพร้อมทดสอบการยอมรับ', 'Selection and sizing of motors, servo and stepper motors, drives, and transmission systems; position, velocity, torque, and multi-axis motion control; path generation and motion profiles; servo tuning; integration with programmable logic controllers and vision systems; collaborative robots, end effectors, and robot-cell layout design; programming and virtual simulation; risk assessment, force limits, interlocks, and acceptance testing'),
  ('EN-714-14028', 'AISE-2570', 'elec', 'Lean/AI Process', 'การปรับปรุงกระบวนการด้วยลีนและปัญญาประดิษฐ์', 'Lean and AI-Enabled Process Improvement', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการลีนและซิกซ์ซิกมา การทำแผนที่สายธารคุณค่าและการลดความสูญเปล่า การไหล การดึง และงานมาตรฐาน กระบวนการดีเอ็มเอไอซี การวิเคราะห์ประสิทธิผลโดยรวมของเครื่องจักร เวลารอบงาน และของเสีย การควบคุมกระบวนการเชิงสถิติและการวิเคราะห์สาเหตุที่แท้จริง และการใช้การเรียนรู้ของเครื่องพยากรณ์คุณภาพและจัดลำดับโอกาสปรับปรุง', 'Lean and Six Sigma principles; value-stream mapping and waste reduction; flow, pull, and standardized work; the DMAIC process; analysis of overall equipment effectiveness, cycle time, bottlenecks, and scrap; statistical process control, process capability, design of experiments, and root-cause analysis; machine learning for quality prediction and improvement prioritization; before-and-after evaluation with quality, cost, and energy indicators'),
  ('EN-714-14029', 'AISE-2570', 'elec', 'CV ควบคุมคุณภาพ', 'คอมพิวเตอร์วิทัศน์เพื่อการควบคุมคุณภาพในอุตสาหกรรม', 'Computer Vision for Industrial Quality Control', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'ระบบคอมพิวเตอร์วิทัศน์อุตสาหกรรม การออกแบบระบบแสงสว่างและการเลือกเลนส์สำหรับการตรวจสอบคุณภาพ การเตรียมภาพและการกำจัดสัญญาณรบกวน การตรวจจับขอบ ตำหนิ และข้อบกพร่องของชิ้นงานบนสายพาน การใช้การเรียนรู้เชิงลึกจำแนกประเภทข้อบกพร่อง การวัดขนาดชิ้นงาน และการเชื่อมต่อกับหุ่นยนต์และระบบคัดแยกอัตโนมัติ', 'Principles of industrial computer-vision systems; design of lighting systems and lens selection for quality inspection; image preparation and noise removal; detection of edges, blemishes, and defects on conveyors; integration with deep learning for defect classification; workpiece dimension measurement and assembly verification; connection to robots and automatic sorting systems; image-data analysis for process improvement'),
  ('EN-714-14030', 'AISE-2570', 'elec', 'พลังงานอัจฉริยะโรงงาน', 'การจัดการพลังงานอัจฉริยะและระบบพลังงานแสงอาทิตย์', 'Smart Energy Management and Solar Energy Systems', '3(3-0-6)', 3, 3, 0, 6, NULL, NULL, false, 'หลักการจัดการและการอนุรักษ์พลังงานในโรงงานอุตสาหกรรม การตรวจสอบและวิเคราะห์การใช้พลังงานของระบบไฟฟ้า เครื่องจักร ระบบปรับอากาศ และหม้อไอน้ำ เทคโนโลยีพลังงานแสงอาทิตย์และการออกแบบระบบผลิตไฟฟ้าด้วยเซลล์แสงอาทิตย์ ระบบบริหารจัดการพลังงานแบบเวลาจริง และการวิเคราะห์ความคุ้มค่าและการลดก๊าซเรือนกระจก', 'Principles of energy management and conservation in industry; auditing and analysis of energy use in electrical systems, machinery, air-conditioning, compressed-air, and boiler systems; solar energy technology and photovoltaic system design; integration of sensors, smart meters, and real-time energy management systems; AI for demand forecasting and anomaly detection; cost-benefit analysis and greenhouse-gas reduction'),
  ('EN-714-14031', 'AISE-2570', 'elec', 'Fluid Power AI', 'ระบบนิวแมติกส์และไฮดรอลิกอัจฉริยะสำหรับวิศวกรรมปัญญาประดิษฐ์', 'Intelligent Pneumatic and Hydraulic Systems for Artificial Intelligence Engineering', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการพื้นฐานของระบบนิวแมติกส์และไฮดรอลิก โครงสร้างและการทำงานของแหล่งจ่ายกำลัง วาล์ว และกระบอกสูบ การออกแบบวงจรควบคุมนิวแมติกส์ ไฮดรอลิก และไฟฟ้า–นิวแมติกส์ การเชื่อมต่อกับตัวควบคุมแบบโปรแกรมได้และอุปกรณ์เอดจ์ การใช้การเรียนรู้ของเครื่องบำรุงรักษาเชิงพยากรณ์ และความปลอดภัยและประสิทธิภาพพลังงานของระบบกำลังของไหล', 'Fundamental principles of pneumatic and hydraulic systems; structure and operation of power sources, valves, and cylinders; design of pneumatic, hydraulic, and electro-pneumatic control circuits; selection of sensors and actuators in automation systems; integration with microcontrollers, programmable logic controllers, and edge devices; real-time signal acquisition; machine learning for anomaly detection and predictive maintenance; fluid-power safety and energy efficiency'),
  ('EN-714-14032', 'AISE-2570', 'elec', 'Heat/Mass Transfer', 'การถ่ายโอนความร้อนและมวลสารสำหรับระบบอัจฉริยะ', 'Heat and Mass Transfer for Smart Systems', '3(3-0-6)', 3, 3, 0, 6, NULL, NULL, false, 'หลักการถ่ายโอนความร้อนและมวลสาร การนำ การพา และการแผ่รังสีความร้อน การวิเคราะห์การนำความร้อนสภาวะคงตัวและไม่คงตัว การเลือกฉนวนความร้อน การแพร่และการถ่ายโอนมวลสาร การเลือกและวิเคราะห์อุปกรณ์แลกเปลี่ยนความร้อน และการจัดการความร้อนสำหรับฮาร์ดแวร์ปัญญาประดิษฐ์ ระบบอบแห้ง ห้องเย็น และระบบพลังงาน', 'Principles of heat and mass transfer; conduction, convection, and thermal radiation; steady-state and transient conduction analysis; thermal insulation selection; natural and forced convection; diffusion and mass transfer; selection and analysis of heat exchangers; finite-difference methods and machine learning for predicting transfer rates; thermal management of AI hardware, drying systems, cold rooms, and energy systems'),
  ('EN-714-14033', 'AISE-2570', 'elec', 'Industrial Safety', 'วิศวกรรมความปลอดภัยอัจฉริยะ อาชีวอนามัย และกฎหมายอุตสาหกรรม', 'Intelligent Safety Engineering, Occupational Health and Industrial Law', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการวิศวกรรมความปลอดภัยและอาชีวอนามัยในโรงงาน กฎหมาย ข้อบังคับ และมาตรฐานความปลอดภัยทางวิศวกรรม การชี้บ่งอันตรายและการประเมินความเสี่ยงด้วยการวิเคราะห์ความปลอดภัยของงานและการวิเคราะห์รูปแบบและผลกระทบของความขัดข้อง ความปลอดภัยเชิงหน้าที่ อินเตอร์ล็อก และระบบหยุดฉุกเฉิน สรีรศาสตร์อุตสาหกรรม และการใช้เซนเซอร์เฝ้าระวังความเสี่ยง', 'Principles of industrial safety engineering and occupational health; engineering safety laws, regulations, and standards; hazard identification and risk assessment through job safety analysis, hazard and operability studies, and failure-mode and effects analysis; safety of machinery, electrical systems, and chemicals; functional safety, interlocks, and emergency-stop systems; ergonomics and industrial hygiene; sensors and AI for risk monitoring and analysis'),
  ('EN-714-14034', 'AISE-2570', 'elec', 'ออกแบบเครื่องจักรกล', 'การออกแบบเครื่องจักรกลอัจฉริยะ', 'Intelligent Machine Design', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การประยุกต์หลักการทางวิศวกรรมสำหรับการออกแบบเครื่องจักรกล การวิเคราะห์ภาระ ความเค้น และความเมื่อยล้าของชิ้นส่วนเครื่องจักร การเลือกวัสดุและกระบวนการผลิต การออกแบบชิ้นส่วนส่งกำลัง เพลา เฟือง และตลับลูกปืน การสร้างแบบจำลองสามมิติและการวิเคราะห์ด้วยไฟไนต์เอลิเมนต์ และการใช้ปัญญาประดิษฐ์หาค่าเหมาะที่สุดของการออกแบบ', 'Application of engineering principles to machine design; analysis of loads, stresses, fatigue, and component safety; selection of materials and manufacturing processes; design of power-transmission components, shafts, gears, belts, and bearings; engineering drawing and three-dimensional computer modeling; finite element analysis; integration of sensors into machines; AI for design optimization and failure prediction'),
  ('EN-714-14035', 'AISE-2570', 'elec', 'ออกแบบเครื่องจักรชั้นสูง', 'การออกแบบเครื่องจักรกลชั้นสูงสำหรับระบบอัตโนมัติและหุ่นยนต์', 'Advanced Machine Design for Automation and Robotics', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'ประเภทและการทำงานของเครื่องจักรกลในระบบอัตโนมัติและหุ่นยนต์ การออกแบบกลไกและระบบส่งกำลังสำหรับการเคลื่อนที่แม่นยำ จลนศาสตร์และพลศาสตร์ของกลไกและแขนกล การเลือกมอเตอร์ เซอร์โว และชุดขับ การออกแบบโครงสร้างเพื่อความแข็งแรงและการสั่นสะเทือนต่ำ การบูรณาการระบบควบคุมและการมองเห็นของเครื่องจักร และการประเมินความเสี่ยง', 'Types and operation of machinery in automation and robotic systems; design of mechanisms and transmission systems for precise motion; kinematics and dynamics of mechanisms and manipulators; selection of motors, servo and stepper drives; machine structure design for stiffness and low vibration; design of fixtures and end effectors; integration of control systems, sensors, and machine vision; risk assessment and acceptance testing'),
  ('EN-714-14036', 'AISE-2570', 'elec', 'Advanced Data Eng', 'วิศวกรรมข้อมูลขั้นสูงและการวางท่อข้อมูล', 'Advanced Data Engineering and Data Pipelines', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'สถาปัตยกรรมและการออกแบบท่อข้อมูลขั้นสูงสำหรับระบบปัญญาประดิษฐ์ การประมวลผลข้อมูลแบบกระแสและแบบกระจาย การออกแบบสถาปัตยกรรมที่เก็บข้อมูลขนาดใหญ่ การจัดการคุณภาพและธรรมาภิบาลข้อมูลในองค์กร การสร้างท่อข้อมูลแบบเวลาจริง การบูรณาการข้อมูลจากหลายแหล่ง และการติดตามและบริหารจัดการท่อข้อมูลในการทำงานจริง', 'Architecture and design of advanced data pipelines for AI systems; stream and distributed processing; design of big-data storage architectures; data-quality management and enterprise data governance; data orchestration; construction of real-time pipelines; integration of data from diverse sources; and monitoring and management of pipelines in production'),
  ('EN-714-14037', 'AISE-2570', 'elec', 'Advanced LLM', 'ตัวแบบภาษาขนาดใหญ่ขั้นสูง', 'Advanced Large Language Models', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'สถาปัตยกรรมและกระบวนการทำงานของตัวแบบภาษาขนาดใหญ่ การจัดเตรียมชุดข้อมูลเฉพาะโดเมน การปรับตัวแบบตามคำสั่งและการปรับแบบประหยัดพารามิเตอร์ การบีบอัดและลดความละเอียดตัวแบบ การประเมินความถูกต้อง การให้เหตุผล และความทนทาน การเพิ่มประสิทธิภาพการอนุมานด้านความเร็วและต้นทุน และการให้บริการตัวแบบพร้อมติดตามการเสื่อมของสมรรถนะ', 'Architectures and operation of large language models; preparation and governance of domain datasets; instruction tuning and parameter-efficient fine-tuning; model compression and quantization; evaluation of accuracy, reasoning, factuality, and robustness; benchmark and comparative-experiment design; inference optimization for latency, cost, and energy; model serving with performance-degradation monitoring'),
  ('EN-714-14038', 'AISE-2570', 'elec', 'AI Reliability/Safety', 'ความน่าเชื่อถือและความปลอดภัยของปัญญาประดิษฐ์', 'AI Reliability and Safety', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'วิศวกรรมความน่าเชื่อถือและความปลอดภัยของระบบปัญญาประดิษฐ์ การกำหนดข้อกำหนดและเกณฑ์ยอมรับสมรรถนะ การสร้างชุดทดสอบสำหรับข้อมูลนอกการแจกแจงและกรณีขอบ การวัดความไม่แน่นอนและการสอบเทียบความเชื่อมั่น ความทนทานต่อการโจมตีแบบปรปักษ์ การประเมินความลำเอียงและความเป็นธรรม และการจัดทำบัตรตัวแบบพร้อมหลักฐานการประกันคุณภาพ', 'Reliability and safety engineering for AI systems; performance requirements and acceptance criteria; test sets for normal, out-of-distribution, and edge cases; uncertainty measurement and confidence calibration; robustness to adversarial attacks; bias and fairness evaluation; red teaming and guardrails; monitoring of data and model drift; preparation of model cards and assurance evidence'),
  ('EN-714-14039', 'AISE-2570', 'elec', 'Enterprise AI Arch', 'สถาปัตยกรรมปัญญาประดิษฐ์ระดับองค์กร', 'Enterprise AI Architecture', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การออกแบบสถาปัตยกรรมปัญญาประดิษฐ์ระดับองค์กร การแบ่งขอบเขตโดเมนและบริการ สถาปัตยกรรมขับเคลื่อนด้วยเหตุการณ์ ส่วนต่อประสานและการจัดการเอพีไอ การบูรณาการกับระบบวางแผนทรัพยากรองค์กรและกระบวนการทำงานเดิม การจัดการอัตลักษณ์และสิทธิ์ การออกแบบระบบที่ขยายขนาดได้และมีความพร้อมใช้สูง และการสังเกตการณ์ระบบพร้อมบริหารต้นทุนคลาวด์', 'Enterprise AI architecture design; domain and service boundaries; event-driven architecture; application programming interfaces and API management; integration with enterprise resource planning, customer-relationship management, and legacy workflows; identity, access, and zero-trust architecture; scalable, highly available, and disaster-recoverable system design; observability and cloud-cost management'),
  ('EN-714-14040', 'AISE-2570', 'elec', 'UX/UI ระบบอัจฉริยะ', 'การออกแบบประสบการณ์ผู้ใช้สำหรับระบบอัจฉริยะ', 'UX/UI Design for Intelligent Systems', '3(3-0-6)', 3, 3, 0, 6, NULL, NULL, false, 'หลักการและกระบวนการออกแบบประสบการณ์ผู้ใช้และส่วนต่อประสานสำหรับระบบปัญญาประดิษฐ์ การวิจัยและวิเคราะห์ความต้องการผู้ใช้ การคิดเชิงออกแบบ การออกแบบโครงร่างและต้นแบบ การออกแบบแผงควบคุมข้อมูล หลักการปัญญาประดิษฐ์ที่อธิบายได้สำหรับส่วนต่อประสานที่โปร่งใส และการทดสอบความสามารถในการใช้งานและการออกแบบที่ครอบคลุม', 'Principles and processes of user-experience and user-interface design for AI systems; user research and needs analysis; design thinking; wireframe and prototype design; dashboard design for data visualization; explainable-AI principles for transparent interfaces; usability testing and user-experience evaluation; and inclusive design for commercial applications'),
  ('EN-714-14041', 'AISE-2570', 'elec', 'AI การแพทย์', 'ปัญญาประดิษฐ์ทางการแพทย์และสุขภาพ', 'Artificial Intelligence in Medical and Healthcare', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการประยุกต์ใช้ปัญญาประดิษฐ์ในทางการแพทย์และระบบสาธารณสุข การจัดการฐานข้อมูลเวชระเบียนอิเล็กทรอนิกส์ การพัฒนาตัวแบบเพื่อการวินิจฉัยโรคเบื้องต้น การพยากรณ์ความเสี่ยงทางสุขภาพจากข้อมูลพฤติกรรม ระบบแนะนำการรักษาเฉพาะบุคคล การบูรณาการกับอุปกรณ์สวมใส่เพื่อติดตามสัญญาณชีพ และจริยธรรมและความเป็นส่วนตัวของข้อมูลผู้ป่วย', 'Principles of applying AI in medicine and public-health systems; management of electronic health-record databases; machine learning models for preliminary diagnosis; health-risk forecasting from behavioral data; personalized treatment recommendation systems; integration with wearable devices to monitor vital signs; natural-language processing to extract information from medical documents; and ethics and privacy of patient data'),
  ('EN-714-14042', 'AISE-2570', 'elec', 'วิเคราะห์ภาพการแพทย์', 'การวิเคราะห์ข้อมูลภาพทางการแพทย์', 'Medical Image Analysis', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'หลักการประมวลผลและการวิเคราะห์ภาพทางการแพทย์ การทำงานกับภาพรังสีเอกซ์ ภาพถ่ายรังสีส่วนตัดอาศัยคอมพิวเตอร์ และภาพคลื่นแม่เหล็กไฟฟ้า การใช้การเรียนรู้เชิงลึกเพื่อการตรวจจับและแบ่งส่วนอวัยวะ การวิเคราะห์ความผิดปกติและรอยโรค การลดสัญญาณรบกวนและเพิ่มความคมชัดของภาพ และการบูรณาการกับระบบจัดเก็บภาพทางการแพทย์พร้อมประเมินตัวแบบ', 'Principles of medical image processing and analysis; working with X-ray, computed-tomography, and magnetic-resonance image data; deep learning for organ detection and segmentation; analysis of abnormalities and lesions; building models to assist physicians in diagnosis; noise reduction and contrast enhancement; integration with picture archiving and communication systems; performance evaluation of models'),
  ('EN-714-14043', 'AISE-2570', 'elec', 'FinTech + AI', 'เทคโนโลยีทางการเงินและปัญญาประดิษฐ์', 'Financial Technology and Artificial Intelligence', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'เทคโนโลยีทางการเงินและนวัตกรรมบริการทางการเงิน การประยุกต์ใช้ปัญญาประดิษฐ์ในอุตสาหกรรมการเงินและการธนาคาร ระบบการชำระเงินอิเล็กทรอนิกส์และเทคโนโลยีบล็อกเชน การวิเคราะห์ความเสี่ยงด้านสินเชื่อ การตรวจจับการทุจริตทางการเงิน ระบบการลงทุนอัตโนมัติ และกฎระเบียบด้านเทคโนโลยีทางการเงิน', 'Principles of financial technology and financial-service innovation; application of AI in finance and banking; electronic payment systems and blockchain technology; credit-risk analysis with machine learning; financial-fraud detection; automated investment and robo-advisory systems; consumer behavior analysis; asset valuation models; and financial-technology regulations and policies'),
  ('EN-714-14044', 'AISE-2570', 'elec', 'วิเคราะห์คาดการณ์การเงิน', 'การวิเคราะห์ข้อมูลเชิงคาดการณ์ทางการเงิน', 'Predictive Data Analysis in Finance', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'เทคนิคการวิเคราะห์ข้อมูลเชิงคาดการณ์สำหรับตลาดการเงิน การวิเคราะห์ข้อมูลอนุกรมเวลาทางการเงิน การสร้างตัวแบบพยากรณ์ราคาสินทรัพย์ด้วยการเรียนรู้เชิงลึก การวิเคราะห์ความรู้สึกจากข่าวสารและสื่อสังคมออนไลน์ การบริหารความเสี่ยงและพอร์ตการลงทุนด้วยปัญญาประดิษฐ์ และการสร้างและทดสอบระบบเทรดอัตโนมัติพร้อมแสดงภาพข้อมูล', 'Predictive-analytics techniques for financial markets; analysis of financial time-series data; price-forecasting models for stocks and financial assets with deep learning; sentiment analysis of news and social media affecting markets; risk and portfolio management with AI; high-frequency trading algorithms; building and testing automated trading systems; and interpretation and visualization of financial data for decisions'),
  ('EN-714-14045', 'AISE-2570', 'elec', 'AI Venture', 'การสร้างธุรกิจปัญญาประดิษฐ์', 'AI Venture Creation', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การต่อยอดต้นแบบปัญญาประดิษฐ์สู่ธุรกิจ การตรวจสอบตลาดและความพร้อมของเทคโนโลยี การกำหนดรูปแบบรายได้ ราคา และเศรษฐศาสตร์ต่อหน่วย กลยุทธ์เข้าสู่ตลาดและการบริหารโครงการนำร่อง การจัดการทรัพย์สินทางปัญญาและข้อตกลงระดับบริการ และการจัดทำประมาณการทางการเงินและการนำเสนอแก่นักลงทุน', 'Commercialization of AI prototypes; market validation and technology readiness; revenue models, pricing, unit economics, and model-serving costs; go-to-market strategy, business-to-business sales, and pilot management; intellectual property, licensing, and service-level agreements; operations and scaling plans; financial projections and investor pitching'),
  ('EN-714-14046', 'AISE-2570', 'elec', 'จัดการโครงการซอฟต์แวร์', 'การจัดการโครงการซอฟต์แวร์อัจฉริยะ', 'Intelligent Software Project Management', '3(3-0-6)', 3, 3, 0, 6, NULL, NULL, false, 'หลักการและระเบียบวิธีบริหารโครงการซอฟต์แวร์อัจฉริยะ การบริหารโครงการแบบอไจล์และสครัม การวางแผนและจัดการทรัพยากรสำหรับโครงการที่ขับเคลื่อนด้วยข้อมูล การประเมินความเสี่ยงและระยะเวลาของโครงการพัฒนาตัวแบบ การจัดการวงจรชีวิตของระบบการเรียนรู้ของเครื่อง และการควบคุมคุณภาพและการวัดผลความสำเร็จของโครงการ', 'Principles and methodologies of intelligent software project management; agile and Scrum; planning and resource management for data- and AI-driven projects; risk and timeline assessment of model-development projects; management of the machine learning system lifecycle; stakeholder-expectation management; quality control and continuous delivery; and measuring project success'),
  ('EN-714-14047', 'AISE-2570', 'elec', 'ธุรกิจ/ตลาดดิจิทัล AI', 'การพัฒนาธุรกิจและการตลาดดิจิทัลด้วยปัญญาประดิษฐ์', 'Business Development and Digital Marketing with AI', '3(3-0-6)', 3, 3, 0, 6, NULL, NULL, false, 'แนวคิดการพัฒนาธุรกิจดิจิทัลโดยใช้ปัญญาประดิษฐ์เป็นฐาน การสร้างกลยุทธ์การตลาดดิจิทัลที่ขับเคลื่อนด้วยข้อมูล การวิเคราะห์และแบ่งกลุ่มลูกค้าเป้าหมายด้วยการเรียนรู้ของเครื่อง การสร้างเนื้อหาการตลาดอัตโนมัติด้วยปัญญาประดิษฐ์เชิงสร้าง ระบบแนะนำสินค้าแบบเฉพาะบุคคล และการวิเคราะห์ประสิทธิผลของแคมเปญและการใช้แชตบอต', 'Concepts of AI-based digital business development; data-driven digital marketing strategy; customer segmentation with machine learning; automated advertising content and marketing communication with generative AI; personalized product and service recommendation systems; campaign-effectiveness analysis; and chatbots for customer service and proactive selling'),
  ('EN-714-14048', 'AISE-2570', 'elec', 'AI Product Mgmt', 'การจัดการผลิตภัณฑ์ปัญญาประดิษฐ์', 'AI Product Management', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'การจัดการผลิตภัณฑ์ปัญญาประดิษฐ์ตลอดวงจรชีวิต การกำหนดวิสัยทัศน์ กลุ่มผู้ใช้ และคุณค่าที่เสนอ การจัดทำแผนที่เส้นทางผลิตภัณฑ์และเกณฑ์จัดลำดับความสำคัญ การกำหนดตัวชี้วัดผลิตภัณฑ์และข้อจำกัดด้านความเสี่ยง การออกแบบปฏิสัมพันธ์ระหว่างมนุษย์กับปัญญาประดิษฐ์ การทดลองแบบเอ/บี และการตัดสินใจขยาย ปรับ หรือยุติผลิตภัณฑ์จากหลักฐาน', 'AI product management throughout the lifecycle; definition of vision, user segments, value proposition, and business outcomes; product roadmaps and prioritization criteria; product metrics, model-performance indicators, and risk constraints; human-AI interaction design; A/B testing; management of feedback and model drift; evidence-based decisions to scale, pivot, or retire products'),
  ('EN-714-14049', 'AISE-2570', 'elec', 'VR/AR + AI', 'เทคโนโลยีโลกเสมือนจริงและปัญญาประดิษฐ์', 'Virtual Reality Technology and Artificial Intelligence', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'เทคโนโลยีโลกเสมือนจริง ความเป็นจริงเสริม และความเป็นจริงผสม การบูรณาการปัญญาประดิษฐ์กับการสร้างสภาพแวดล้อมจำลอง การสร้างเนื้อหาสามมิติด้วยปัญญาประดิษฐ์เชิงสร้าง การโต้ตอบกับวัตถุเสมือนด้วยคอมพิวเตอร์วิทัศน์และการประมวลผลภาษาธรรมชาติ การพัฒนาแอปพลิเคชันสำหรับการฝึกอบรมอุตสาหกรรมและการตลาดดิจิทัล และการวิเคราะห์พฤติกรรมผู้ใช้', 'Virtual-reality, augmented-reality, and mixed-reality technologies; integration of AI with simulated environments; processing and generation of 3D content with generative AI; interaction with virtual objects through computer vision and natural-language processing; development of applications for medical simulation, industrial training, and digital marketing; analysis of user behavior in digital environments'),
  ('EN-714-14050', 'AISE-2570', 'elec', 'AI Governance/Risk', 'ธรรมาภิบาลและความเสี่ยงของปัญญาประดิษฐ์', 'AI Governance and Risk', '3(2-2-5)', 3, 2, 2, 5, NULL, NULL, false, 'กรอบธรรมาภิบาลและการบริหารความเสี่ยงของปัญญาประดิษฐ์ การจัดทำบัญชีระบบและจำแนกระดับความเสี่ยง การประเมินผลกระทบด้านสิทธิ ความเป็นส่วนตัว และความเป็นธรรม การกำหนดบทบาท ความรับผิดชอบ และการกำกับโดยมนุษย์ การปฏิบัติตามกฎหมายคุ้มครองข้อมูลและมาตรฐานที่เกี่ยวข้อง และการจัดทำทะเบียนความเสี่ยง บัตรตัวแบบ และหลักฐานสำหรับการตรวจประเมิน', 'AI governance and risk-management frameworks; system inventories and risk classification; impact assessment for rights, privacy, fairness, and safety; roles, accountability, and human oversight; compliance with data-protection laws and relevant standards; third-party and external-model risk; risk registers, model cards, and audit evidence; post-deployment monitoring and incident reporting');
