INSERT INTO clo (id, course_code, no, statement, evidence, primary_skill_set) VALUES
  (1, 'EN-714-11001', 1, 'อธิบายมาตรฐานการเขียนแบบ สัญลักษณ์ ภาพฉาย และเกณฑ์ความคลาดเคลื่อน พร้อมตีความแบบชิ้นส่วนและแบบประกอบได้', 'ชุดแบบและแบบจำลองด้วยคอมพิวเตอร์ช่วยออกแบบ', 'AISK02'),
  (2, 'EN-714-11001', 2, 'ควบคุมการแก้ไขแบบและสื่อสารแบบเพื่อการจำลอง การติดตั้ง และการส่งมอบร่วมกับทีมได้', 'บันทึกการแก้ไข หลักฐานการมีส่วนร่วม และผลการทบทวนแบบ', 'AISK08'),
  (3, 'EN-714-11001', 3, 'ออกแบบผังระบบ แบบท่อและเครื่องมือวัด และแบบไฟฟ้าหรือแบบควบคุม โดยคำนึงถึงความปลอดภัย ความสามารถในการบำรุงรักษา และการยศาสตร์ได้', 'ชุดแบบระบบที่ผ่านการตรวจสอบความสอดคล้อง', 'AISK03'),
  (4, 'EN-714-11002', 1, 'อธิบายชนิดข้อมูล โครงสร้างโปรแกรม การจัดการแฟ้มข้อมูลและฐานข้อมูล และบทบาทของส่วนต่อประสานโปรแกรมประยุกต์และเครื่องมือช่วยเขียนโปรแกรมด้วยปัญญาประดิษฐ์ได้', 'โปรแกรมประยุกต์ขนาดย่อมที่เชื่อมข้อมูลและส่วนต่อประสานโปรแกรมประยุกต์', 'AISK06'),
  (5, 'EN-714-11002', 2, 'ใช้ระบบควบคุมรุ่น แก้จุดบกพร่อง ทดสอบหน่วย และจัดทำเอกสาร เพื่อพัฒนาและส่งมอบโปรแกรมร่วมกับทีมตามบทบาทได้', 'คลังรหัส หลักฐานการมีส่วนร่วม และผลการทดสอบ', 'AISK01'),
  (6, 'EN-714-11002', 3, 'ออกแบบขั้นตอนวิธีและพัฒนาโปรแกรมภาษาไพทอน โดยใช้โครงสร้างข้อมูล ฟังก์ชัน โมดูล และการเขียนโปรแกรมเชิงวัตถุได้', 'แบบฝึกปฏิบัติการเขียนโปรแกรม', 'AISK01'),
  (7, 'EN-714-11003', 1, 'อธิบายแรงภายใน ความเค้น ความเครียด การโก่งตัว และรูปแบบความเสียหายของโครงสร้างได้', 'รายงานการคำนวณโครงสร้าง', 'AISK02'),
  (8, 'EN-714-11003', 2, 'ออกแบบโครง ฐานยึด และกล่องหุ้ม โดยใช้ค่าความปลอดภัยและเกณฑ์ด้านการผลิตได้', 'ชุดเอกสารการออกแบบที่คำนึงถึงความปลอดภัย', 'AISK02'),
  (9, 'EN-714-11003', 3, 'เลือกวัสดุโดยพิจารณาอายุการใช้งาน การบำรุงรักษา และผลกระทบตลอดวงจรชีวิตได้', 'รายงานประกอบการตัดสินใจเลือกวัสดุและวิเคราะห์วงจรชีวิต', 'AISK02'),
  (10, 'EN-714-11004', 1, 'อ่านและตีความแบบ ข้อกำหนด และหลักความปลอดภัยของงานสร้างต้นแบบโครงสร้างหรือสถานีตรวจวัดได้', 'ต้นแบบและผลการตรวจสอบคุณภาพชิ้นงาน', 'AISK02'),
  (11, 'EN-714-11004', 2, 'ติดตั้งและสอบเทียบอุปกรณ์ตรวจวัด พร้อมจัดทำแบบ รายการวัสดุ และบันทึกการสอบเทียบเป็นทีมได้', 'แฟ้มหลักฐานการสร้างและประกอบระบบของทีม', 'AISK04'),
  (12, 'EN-714-12001', 1, 'อธิบายและเปรียบเทียบแนวคิดการค้นหาและการให้เหตุผล การเรียนรู้ของเครื่อง คอมพิวเตอร์วิทัศน์ การประมวลผลภาษาธรรมชาติ ปัญญาประดิษฐ์เชิงสร้าง และระบบเอเจนต์ได้', 'รายงานวิเคราะห์แนวคิดและลักษณะปัญหา', 'AISK06'),
  (13, 'EN-714-12001', 2, 'สืบค้นและวิเคราะห์แนวโน้มปัญญาประดิษฐ์จากงานวิจัย ตลาด และแหล่งข้อมูลที่น่าเชื่อถือ พร้อมจัดทำแผนการเรียนรู้ได้', 'เอกสารเฝ้าติดตามเทคโนโลยี', 'AISK06'),
  (14, 'EN-714-12001', 3, 'ตรวจสอบวงจรชีวิต ข้อจำกัด ความลำเอียง ความไม่แน่นอน และการกำกับดูแลโดยมนุษย์ของกรณีปัญญาประดิษฐ์ตามรายการตรวจสอบมาตรฐานได้', 'รายงานกรณีศึกษาปัญญาประดิษฐ์ที่รับผิดชอบ', 'AISK07'),
  (15, 'GE-001-13002', 1, 'ใช้คำศัพท์และโครงสร้างประโยคภาษาอังกฤษพื้นฐานเพื่อการสื่อสารในชีวิตประจำวันได้', NULL, NULL),
  (16, 'GE-001-13002', 2, 'ฟังและจับใจความสำคัญจากบทสนทนาในสถานการณ์ต่าง ๆ ได้', NULL, NULL),
  (17, 'GE-001-13002', 3, 'อ่านและทำความเข้าใจข้อความสั้น ๆ ได้', NULL, NULL),
  (18, 'GE-001-13005', 1, 'อธิบายวิสัยทัศน์ พันธกิจ และอัตลักษณ์บัณฑิตของมหาวิทยาลัยกาฬสินธุ์ได้', NULL, NULL),
  (19, 'GE-001-13005', 2, 'แสดงออกถึงการมีจิตสาธารณะและทำงานเพื่อส่วนรวม', NULL, NULL),
  (20, 'EN-714-11005', 1, 'อธิบายหลักสมดุลมวล สมดุลพลังงาน กลไกการถ่ายเทความร้อน และลักษณะการไหลในระบบเกษตรหรืออุตสาหกรรมได้', 'รายงานการคำนวณและแบบจำลอง', 'AISK02'),
  (21, 'EN-714-11005', 2, 'เลือกองค์ประกอบและออกแบบแนวทางปรับปรุงระบบปั๊ม พัดลม เครื่องแลกเปลี่ยนความร้อน ระบบอบแห้ง หรือระบบทำความเย็นภายใต้ข้อจำกัดได้', 'รายงานเปรียบเทียบทางเลือกการออกแบบทางวิศวกรรม', 'AISK02'),
  (22, 'EN-714-11005', 3, 'คำนวณประสิทธิภาพพลังงาน การนำความร้อนทิ้งกลับมาใช้ และผลกระทบด้านคาร์บอน พร้อมระบุความไม่แน่นอนของผลการคำนวณได้', 'รายงานการตรวจประเมินพลังงานและคาร์บอน', 'AISK02'),
  (23, 'EN-714-11006', 1, 'อธิบายกฎพื้นฐานของวงจรไฟฟ้าและวงจรอิเล็กทรอนิกส์ ลักษณะของสัญญาณ และหลักการวัดที่ถูกต้องได้', 'รายงานปฏิบัติการวงจรและการวัด', 'AISK04'),
  (24, 'EN-714-11006', 2, 'เลือกและเชื่อมต่ออุปกรณ์ตรวจวัด วงจรปรับสภาพสัญญาณ ตัวกระตุ้น มอเตอร์ และระบบขับเคลื่อนให้สอดคล้องกับข้อกำหนดของระบบได้', 'แบบระบบตรวจวัดและขับเคลื่อน', 'AISK03'),
  (25, 'EN-714-11006', 3, 'ทดสอบการต่อลงดิน อุปกรณ์ป้องกัน และความปลอดภัยทางไฟฟ้า พร้อมบันทึกผลได้', 'แบบตรวจสอบความปลอดภัยและบันทึกผลการทดสอบ', 'AISK04'),
  (26, 'EN-714-11007', 1, 'อธิบายหลักการของสถิติเชิงพรรณนา การแจกแจงความน่าจะเป็น การทดสอบสมมติฐาน การถดถอย และการออกแบบการทดลอง พร้อมระบุเงื่อนไขการนำไปใช้กับปัญหาทางวิศวกรรมได้', 'สมุดบันทึกการออกแบบการทดลองและการวิเคราะห์ทางสถิติ', 'AISK01'),
  (27, 'EN-714-11007', 2, 'ประยุกต์ใช้การวิเคราะห์ระบบการวัดและแผนภูมิควบคุมกระบวนการเชิงสถิติ เพื่อตรวจสอบสมรรถนะของตัวแบบภายใต้ความไม่แน่นอนตามกระบวนการมาตรฐานได้', 'รายงานการวิเคราะห์ระบบการวัด การควบคุมกระบวนการ และการประเมินตัวแบบ', 'AISK01'),
  (28, 'EN-714-11007', 3, 'จัดทำและสื่อสารรายงานผลเชิงสถิติอย่างซื่อตรง พร้อมระบุข้อจำกัดของผลการวิเคราะห์ได้', 'บันทึกทางเทคนิคและแผงสรุปข้อมูล', 'AISK08'),
  (29, 'EN-714-11008', 1, 'อธิบายหลักการทำงานและข้อกำหนดการเชื่อมต่อของมอเตอร์ ระบบขับเคลื่อน วงจรนิวแมติกส์หรือไฮดรอลิกส์ อุปกรณ์ตรวจวัด และตัวควบคุมได้', 'รายงานปฏิบัติการระบบกำลังของไหลและการควบคุม', 'AISK03'),
  (30, 'EN-714-11008', 2, 'พัฒนาลำดับการควบคุมและส่วนต่อประสานมนุษย์กับเครื่องจักร พร้อมระบบอินเตอร์ล็อกและการหยุดฉุกเฉินได้', 'โปรแกรมควบคุมและผลการทดสอบความปลอดภัย', 'AISK03'),
  (31, 'EN-714-11008', 3, 'ทดสอบ แก้ไขข้อขัดข้อง และทบทวนผลการปฏิบัติงานร่วมกันเป็นทีมได้', 'บันทึกการแก้ไขข้อขัดข้องและการประเมินร่วมกัน', 'AISK08'),
  (32, 'EN-714-12002', 1, 'อธิบายแนวคิดพีชคณิตเชิงเส้น แคลคูลัส และความน่าจะเป็นที่รองรับการทำงานของตัวแบบปัญญาประดิษฐ์ได้', 'สมุดบันทึกการคำนวณทางคณิตศาสตร์', 'AISK01'),
  (33, 'EN-714-12002', 2, 'สร้างและแก้ตัวแบบการหาค่าเหมาะที่สุดแบบมีและไม่มีข้อจำกัดได้', 'แบบฝึกปฏิบัติการหาค่าเหมาะที่สุด', 'AISK01'),
  (34, 'EN-714-12002', 3, 'ตรวจสอบเสถียรภาพ ความถูกต้อง และตีความผลเชิงคณิตศาสตร์ของตัวแบบได้', 'รายงานการทวนสอบตัวแบบ', 'AISK01'),
  (35, 'GE-002-14005', 1, 'สื่อสารภาษาอังกฤษในบริบทสังคมพหุวัฒนธรรมด้วยคำศัพท์และสำนวนที่เหมาะสมได้', NULL, NULL),
  (36, 'GE-002-14005', 2, 'เขียนโต้ตอบอีเมลหรือข้อความสั้น ๆ เพื่อสื่อสารข้ามวัฒนธรรมได้', NULL, NULL),
  (37, 'GE-001-13001', 1, 'ประยุกต์ใช้เครื่องมือและแพลตฟอร์มดิจิทัลในการเรียนรู้และทำงานได้อย่างปลอดภัย', NULL, NULL),
  (38, 'GE-001-13001', 2, 'ตระหนักถึงความเป็นพลเมืองดิจิทัลและปฏิบัติตามกฎหมาย/จริยธรรมที่เกี่ยวข้อง', NULL, NULL),
  (39, 'EN-714-11009', 1, 'อธิบายแนวคิดมูลค่าเงินตามเวลา มูลค่าปัจจุบันสุทธิ อัตราผลตอบแทนภายใน อัตราส่วนผลประโยชน์ต่อต้นทุน ระยะเวลาคืนทุน ต้นทุนรวมในการเป็นเจ้าของ และเศรษฐศาสตร์ต่อหน่วยของโครงการวิศวกรรมหรือปัญญาประดิษฐ์ได้', 'แบบคำนวณพร้อมหลักฐานการตรวจสอบสมมติฐาน', 'AISK05'),
  (40, 'EN-714-11009', 2, 'จัดทำและนำเสนอกรณีธุรกิจที่แสดงคุณค่า ความเป็นไปได้ และข้อเสนอแนะต่อผู้มีอำนาจตัดสินใจได้', 'เอกสารกรณีธุรกิจและการนำเสนอข้อเสนอ', 'AISK08'),
  (41, 'EN-714-11009', 3, 'เปรียบเทียบและเลือกทางเลือกการลงทุนภายใต้ความเสี่ยง โดยพิจารณาต้นทุนทรัพยากร พลังงาน และคาร์บอนได้', 'รายงานการวิเคราะห์ความไว สถานการณ์ ทางเลือกการออกแบบ และ BCG', 'AISK05'),
  (42, 'EN-714-11010', 1, 'อธิบายวัตถุประสงค์ ขอบเขต และเกณฑ์ผ่านของการทดสอบส่วนต่อประสาน สมรรถนะ ความน่าเชื่อถือ และความปลอดภัยของระบบบูรณาการได้', 'แฟ้มหลักฐานการทดสอบและความปลอดภัย', 'AISK07'),
  (43, 'EN-714-11010', 2, 'ออกแบบสถาปัตยกรรมและบูรณาการระบบตรวจวัด ปัญญาประดิษฐ์ที่ขอบเครือข่าย PLC/SCADA ตัวกระตุ้น และแผงสรุปข้อมูลได้', 'การสาธิตระบบครบวงจร', 'AISK09'),
  (44, 'EN-714-11010', 3, 'วิเคราะห์ตัวชี้วัดด้านต้นทุน พลังงาน ทรัพยากร และคาร์บอน พร้อมจัดทำเอกสารส่งมอบได้', 'รายงาน BCG คุณค่า และเอกสารส่งมอบ', 'AISK08'),
  (45, 'EN-714-12003', 1, 'อธิบายหลักการของการเรียนรู้ของเครื่องและการเรียนรู้เชิงลึก พร้อมจำแนกประเภทของตัวแบบให้สอดคล้องกับลักษณะของปัญหาและข้อมูลได้', 'โครงงานพัฒนาตัวแบบ', 'AISK01'),
  (46, 'EN-714-12003', 2, 'ออกแบบการแบ่งข้อมูล ตัวชี้วัด และการตรวจสอบข้าม พร้อมจัดการการรั่วไหลของข้อมูลและความไม่สมดุลของข้อมูลได้', 'ระเบียบวิธีการประเมินตัวแบบ', 'AISK01'),
  (47, 'EN-714-12003', 3, 'วิเคราะห์ความไม่แน่นอน ความทนทาน และความสามารถในการอธิบายผล พร้อมดำเนินการทดลองซ้ำได้', 'ชุดหลักฐานการทำซ้ำผลการทดลอง', 'AISK01'),
  (48, 'EN-714-12004', 1, 'อธิบายสถาปัตยกรรมกระบวนการข้อมูล การประสานงาน จุดตรวจคุณภาพ ข้อมูลกำกับ สายสืบย้อนข้อมูล และการควบคุมรุ่นได้', 'แฟ้มหลักฐานกระบวนการและคุณภาพข้อมูล', 'AISK01'),
  (49, 'EN-714-12004', 2, 'สร้างชั้นความหมายข้อมูลและระบบธุรกิจอัจฉริยะ พร้อมสื่อสารผลโดยคุ้มครองข้อมูลได้', 'แผงสรุปข้อมูลและบันทึกธรรมาภิบาล', 'AISK05'),
  (50, 'EN-714-12004', 3, 'ออกแบบตัวแบบข้อมูล ข้อตกลงข้อมูล และสถาปัตยกรรมการประมวลผลแบบกลุ่มหรือแบบกระแสสำหรับระบบปัญญาประดิษฐ์และระบบสนับสนุนการตัดสินใจได้', 'แบบสถาปัตยกรรมข้อมูล', 'AISK01'),
  (51, 'EN-714-12005', 1, 'อธิบายหลักการทำงานและวิธีสอบเทียบของอุปกรณ์ตรวจวัดและอุปกรณ์ขับเคลื่อน พร้อมระบุแหล่งความไม่แน่นอนของห่วงโซ่การวัดได้', 'บันทึกการสอบเทียบและการวิเคราะห์ระบบการวัด', 'AISK03'),
  (52, 'EN-714-12005', 2, 'พัฒนากระบวนงานข้อมูลอนุกรมเวลาและการอนุมานที่ขอบเครือข่าย พร้อมจัดการอุปกรณ์ได้', 'การสาธิตระบบไอโอทีและการประมวลผลที่ขอบเครือข่าย', 'AISK04'),
  (53, 'EN-714-12005', 3, 'ออกแบบสถาปัตยกรรมระบบไซเบอร์กายภาพและไอโอที พร้อมเลือกอุปกรณ์ตรวจวัด อุปกรณ์ขับเคลื่อน โพรโทคอล เกตเวย์ และการประมวลผลที่ขอบเครือข่ายหรือระบบคลาวด์ได้', 'ข้อกำหนดสถาปัตยกรรมและส่วนต่อประสาน', 'AISK04'),
  (54, 'EN-714-12005', 4, 'วิเคราะห์ความน่าเชื่อถือ ความทนต่อความขัดข้อง ความเป็นส่วนตัว และความมั่นคงปลอดภัยของระบบ พร้อมทดสอบการบูรณาการสถานีตรวจวัดร่วมกันเป็นทีมได้', 'รายงานการทดสอบความน่าเชื่อถือและแฟ้มหลักฐานการทำงานของทีม', 'AISK07'),
  (55, 'GE-001-13004', 1, 'วิเคราะห์ปัจจัยและวางแผนเป้าหมายชีวิต/การเรียนรู้ของตนเองได้', NULL, NULL),
  (56, 'GE-001-13004', 2, 'สร้างความสัมพันธ์ระหว่างบุคคลและแสดงมนุษยสัมพันธ์ที่ดีในการทำงานร่วมกัน', NULL, NULL),
  (57, 'GE-002-14015', 1, 'วิเคราะห์ปัญหาด้านจริยธรรมทางสังคมและเศรษฐกิจที่เกี่ยวข้องกับเทคโนโลยีได้', NULL, NULL),
  (58, 'GE-002-14015', 2, 'ประยุกต์หลักปรัชญาเศรษฐกิจพอเพียงในการวางแผนและตัดสินใจได้', NULL, NULL),
  (59, 'EN-714-12006', 1, 'อธิบายหลักการของการตรวจจับ การจำแนก และการแบ่งส่วนภาพ พร้อมระบุเกณฑ์ประเมินความทนทานและความสามารถในการอธิบายผลของตัวแบบได้', 'รายงานการพัฒนาและประเมินตัวแบบ', 'AISK05'),
  (60, 'EN-714-12006', 2, 'นำตัวแบบไปใช้ที่ขอบเครือข่ายหรือในระบบตรวจสอบเฉพาะบริบท และสื่อสารข้อจำกัดแก่ผู้รับสารได้', 'การสาธิตระบบที่นำขึ้นใช้งานและเอกสารกำกับตัวแบบ', 'AISK04'),
  (61, 'EN-714-12006', 3, 'วิเคราะห์และออกแบบกระบวนการประมวลผลภาพหรือวิดีโอ พร้อมเปรียบเทียบวิธีเตรียมข้อมูลภาพสี ภาพหลายช่วงคลื่น หรือภาพความร้อนได้', 'ข้อกำหนดชุดข้อมูลและกระบวนการประมวลผล', 'AISK05'),
  (62, 'EN-714-12007', 1, 'อธิบายองค์ประกอบของกระบวนการฝึกและการนำตัวแบบขึ้นใช้งานด้วยคอนเทนเนอร์ ทะเบียนตัวแบบ และจุดตรวจคุณภาพได้', 'กระบวนการบูรณาการ ส่งมอบ และฝึกตัวแบบอย่างต่อเนื่อง', 'AISK01'),
  (63, 'EN-714-12007', 2, 'ติดตามสมรรถนะ การเปลี่ยนแปลงของข้อมูลและตัวแบบ บันทึกเหตุการณ์ ตัวชี้วัด ร่องรอย และวัตถุประสงค์ระดับบริการ พร้อมดำเนินการย้อนกลับและใช้คู่มือปฏิบัติการได้', 'แบบฝึกปฏิบัติการสังเกตการณ์ระบบและจัดการเหตุการณ์', 'AISK09'),
  (64, 'EN-714-12007', 3, 'เปรียบเทียบและเลือกแนวทางนำระบบขึ้นใช้งาน โดยพิจารณาความถูกต้อง เวลาตอบสนอง ความพร้อมใช้ ต้นทุน พลังงาน และคาร์บอนได้', 'รายงานเปรียบเทียบทางเลือกและผลกระทบของการนำระบบขึ้นใช้งาน', 'AISK01'),
  (65, 'EN-714-12008', 1, 'อธิบายลักษณะภาระงานปัญญาประดิษฐ์ พร้อมจำแนกบทบาทของหน่วยประมวลผล ระบบจัดเก็บข้อมูล เครือข่าย และหน่วยเร่งการประมวลผลได้', 'แบบกำหนดขีดความสามารถของระบบ', 'AISK01'),
  (66, 'EN-714-12008', 2, 'ออกแบบสถาปัตยกรรมที่เชื่อมเทคโนโลยีสารสนเทศ เทคโนโลยีปฏิบัติการ การประมวลผลที่ขอบเครือข่าย และระบบคลาวด์ พร้อมการแบ่งส่วนเครือข่าย การจัดการตัวตนและสิทธิ และการกำหนดค่าที่มั่นคงปลอดภัยได้', 'แบบสถาปัตยกรรมที่มั่นคงปลอดภัย', 'AISK09'),
  (67, 'EN-714-12008', 3, 'ออกแบบความพร้อมใช้ การสำรองและกู้คืนจากภัยพิบัติ และการเฝ้าติดตาม พร้อมทดลองการกู้คืนและสมรรถนะ และจัดทำเอกสารส่งมอบการปฏิบัติการได้', 'ผลการทดสอบความต่อเนื่องและการกู้คืน พร้อมแผนปฏิบัติการ', 'AISK09'),
  (68, 'EN-714-12009', 1, 'อธิบายบริบททางธุรกิจ ผู้ใช้ ผู้มีส่วนได้ส่วนเสีย และกระบวนการ พร้อมระบุปัญหาและโอกาสของผลิตภัณฑ์ปัญญาประดิษฐ์ได้', 'เอกสารสรุปปัญหา ผู้มีส่วนได้ส่วนเสีย และข้อกำหนด', 'AISK09'),
  (69, 'EN-714-12009', 2, 'ออกแบบแนวคิดสถาปัตยกรรมและต้นแบบที่ใช้ตรวจสอบความเป็นไปได้ด้านข้อมูลและปัญญาประดิษฐ์ได้', 'แบบสถาปัตยกรรมและต้นแบบ', 'AISK09'),
  (70, 'EN-714-12009', 3, 'ตรวจสอบสมมติฐานด้วยข้อมูลผู้ใช้หรือตลาด พร้อมคำนวณแบบจำลองธุรกิจ ผลตอบแทนการลงทุน ต้นทุนรวมในการเป็นเจ้าของ วงจรชีวิต BCG และความเสี่ยงตามเกณฑ์ที่กำหนดได้', 'หลักฐานการตรวจสอบสมมติฐานและกรณีศึกษาความเป็นไปได้กับคุณค่า', 'AISK08'),
  (71, 'EN-714-12009', 4, 'กำหนดเกณฑ์การยอมรับ การทดสอบการยอมรับของผู้ใช้ การนำไปใช้ การจัดการการเปลี่ยนแปลง และแผนด้านทรัพย์สินทางปัญญากับธรรมาภิบาลร่วมกับผู้มีส่วนได้ส่วนเสียได้', 'แฟ้มหลักฐานการยอมรับ การเปลี่ยนแปลง และการทำงานร่วมกัน', 'AISK09'),
  (72, 'EN-714-12010', 1, 'อธิบายข้อเสนอแนะและข้อจำกัดของระบบสนับสนุนการตัดสินใจแก่ผู้ปฏิบัติงานหรือผู้บริหารได้', 'แผงสรุปข้อมูลและเอกสารสรุปเพื่อการตัดสินใจ', 'AISK05'),
  (73, 'EN-714-12010', 2, 'จัดทำตัวชี้วัดและตัวแบบข้อมูล พร้อมประยุกต์ใช้การวิเคราะห์เชิงพรรณนาและเชิงพยากรณ์กับการดำเนินงานของห่วงโซ่อุปทานได้', 'ตัวแบบธุรกิจอัจฉริยะและการพยากรณ์', 'AISK05'),
  (74, 'EN-714-12010', 3, 'ประยุกต์ใช้การจำลองสถานการณ์เพื่อตรวจสอบความไม่แน่นอนและความเสี่ยงของห่วงโซ่อุปทานตามกระบวนการมาตรฐานได้', 'รายงานการวิเคราะห์สถานการณ์และการจำลอง', 'AISK05'),
  (75, 'EN-714-12010', 4, 'ออกแบบระบบสนับสนุนการตัดสินใจและตัวแบบการหาค่าเหมาะที่สุดหรือการวิจัยดำเนินงาน สำหรับสินค้าคงคลัง การผลิต หรือโลจิสติกส์ได้', 'ต้นแบบระบบสนับสนุนการตัดสินใจและการหาค่าเหมาะที่สุด', 'AISK05'),
  (76, 'GE-002-14011', 1, 'แสดงภาวะผู้นำและทำงานเป็นทีมในสถานการณ์ที่กำหนดได้', NULL, NULL),
  (77, 'GE-002-14011', 2, 'ประเมินและพัฒนาทักษะการทำงานร่วมกับผู้อื่นของตนเองได้', NULL, NULL),
  (78, 'EN-714-12011', 1, 'พัฒนาระบบพยากรณ์ ระบบแนะนำ หรือระบบสนับสนุนการตัดสินใจสำหรับฟาร์มจากข้อมูลอินเทอร์เน็ตของสรรพสิ่ง ข้อมูลเชิงพื้นที่ และข้อมูลการจัดการได้', 'ตัวแบบสนับสนุนการตัดสินใจสำหรับฟาร์ม', 'AISK05'),
  (79, 'EN-714-12011', 2, 'ออกแบบสถาปัตยกรรมระบบเกษตรอัจฉริยะจากข้อกำหนดของพื้นที่ พืช ปศุสัตว์ และผู้ใช้ได้', 'แบบสถาปัตยกรรมระบบฟาร์ม', 'AISK02'),
  (80, 'EN-714-12011', 3, 'วิเคราะห์ความน่าเชื่อถือและความไม่แน่นอนของผลจากการบูรณาการและทดลองต้นแบบระบบเกษตรอัจฉริยะได้', 'ต้นแบบและรายงานการทดลองกับความน่าเชื่อถือ', 'AISK04'),
  (81, 'EN-714-12011', 4, 'ประเมินตัวชี้วัดด้านต้นทุน น้ำ ปัจจัยการผลิต พลังงาน คาร์บอน ความปลอดภัย และผลกระทบ พร้อมจัดทำข้อเสนอปรับปรุงร่วมกับทีมได้', 'รายงาน BCG คุณค่า ความปลอดภัย และบันทึกการตัดสินใจของทีม', 'AISK02'),
  (82, 'EN-714-12012', 1, 'จัดทำแบบด้วยคอมพิวเตอร์ช่วยออกแบบ ผังระบบ แบบท่อและเครื่องมือวัด และแบบวงจรควบคุม พร้อมบูรณาการเซลล์หุ่นยนต์กับปัญญาประดิษฐ์และไอโอทีอุตสาหกรรมตามข้อกำหนดส่วนต่อประสานได้', 'ชุดแบบ เซลล์บูรณาการ และผลการทดสอบส่วนต่อประสาน', 'AISK03'),
  (83, 'EN-714-12012', 2, 'วิเคราะห์กระบวนการ การไหลของวัสดุและพลังงาน ความสูญเสีย คุณภาพ และข้อจำกัดด้านการผลิตได้', 'ตัวแบบกระบวนการและสายธารคุณค่า', 'AISK03'),
  (84, 'EN-714-12012', 3, 'ออกแบบสถาปัตยกรรมการควบคุมด้วยตัวควบคุมแบบโปรแกรมได้ ระบบสกาดา และหุ่นยนต์ พร้อมบูรณาการระบบบริหารการผลิตกับระบบวางแผนทรัพยากรองค์กรและดิจิทัลทวินได้', 'แบบสถาปัตยกรรมควบคุม ดิจิทัลทวิน และแผงสรุปข้อมูล', 'AISK03'),
  (85, 'EN-714-12012', 4, 'ประเมินการผลิตแบบลีน ซิกซ์ซิกมา การหาค่าเหมาะที่สุด ความปลอดภัยของเครื่องจักร ความเสี่ยง และการปรับปรุงด้านพลังงาน ของเสีย และคาร์บอน โดยดำเนินการทดสอบก่อนใช้งานร่วมกันเป็นทีมได้', 'แฟ้มหลักฐานการทดสอบก่อนใช้งาน การปรับปรุง และ BCG', 'AISK05'),
  (86, 'EN-714-12013', 1, 'ใช้เครื่องมือช่วยพัฒนาด้วยปัญญาประดิษฐ์เพื่อสร้างโปรแกรมประยุกต์ปัญญาประดิษฐ์แบบครบวงจร พร้อมทดสอบรหัส ตัวแบบ และระบบ และจัดทำกระบวนการบูรณาการกับส่งมอบอย่างต่อเนื่องได้', 'โปรแกรมประยุกต์ที่นำขึ้นใช้งาน ผลการทดสอบ และกระบวนการส่งมอบ', 'AISK06'),
  (87, 'EN-714-12013', 2, 'วิเคราะห์ข้อกำหนดและแปลงเป็นสถาปัตยกรรมโซลูชัน ตัวแบบข้อมูล ข้อตกลงของส่วนต่อประสานโปรแกรมประยุกต์และส่วนต่อประสานระบบ และเกณฑ์การยอมรับได้', 'แบบสถาปัตยกรรมและตารางสอบย้อนกลับข้อกำหนด', 'AISK09'),
  (88, 'EN-714-12013', 3, 'วิเคราะห์วัตถุประสงค์ระดับบริการและความสามารถในการสังเกตการณ์ระบบ พร้อมดำเนินการทดสอบการยอมรับของผู้ใช้และแบบฝึกจัดการเหตุการณ์ และจัดทำเอกสาร คู่มือปฏิบัติการ และหลักฐานส่งมอบร่วมกับทีมตามบทบาทได้', 'ชุดเอกสารการปฏิบัติการ การส่งมอบ และหลักฐานการมีส่วนร่วม', 'AISK09'),
  (89, 'EN-714-12017', 1, 'สืบค้น ประเมิน และสังเคราะห์แหล่งวิชาการและวิชาชีพด้านเทคโนโลยีปัญญาประดิษฐ์ร่วมสมัยอย่างเป็นระบบ พร้อมนำเสนอและอภิปรายเป็นภาษาไทยและภาษาอังกฤษโดยอ้างอิงหลักฐานได้', 'รายงานทบทวนวรรณกรรมและการนำเสนอสัมมนา', 'AISK06'),
  (90, 'EN-714-12017', 2, 'วิเคราะห์ประเด็นจริยธรรม ความมั่นคงปลอดภัย ความปลอดภัย และผลกระทบของเทคโนโลยีที่ศึกษา พร้อมจัดทำเอกสารกำกับตัวแบบและบันทึกธรรมาภิบาลได้', 'บันทึกวิเคราะห์จริยธรรมและแฟ้มหลักฐานธรรมาภิบาล', 'AISK07'),
  (91, 'EN-714-12017', 3, 'ประเมินเทคโนโลยีปัญญาประดิษฐ์เชิงสร้างหรือระบบเอเจนต์ มาตรฐาน กฎหมาย และแนวโน้มที่เกี่ยวข้องกับแขนงวิชาได้', 'เอกสารเฝ้าติดตามเทคโนโลยีและมาตรฐาน', 'AISK06'),
  (92, 'EN-714-17001', 1, 'สื่อสารเพื่อสมัครงานและนำเสนอระเบียนทักษะเป็นภาษาไทยและภาษาอังกฤษได้', 'ประวัติย่อ การสัมภาษณ์ และแฟ้มสะสมผลงาน', 'AISK08'),
  (93, 'EN-714-17001', 2, 'ปฏิบัติตามจรรยาบรรณ ความปลอดภัยในการทำงาน ความมั่นคงปลอดภัย ความเป็นส่วนตัว คุณภาพ และมาตรฐานได้', 'ผลการประเมินการปฏิบัติตามข้อกำหนดและความปลอดภัย', 'AISK07'),
  (94, 'EN-714-17001', 3, 'วิเคราะห์บทบาท ความคาดหวัง และช่องว่างสมรรถนะของตนเทียบกับทีมและผู้มีส่วนได้ส่วนเสีย เพื่อวางแผนการทำงานและการพัฒนาตนเองอย่างรับผิดชอบได้', 'แผนการเรียนรู้สำหรับสหกิจศึกษา', 'AISK08'),
  (95, 'GE-001-13003', 1, 'อธิบายแนวคิดผู้ประกอบการและโมเดลธุรกิจในสังคมดิจิทัลได้', NULL, NULL),
  (96, 'GE-001-13003', 2, 'เสนอแนวทางพัฒนาธุรกิจโดยใช้เทคโนโลยีดิจิทัลได้', NULL, NULL),
  (97, 'EN-714-12014', 1, 'สร้างชุดข้อมูลสำหรับการประเมิน และประเมินความถูกต้อง การอ้างอิง การสร้างข้อมูลเท็จ ความทนทาน ความเป็นส่วนตัว ความมั่นคงปลอดภัย ต้นทุน และเวลาตอบสนองได้', 'รายงานการประเมินและบัตรความเสี่ยง', 'AISK06'),
  (98, 'EN-714-12014', 2, 'ออกแบบกระบวนงานการสร้างข้อความเสริมด้วยการค้นคืนและระบบเอเจนต์ที่เชื่อมฐานความรู้ เครื่องมือ ส่วนต่อประสานโปรแกรมประยุกต์ และการกำกับดูแลโดยมนุษย์ได้', 'แบบสถาปัตยกรรมและการสาธิตระบบเอเจนต์', 'AISK06'),
  (99, 'EN-714-12014', 3, 'เปรียบเทียบและติดตามตัวแบบหรือเครื่องมือใหม่โดยอาศัยหลักฐาน พร้อมทำงานเป็นทีมเพื่อปรับปรุงระบบอย่างต่อเนื่องได้', 'รายงานทบทวนเทคโนโลยีและบันทึกการปรับปรุงแบบวนซ้ำ', 'AISK06'),
  (100, 'EN-714-12015', 1, 'วางแผนภารกิจอากาศยานไร้คนขับหรือระบบอัตโนมัติทางการเกษตรตามข้อกำกับ ความปลอดภัย และข้อจำกัดด้านสิ่งแวดล้อมได้', 'แผนภารกิจและความปลอดภัย', 'AISK02'),
  (101, 'EN-714-12015', 2, 'วิเคราะห์ข้อมูลการตรวจวัดระยะไกลและปัญญาประดิษฐ์เชิงพื้นที่ เพื่อจัดทำแผนที่ ตัวแบบ และข้อเสนอแนะเชิงพื้นที่ได้', 'ผลิตผลจากการวิเคราะห์ปัญญาประดิษฐ์เชิงพื้นที่', 'AISK05'),
  (102, 'EN-714-12015', 3, 'ออกแบบและบูรณาการภารกิจบิน การรับรู้ การนำทาง หรือการขับเคลื่อนของระบบย่อยหุ่นยนต์ พร้อมเชื่อมข้อมูลกับระบบฟาร์มและทดสอบภาคสนามเป็นทีมได้', 'การสาธิตระบบอัตโนมัติ ผลิตผลข้อมูล และบันทึกการทำงานของทีม', 'AISK02'),
  (103, 'EN-714-12016', 1, 'เขียนโปรแกรมตัวควบคุมแบบโปรแกรมได้ด้วยภาษาแลดเดอร์และฟังก์ชันบล็อก พร้อมต่อสัญญาณอินพุตและเอาต์พุตแบบดิจิทัลและแอนะล็อกตามแบบที่กำหนดได้', 'ชุดโปรแกรมควบคุมและผลการต่อสัญญาณ', 'AISK03'),
  (104, 'EN-714-12016', 2, 'วิเคราะห์การเชื่อมต่อเซนเซอร์และอุปกรณ์ภาคสนามเข้ากับระบบควบคุม ส่วนต่อประสานมนุษย์กับเครื่องจักร และระบบสกาดา พร้อมทดสอบการทำงานของเซลล์หุ่นยนต์ได้', 'รายงานผลการเชื่อมต่อและการทดสอบเซลล์หุ่นยนต์', 'AISK03'),
  (105, 'EN-714-12016', 3, 'วิเคราะห์ประสิทธิผลโดยรวมของเครื่องจักร ตรวจสอบความปลอดภัยของระบบ และจัดทำเอกสารส่งมอบร่วมกันเป็นทีมได้', 'แฟ้มหลักฐานประสิทธิผลเครื่องจักร ความปลอดภัย และเอกสารส่งมอบ', 'AISK03'),
  (106, 'EN-714-12018', 1, 'วางแผนรายการงานคงค้าง บทบาททีม เป้าหมายการเรียนรู้ และการส่งมอบได้', 'แผนโครงงานและแผนการเรียนรู้', 'AISK08'),
  (107, 'EN-714-12018', 2, 'วิเคราะห์ผู้มีส่วนได้ส่วนเสียและปัญหา พร้อมกำหนดข้อกำหนด ขอบเขต ตัวชี้วัดผลการดำเนินงานเฉพาะแขนง และเกณฑ์การยอมรับได้', 'ข้อเสนอโครงงานและข้อกำหนด', 'AISK09'),
  (108, 'EN-714-12018', 3, 'ออกแบบระเบียบวิธี แผนการทดลองและทดสอบ แผนความเสี่ยง คุณภาพ ความปลอดภัย ธุรกิจ และการประเมิน BCG ได้', 'แผนการประเมินและบริหารความเสี่ยง', 'AISK05'),
  (109, 'EN-714-12019', 1, 'สร้าง บูรณาการ ทดลอง และประเมินสมรรถนะ คุณภาพ ความปลอดภัย และความน่าเชื่อถือของระบบตามเกณฑ์ที่กำหนดได้', 'ระบบและแฟ้มหลักฐานการทดลองกับการทดสอบ', 'AISK01'),
  (110, 'EN-714-12019', 2, 'ทำงานเป็นทีม บริหารรายการงานคงค้าง ความเสี่ยง และการเปลี่ยนแปลง พร้อมแสดงความรับผิดชอบต่อผลลัพธ์ได้', 'บันทึกการทำงานของทีม การเปลี่ยนแปลง และความรับผิดชอบ', 'AISK08'),
  (111, 'EN-714-12019', 3, 'วิเคราะห์ปัญหาที่ซับซ้อน กำหนดข้อกำหนด และออกแบบระบบปัญญาประดิษฐ์หรือระบบอัจฉริยะแบบบูรณาการตามตัวชี้วัดผลการดำเนินงานเฉพาะแขนงได้', 'ข้อกำหนดและแบบสถาปัตยกรรม', 'AISK09'),
  (112, 'EN-714-12019', 4, 'ประเมินคุณค่าทางธุรกิจและตัวชี้วัด BCG หรือคาร์บอน พร้อมหลักฐานธรรมาภิบาล และส่งมอบผลงานแก่ผู้มีส่วนได้ส่วนเสียได้', 'หลักฐานด้านคุณค่า BCG ธรรมาภิบาล การทดสอบการยอมรับ และการส่งมอบ', 'AISK09'),
  (113, 'EN-714-12020', 1, 'ทวนสอบปัญหา ข้อกำหนด และเกณฑ์การยอมรับร่วมกับสถานประกอบการ พร้อมบริหารโครงงานและความเสี่ยงร่วมกับพี่เลี้ยงได้', NULL, NULL),
  (114, 'EN-714-12020', 2, 'ออกแบบ พัฒนา และบูรณาการระบบภายใต้ข้อจำกัดด้านข้อมูล เวลา และทรัพยากรขององค์กรได้', NULL, NULL),
  (115, 'EN-714-12020', 3, 'ออกแบบและดำเนินการทดลองเพื่อประเมินสมรรถนะ ความน่าเชื่อถือ และความปลอดภัย พร้อมจัดทำหลักฐานด้านจริยธรรมและธรรมาภิบาลข้อมูลได้', NULL, NULL),
  (116, 'EN-714-12020', 4, 'สาธิตและสอบป้องกันโครงงานต่อคณะกรรมการร่วมระหว่างมหาวิทยาลัยและสถานประกอบการได้', NULL, NULL),
  (117, 'EN-714-17002', 1, 'ทำงานเป็นทีมและแสดงบทบาทผู้นำหรือสมาชิกอย่างรับผิดชอบได้', 'ผลการประเมินจากสถานประกอบการและทีม', 'AISK08'),
  (118, 'EN-714-17002', 2, 'เก็บ วิเคราะห์ และสื่อสารผลแก่ผู้บริหารหรือผู้มีส่วนได้ส่วนเสีย พร้อมจัดทำเอกสารส่งมอบได้', 'รายงานข้อมูลและผลการวิเคราะห์ การนำเสนอ และเอกสารส่งมอบ', 'AISK05'),
  (119, 'EN-714-17002', 3, 'ปฏิบัติตามจริยธรรม คุณภาพ ความปลอดภัย และมาตรฐาน พร้อมวางแผนการเรียนรู้ตลอดชีวิตได้', 'บันทึกการปฏิบัติวิชาชีพและการสะท้อนผลการเรียนรู้', 'AISK07'),
  (120, 'EN-714-17002', 4, 'วิเคราะห์ข้อกำหนดและแก้ปัญหาวิศวกรรมจริงตามเกณฑ์การยอมรับของสถานประกอบการได้', 'บันทึกปัญหาและผลการยอมรับจากสถานประกอบการ', 'AISK09'),
  (121, 'EN-714-14001', 1, 'ออกแบบระบบชลประทานอัจฉริยะและระบบตรวจวัดความชื้นดินให้เหมาะกับพืชและพื้นที่ได้', NULL, NULL),
  (122, 'EN-714-14001', 2, 'พัฒนาตัวแบบพยากรณ์ความต้องการน้ำและควบคุมการให้น้ำอัตโนมัติได้', NULL, NULL),
  (123, 'EN-714-14001', 3, 'ประเมินประสิทธิภาพการใช้น้ำและความเสี่ยงภัยแล้งหรือน้ำท่วมในระดับแปลงและลุ่มน้ำได้', NULL, NULL),
  (124, 'EN-714-14002', 1, 'จัดการและวิเคราะห์ข้อมูลจากเซนเซอร์ ดาวเทียม และภาพถ่ายอากาศยานไร้คนขับเพื่อการเกษตรแม่นยำได้', NULL, NULL),
  (125, 'EN-714-14002', 2, 'พัฒนาตัวแบบตรวจจับโรคพืชและแมลงศัตรูพืชด้วยคอมพิวเตอร์วิทัศน์และการเรียนรู้เชิงลึกได้', NULL, NULL),
  (126, 'EN-714-14002', 3, 'เสนอแนวทางการจัดการธาตุอาหารและการวางแผนการผลิตจากผลการพยากรณ์ได้', NULL, NULL),
  (127, 'EN-714-14003', 1, 'จัดการและวิเคราะห์ข้อมูลเชิงพื้นที่แบบเวกเตอร์และแรสเตอร์พร้อมสร้างแผนที่ดิจิทัลได้', NULL, NULL),
  (128, 'EN-714-14003', 2, 'ประยุกต์การซ้อนทับ บัฟเฟอร์ และการวิเคราะห์เครือข่ายร่วมกับการเรียนรู้ของเครื่องได้', NULL, NULL),
  (129, 'EN-714-14003', 3, 'ประเมินความเหมาะสมของพื้นที่ปลูกพืชและติดตามการเปลี่ยนแปลงการใช้ที่ดินได้', NULL, NULL),
  (130, 'EN-714-14004', 1, 'อธิบายสรีรวิทยาและสาเหตุการสูญเสียผลผลิตหลังการเก็บเกี่ยว พร้อมเสนอแนวทางลดความสูญเสียได้', NULL, NULL),
  (131, 'EN-714-14004', 2, 'ออกแบบระบบคัดแยกและคัดเกรดด้วยคอมพิวเตอร์วิทัศน์และระบบควบคุมสภาพแวดล้อมในโรงเก็บได้', NULL, NULL),
  (132, 'EN-714-14004', 3, 'ประเมินคุณภาพผลผลิตและออกแบบระบบตรวจสอบย้อนกลับได้', NULL, NULL),
  (133, 'EN-714-14005', 1, 'จัดการข้อมูลขนาดใหญ่จากเครือข่ายเซนเซอร์และวิเคราะห์อนุกรมเวลาของข้อมูลฟาร์มได้', NULL, NULL),
  (134, 'EN-714-14005', 2, 'สร้างตัวแบบพยากรณ์ผลผลิตและราคาสินค้าเกษตรพร้อมประเมินความถูกต้องของตัวแบบได้', NULL, NULL),
  (135, 'EN-714-14005', 3, 'ออกแบบแผงควบคุมข้อมูลและสื่อสารผลการพยากรณ์แก่เกษตรกรและผู้บริหารได้', NULL, NULL),
  (136, 'EN-714-14006', 1, 'อธิบายสถาปัตยกรรมโรงงานผลิตพืชปิดและระบบปลูกพืชไร้ดินแต่ละรูปแบบได้', NULL, NULL),
  (137, 'EN-714-14006', 2, 'ออกแบบระบบแสงเทียมและการควบคุมสภาพแวดล้อมอัตโนมัติด้วยปัญญาประดิษฐ์ได้', NULL, NULL),
  (138, 'EN-714-14006', 3, 'วิเคราะห์ต้นทุน ผลตอบแทน และการใช้พลังงานของการลงทุนในโรงงานผลิตพืชได้', NULL, NULL),
  (139, 'EN-714-14007', 1, 'ออกแบบระบบติดตามสุขภาพสัตว์ด้วยอินเทอร์เน็ตของสรรพสิ่งและเซนเซอร์สวมใส่ได้', NULL, NULL),
  (140, 'EN-714-14007', 2, 'วิเคราะห์พฤติกรรมสัตว์และพยากรณ์โรคด้วยคอมพิวเตอร์วิทัศน์และการเรียนรู้ของเครื่องได้', NULL, NULL),
  (141, 'EN-714-14007', 3, 'ประเมินประสิทธิภาพการผลิตของฟาร์มและออกแบบระบบตรวจสอบย้อนกลับผลิตภัณฑ์ได้', NULL, NULL),
  (142, 'EN-714-14008', 1, 'ออกแบบระบบกล้องและแสง พร้อมสร้างและจัดการชุดข้อมูลภาพผลผลิตเกษตรได้', NULL, NULL),
  (143, 'EN-714-14008', 2, 'ฝึกและปรับแต่งตัวแบบการเรียนรู้เชิงลึกเพื่อจำแนกประเภทและตรวจจับตำหนิ พร้อมพัฒนาโปรแกรมประยุกต์เฉพาะงานได้', NULL, NULL),
  (144, 'EN-714-14008', 3, 'ประเมินความแม่นยำของระบบเทียบกับค่ามาตรฐานห้องปฏิบัติการและบูรณาการกับระบบคัดแยกอัตโนมัติได้', NULL, NULL),
  (145, 'EN-714-14009', 1, 'ออกแบบเครือข่ายเซนเซอร์ฟาร์มและเตรียมข้อมูลด้วยการประมวลผลสัญญาณและการกรองสัญญาณรบกวนได้', NULL, NULL),
  (146, 'EN-714-14009', 2, 'สร้างตัวแบบการเรียนรู้ของเครื่องเพื่อพยากรณ์และตรวจจับความผิดปกติจากข้อมูลเซนเซอร์ได้', NULL, NULL),
  (147, 'EN-714-14009', 3, 'แสดงผลและรายงานข้อมูลเซนเซอร์ผ่านแผงควบคุมเพื่อสนับสนุนการตัดสินใจได้', NULL, NULL),
  (148, 'EN-714-14010', 1, 'วิเคราะห์สมบัติของดินและธาตุอาหารพืชเพื่อวางแผนการใช้ปุ๋ยเฉพาะพื้นที่ได้', NULL, NULL),
  (149, 'EN-714-14010', 2, 'ใช้ข้อมูลเซนเซอร์และภาพถ่ายอากาศยานไร้คนขับร่วมกับการเรียนรู้เชิงลึกเพื่อวิเคราะห์โรคพืชและพยากรณ์ผลผลิตได้', NULL, NULL),
  (150, 'EN-714-14010', 3, 'พัฒนาระบบสนับสนุนการตัดสินใจและวิเคราะห์ต้นทุนการผลิตเพื่อการผลิตพืชอย่างยั่งยืนได้', NULL, NULL),
  (151, 'EN-714-14011', 1, 'อธิบายองค์ประกอบของระบบหุ่นยนต์เกษตรทั้งเซนเซอร์ ตัวกระตุ้น และระบบควบคุมได้', NULL, NULL),
  (152, 'EN-714-14011', 2, 'ออกแบบและทดสอบการนำทางอัตโนมัติ การระบุตำแหน่ง และการวางแผนเส้นทางของหุ่นยนต์เกษตรได้', NULL, NULL),
  (153, 'EN-714-14011', 3, 'บูรณาการหุ่นยนต์กับอากาศยานไร้คนขับและระบบฟาร์มอัจฉริยะเพื่อแก้ปัญหาทางการเกษตรได้', NULL, NULL),
  (154, 'EN-714-14012', 1, 'วางแผนเส้นทางบินสำรวจทางการเกษตรและปฏิบัติการบินอย่างปลอดภัยตามกฎหมายและใบอนุญาตได้', NULL, NULL),
  (155, 'EN-714-14012', 2, 'ประมวลผลและวิเคราะห์ภาพถ่ายทางอากาศด้วยการเรียนรู้ของเครื่อง พร้อมสร้างแผนที่ดัชนีพืชพรรณได้', NULL, NULL),
  (156, 'EN-714-14012', 3, 'จัดทำแผนที่การให้ปัจจัยการผลิตแบบผันแปรตามพื้นที่และประเมินความเสียหายของแปลงเกษตรได้', NULL, NULL),
  (157, 'EN-714-14013', 1, 'วิเคราะห์ห่วงโซ่อุปทานสินค้าเกษตรและวางแผนการจัดหาและกระจายผลผลิตด้วยปัญญาประดิษฐ์ได้', NULL, NULL),
  (158, 'EN-714-14013', 2, 'ออกแบบระบบตรวจสอบย้อนกลับด้วยเทคโนโลยีบล็อกเชนตลอดห่วงโซ่อุปทานได้', NULL, NULL),
  (159, 'EN-714-14013', 3, 'พยากรณ์ความต้องการของตลาดและจัดเส้นทางการขนส่งเพื่อลดความสูญเสียอาหารได้', NULL, NULL),
  (160, 'EN-714-14014', 1, 'อธิบายความสัมพันธ์ระหว่างปัญญาประดิษฐ์กับเทคโนโลยีชีวภาพการเกษตรได้', NULL, NULL),
  (161, 'EN-714-14014', 2, 'ใช้การเรียนรู้ของเครื่องวิเคราะห์ข้อมูลพันธุกรรมและลำดับดีเอ็นเอเพื่อคัดเลือกสายพันธุ์ที่ทนทานได้', NULL, NULL),
  (162, 'EN-714-14014', 3, 'ประเมินประเด็นจริยธรรมและความปลอดภัยทางชีวภาพในการประยุกต์ใช้ปัญญาประดิษฐ์ได้', NULL, NULL),
  (163, 'EN-714-14015', 1, 'วิเคราะห์ข้อมูลภูมิอากาศขนาดใหญ่และพยากรณ์สภาพอากาศสุดขั้ว ภัยแล้ง และอุทกภัยด้วยปัญญาประดิษฐ์ได้', NULL, NULL),
  (164, 'EN-714-14015', 2, 'ประเมินความเสี่ยงต่อผลผลิตทางการเกษตรและออกแบบระบบเตือนภัยล่วงหน้าอัจฉริยะได้', NULL, NULL),
  (165, 'EN-714-14015', 3, 'เสนอกลยุทธ์การปรับตัวของภาคการเกษตรและแนวทางประกันภัยพืชผลที่อาศัยข้อมูลดาวเทียมได้', NULL, NULL),
  (166, 'EN-714-14016', 1, 'สร้างแบบจำลองพลวัตและวิเคราะห์เสถียรภาพของวงควบคุมกระบวนการอุตสาหกรรมได้', NULL, NULL),
  (167, 'EN-714-14016', 2, 'ออกแบบและปรับตั้งการควบคุมขั้นสูง ทั้งแบบป้อนไปข้างหน้า แบบหลายตัวแปร และการควบคุมเชิงทำนายด้วยแบบจำลองได้', NULL, NULL),
  (168, 'EN-714-14016', 3, 'กำหนดค่าระบบควบคุมแบบกระจาย เชื่อมต่อกับสกาดาและระบบบริหารการผลิต แล้วประเมินสมรรถนะด้วยตัวชี้วัดคุณภาพและพลังงานได้', NULL, NULL),
  (169, 'EN-714-14017', 1, 'เก็บและประมวลผลสัญญาณการสั่นสะเทือน เสียง อุณหภูมิ และกระแสไฟฟ้า พร้อมสกัดคุณลักษณะเพื่อวินิจฉัยเครื่องจักรได้', NULL, NULL),
  (170, 'EN-714-14017', 2, 'สร้างตัวแบบการเรียนรู้ของเครื่องเพื่อตรวจจับความผิดปกติและพยากรณ์ความเสียหายได้', NULL, NULL),
  (171, 'EN-714-14017', 3, 'ออกแบบระบบแจ้งเตือนและแผนบำรุงรักษาอัตโนมัติ พร้อมประเมินผลตอบแทนการลงทุนได้', NULL, NULL),
  (172, 'EN-714-14018', 1, 'ออกแบบผังคลังสินค้าและเลือกระบบจัดเก็บและเรียกคืนอัตโนมัติให้เหมาะกับโรงงานเกษตรอุตสาหกรรมได้', NULL, NULL),
  (173, 'EN-714-14018', 2, 'บูรณาการคอมพิวเตอร์วิทัศน์ อาร์เอฟไอดี และระบบการจัดการคลังสินค้าเพื่อตรวจสอบและติดตามสินค้าได้', NULL, NULL),
  (174, 'EN-714-14018', 3, 'วิเคราะห์และเพิ่มประสิทธิภาพการไหลของสินค้าด้วยการจำลองและการจัดการสินค้าคงคลังด้วยปัญญาประดิษฐ์ได้', NULL, NULL),
  (175, 'EN-714-14019', 1, 'สร้างตัวแบบการตัดสินใจทางอุตสาหกรรมด้วยการโปรแกรมเชิงเส้น จำนวนเต็มผสม และหลายวัตถุประสงค์ได้', NULL, NULL),
  (176, 'EN-714-14019', 2, 'ประยุกต์ทฤษฎีแถวคอย การจำลองเหตุการณ์ไม่ต่อเนื่อง และวิธีเมตาฮิวริสติกกับปัญหาการผลิตและโลจิสติกส์ได้', NULL, NULL),
  (177, 'EN-714-14019', 3, 'วิเคราะห์ความไวและเปรียบเทียบทางเลือกด้วยตัวชี้วัดต้นทุน เวลา และความเสี่ยง พร้อมสื่อสารข้อเสนอแนะได้', NULL, NULL),
  (178, 'EN-714-14020', 1, 'อธิบายกระบวนการแปรรูปผลผลิตเกษตรและมาตรฐานคุณภาพและความปลอดภัยอาหารที่เกี่ยวข้องได้', NULL, NULL),
  (179, 'EN-714-14020', 2, 'วิเคราะห์การจัดการของเสีย น้ำเสีย และการใช้พลังงานในโรงงานเกษตรอุตสาหกรรมได้', NULL, NULL),
  (180, 'EN-714-14020', 3, 'เสนอแนวทางประยุกต์ปัญญาประดิษฐ์และเทคโนโลยีดิจิทัลเพื่อเพิ่มประสิทธิภาพและลดต้นทุนกระบวนการแปรรูปได้', NULL, NULL),
  (181, 'EN-714-14021', 1, 'อธิบายกระบวนการสีข้าวตั้งแต่การรับซื้อข้าวเปลือกถึงการบรรจุ และระบุจุดควบคุมคุณภาพได้', NULL, NULL),
  (182, 'EN-714-14021', 2, 'พัฒนาระบบคอมพิวเตอร์วิทัศน์ตรวจสอบคุณภาพข้าวและระบบอบแห้งที่ควบคุมความชื้นอัตโนมัติได้', NULL, NULL),
  (183, 'EN-714-14021', 3, 'ประยุกต์ดิจิทัลทวินและการบำรุงรักษาเชิงพยากรณ์เพื่อเพิ่มประสิทธิภาพและตรวจสอบย้อนกลับคุณภาพข้าวได้', NULL, NULL),
  (184, 'EN-714-14022', 1, 'อธิบายกระบวนการผลิตน้ำตาลตั้งแต่การรับอ้อยถึงการบรรจุ และระบุจุดควบคุมคุณภาพได้', NULL, NULL),
  (185, 'EN-714-14022', 2, 'พัฒนาระบบปัญญาประดิษฐ์วิเคราะห์คุณภาพอ้อยและพยากรณ์ค่าความหวาน พร้อมควบคุมกระบวนการหีบด้วยตัวควบคุมแบบโปรแกรมได้', NULL, NULL),
  (186, 'EN-714-14022', 3, 'ประเมินการจัดการพลังงานร่วมจากชีวมวล ของเสีย และผลพลอยได้ของโรงงานน้ำตาลได้', NULL, NULL),
  (187, 'EN-714-14023', 1, 'อธิบายกระบวนการผลิตแป้งมันสำปะหลังครบวงจรและระบุจุดสูญเสียในกระบวนการได้', NULL, NULL),
  (188, 'EN-714-14023', 2, 'พัฒนาระบบคอมพิวเตอร์วิทัศน์ตรวจรับวัตถุดิบและพยากรณ์ปริมาณแป้ง พร้อมควบคุมกระบวนการสกัดเพื่อเพิ่มอัตราการสกัดได้', NULL, NULL),
  (189, 'EN-714-14023', 3, 'ประเมินการประหยัดพลังงานในการอบแห้ง การจัดการน้ำเสีย และโอกาสผลิตผลิตภัณฑ์มูลค่าสูงได้', NULL, NULL),
  (190, 'EN-714-14024', 1, 'ออกแบบและติดตั้งเครือข่ายเซนเซอร์อุณหภูมิ ความชื้น และก๊าซในโรงเก็บ ไซโล และห้องเย็นได้', NULL, NULL),
  (191, 'EN-714-14024', 2, 'พัฒนาระบบควบคุมสภาพแวดล้อมอัตโนมัติและระบบแจ้งเตือนด้วยปัญญาประดิษฐ์ได้', NULL, NULL),
  (192, 'EN-714-14024', 3, 'พยากรณ์อายุการเก็บรักษาและวิเคราะห์คุณภาพผลผลิตระหว่างจัดเก็บด้วยการเรียนรู้ของเครื่องได้', NULL, NULL),
  (193, 'EN-714-14025', 1, 'คำนวณและออกแบบระบบอบแห้งผลผลิตเกษตรจากหลักการถ่ายเทความร้อนและมวลสารได้', NULL, NULL),
  (194, 'EN-714-14025', 2, 'ควบคุมกระบวนการอบแห้งอัตโนมัติด้วยตัวควบคุมแบบโปรแกรมได้และการตรวจวัดความชื้นแบบเวลาจริงได้', NULL, NULL),
  (195, 'EN-714-14025', 3, 'สร้างตัวแบบการเรียนรู้ของเครื่องเพื่อเพิ่มประสิทธิภาพการอบแห้งและประหยัดพลังงานร่วมกับระบบผลิตพลังงานร่วมได้', NULL, NULL),
  (196, 'EN-714-14026', 1, 'เลือกและคำนวณอุปกรณ์ขนถ่ายวัสดุ รวมถึงความดันสูญเสียและความเร็วลมลำเลียงสำหรับวัสดุผงได้', NULL, NULL),
  (197, 'EN-714-14026', 2, 'ออกแบบเครื่องจักรบรรจุภัณฑ์อัตโนมัติและระบบควบคุมด้วยตัวควบคุมแบบโปรแกรมได้และสกาดาได้', NULL, NULL),
  (198, 'EN-714-14026', 3, 'ประเมินความปลอดภัยจากฝุ่นระเบิดและประสิทธิภาพของระบบขนถ่าย พร้อมวางแผนบำรุงรักษาเชิงพยากรณ์ได้', NULL, NULL),
  (199, 'EN-714-14027', 1, 'เลือกและกำหนดขนาดมอเตอร์ ชุดขับ และระบบส่งกำลัง พร้อมปรับตั้งระบบเซอร์โวสำหรับการควบคุมการเคลื่อนที่ได้', NULL, NULL),
  (200, 'EN-714-14027', 2, 'ออกแบบผังและลำดับการทำงานของเซลล์หุ่นยนต์ร่วมปฏิบัติงาน พร้อมโปรแกรมและจำลองการทำงานได้', NULL, NULL),
  (201, 'EN-714-14027', 3, 'ประเมินความเสี่ยง ขีดจำกัดแรงและกำลัง และดำเนินการทดสอบการยอมรับของเซลล์หุ่นยนต์ได้', NULL, NULL),
  (202, 'EN-714-14028', 1, 'ทำแผนที่สายธารคุณค่าและจำแนกความสูญเปล่าในกระบวนการผลิตได้', NULL, NULL),
  (203, 'EN-714-14028', 2, 'วิเคราะห์ประสิทธิผลโดยรวมของเครื่องจักรและควบคุมกระบวนการเชิงสถิติ พร้อมวิเคราะห์สาเหตุที่แท้จริงได้', NULL, NULL),
  (204, 'EN-714-14028', 3, 'ออกแบบและทดลองมาตรการปรับปรุงด้วยการเรียนรู้ของเครื่อง พร้อมประเมินผลก่อน–หลังด้วยตัวชี้วัดคุณภาพ ต้นทุน และพลังงานได้', NULL, NULL),
  (205, 'EN-714-14029', 1, 'ออกแบบระบบแสงสว่างและเลือกเลนส์ให้เหมาะกับงานตรวจสอบคุณภาพในสายการผลิตได้', NULL, NULL),
  (206, 'EN-714-14029', 2, 'พัฒนาตัวแบบการเรียนรู้เชิงลึกเพื่อตรวจจับและจำแนกข้อบกพร่องของชิ้นงานได้', NULL, NULL),
  (207, 'EN-714-14029', 3, 'บูรณาการระบบวิสัยทัศน์กับหุ่นยนต์และระบบคัดแยกอัตโนมัติ พร้อมวิเคราะห์ข้อมูลภาพเพื่อปรับปรุงกระบวนการได้', NULL, NULL),
  (208, 'EN-714-14030', 1, 'ตรวจสอบและวิเคราะห์การใช้พลังงานของเครื่องจักรและระบบสนับสนุนในโรงงานได้', NULL, NULL),
  (209, 'EN-714-14030', 2, 'ออกแบบระบบผลิตไฟฟ้าด้วยเซลล์แสงอาทิตย์และระบบบริหารจัดการพลังงานที่เก็บข้อมูลแบบเวลาจริงได้', NULL, NULL),
  (210, 'EN-714-14030', 3, 'พยากรณ์ความต้องการพลังงานและตรวจจับความผิดปกติด้วยปัญญาประดิษฐ์ พร้อมวิเคราะห์ความคุ้มค่าและการลดก๊าซเรือนกระจกได้', NULL, NULL),
  (211, 'EN-714-14031', 1, 'เชื่อมต่อระบบกำลังของไหลกับตัวควบคุม อุปกรณ์ตรวจวัด และอุปกรณ์ประมวลผลที่ขอบเครือข่าย พร้อมเก็บข้อมูลเวลาจริงได้', 'ระบบต้นแบบและชุดข้อมูลการทดสอบ', 'AISK03'),
  (212, 'EN-714-14031', 2, 'พัฒนาและประเมินวิธีตรวจจับความผิดปกติ การบำรุงรักษาเชิงพยากรณ์ หรือการควบคุมแบบปรับตัว โดยคำนึงถึงความปลอดภัยและพลังงานได้', 'รายงานการทดลอง สมรรถนะ ความปลอดภัย และข้อเสนอปรับปรุง', 'AISK03'),
  (213, 'EN-714-14031', 3, 'วิเคราะห์ข้อกำหนดและออกแบบวงจรนิวแมติกส์ ไฮดรอลิกส์ ไฟฟ้า–นิวแมติกส์ หรือไฟฟ้า–ไฮดรอลิกส์สำหรับระบบอัตโนมัติได้', 'แบบวงจร รายการอุปกรณ์ และผลการตรวจสอบการออกแบบ', 'AISK03'),
  (214, 'EN-714-14032', 1, 'สร้างและตรวจสอบแบบจำลองเชิงตัวเลขหรือแบบจำลองการเรียนรู้ของเครื่องเพื่อพยากรณ์อัตราการถ่ายโอนและสมรรถนะได้', 'แบบจำลอง ชุดข้อมูล และรายงานการตรวจสอบความถูกต้อง', 'AISK01'),
  (215, 'EN-714-14032', 2, 'วิเคราะห์การนำ การพา การแผ่รังสี และการถ่ายโอนมวลสารในระบบอัจฉริยะทั้งสภาวะคงตัวและไม่คงตัวได้', 'รายงานการคำนวณและวิเคราะห์ระบบ', 'AISK03'),
  (216, 'EN-714-14032', 3, 'ประเมินและเสนอแนวทางปรับปรุงระบบจัดการความร้อน ระบบอบแห้ง ห้องเย็น หรือกระบวนการทางความร้อน โดยคำนึงถึงพลังงาน ต้นทุน และคาร์บอนได้', 'รายงานเปรียบเทียบทางเลือกและตัวชี้วัดพลังงาน–คาร์บอน', 'AISK03'),
  (217, 'EN-714-14033', 1, 'ดำเนินการสำรวจหรือสืบสวนอุบัติการณ์ วิเคราะห์ข้อมูล และสื่อสารแผนลดความเสี่ยงต่อผู้ปฏิบัติงานและผู้บริหารร่วมกับทีมได้', 'รายงานสำรวจความปลอดภัย การนำเสนอ และหลักฐานการทำงานเป็นทีม', 'AISK05'),
  (218, 'EN-714-14033', 2, 'ชี้บ่งอันตราย ประเมินความเสี่ยง และวินิจฉัยความสอดคล้องกับกฎหมายหรือมาตรฐานความปลอดภัยของระบบอุตสาหกรรมได้', 'ทะเบียนอันตรายและรายงานประเมินความเสี่ยง', 'AISK03'),
  (219, 'EN-714-14033', 3, 'ออกแบบมาตรการควบคุมความเสี่ยง ระบบป้องกัน อินเตอร์ล็อก การหยุดฉุกเฉิน และระบบเฝ้าระวังด้วยเซนเซอร์หรือปัญญาประดิษฐ์ตามลำดับชั้นการควบคุมได้', 'แบบมาตรการป้องกันและผลการทดสอบหน้าที่ความปลอดภัย', 'AISK03'),
  (220, 'EN-714-14034', 1, 'วิเคราะห์ภาระ ความเค้น ความเมื่อยล้า และค่าความปลอดภัยของชิ้นส่วนเครื่องจักรได้', NULL, NULL),
  (221, 'EN-714-14034', 2, 'ออกแบบชิ้นส่วนส่งกำลังและสร้างแบบจำลองสามมิติพร้อมวิเคราะห์ด้วยระเบียบวิธีไฟไนต์เอลิเมนต์ได้', NULL, NULL),
  (222, 'EN-714-14034', 3, 'บูรณาการเซนเซอร์เข้ากับเครื่องจักรและใช้ปัญญาประดิษฐ์หาค่าเหมาะที่สุดของการออกแบบและทำนายความเสียหายได้', NULL, NULL),
  (223, 'EN-714-14035', 1, 'วิเคราะห์จลนศาสตร์และพลศาสตร์ของกลไกและแขนกลสำหรับการเคลื่อนที่แม่นยำได้', NULL, NULL),
  (224, 'EN-714-14035', 2, 'ออกแบบโครงสร้างเครื่องจักร อุปกรณ์จับยึด และปลายแขนกล พร้อมเลือกมอเตอร์และชุดขับให้เหมาะสมได้', NULL, NULL),
  (225, 'EN-714-14035', 3, 'บูรณาการระบบควบคุม เซนเซอร์ และการมองเห็นของเครื่องจักร พร้อมประเมินความเสี่ยงและทดสอบการยอมรับได้', NULL, NULL),
  (226, 'EN-714-14036', 1, 'ออกแบบสถาปัตยกรรมท่อข้อมูลและที่เก็บข้อมูลขนาดใหญ่สำหรับระบบปัญญาประดิษฐ์ได้', NULL, NULL),
  (227, 'EN-714-14036', 2, 'สร้างท่อข้อมูลแบบเวลาจริงและบูรณาการข้อมูลจากแหล่งที่หลากหลายได้', NULL, NULL),
  (228, 'EN-714-14036', 3, 'จัดการคุณภาพข้อมูล ธรรมาภิบาลข้อมูล และการติดตามท่อข้อมูลในสภาพแวดล้อมการทำงานจริงได้', NULL, NULL),
  (229, 'EN-714-14037', 1, 'อธิบายสถาปัตยกรรมและกระบวนการทำงานของตัวแบบภาษาขนาดใหญ่ พร้อมจัดเตรียมชุดข้อมูลเฉพาะโดเมนได้', NULL, NULL),
  (230, 'EN-714-14037', 2, 'ปรับตัวแบบตามคำสั่งและแบบประหยัดพารามิเตอร์ พร้อมบีบอัดและเพิ่มประสิทธิภาพการอนุมานได้', NULL, NULL),
  (231, 'EN-714-14037', 3, 'ประเมินความถูกต้อง การให้เหตุผล ความเที่ยงตรงต่อข้อเท็จจริง และความทนทานด้วยเกณฑ์มาตรฐาน พร้อมติดตามการเสื่อมของสมรรถนะได้', NULL, NULL),
  (232, 'EN-714-14038', 1, 'กำหนดข้อกำหนดสมรรถนะและสร้างชุดทดสอบสำหรับข้อมูลปกติ ข้อมูลนอกการแจกแจง และกรณีขอบได้', NULL, NULL),
  (233, 'EN-714-14038', 2, 'วัดความไม่แน่นอน สอบเทียบความเชื่อมั่น และประเมินความทนทานต่อการโจมตีแบบปรปักษ์ ความลำเอียง และความเป็นธรรมได้', NULL, NULL),
  (234, 'EN-714-14038', 3, 'จัดทำบัตรตัวแบบ หลักฐานการประกันคุณภาพ และระบบติดตามการเลื่อนของข้อมูลและตัวแบบได้', NULL, NULL),
  (235, 'EN-714-14039', 1, 'แบ่งขอบเขตโดเมนและบริการ พร้อมออกแบบสถาปัตยกรรมขับเคลื่อนด้วยเหตุการณ์และการจัดการเอพีไอได้', NULL, NULL),
  (236, 'EN-714-14039', 2, 'บูรณาการระบบปัญญาประดิษฐ์กับระบบวางแผนทรัพยากรองค์กร ระบบบริหารลูกค้าสัมพันธ์ และกระบวนการทำงานเดิมได้', NULL, NULL),
  (237, 'EN-714-14039', 3, 'ออกแบบการจัดการอัตลักษณ์และสิทธิ์ ความพร้อมใช้สูง การกู้คืนจากภัยพิบัติ และการบริหารต้นทุนคลาวด์ พร้อมจัดทำบันทึกการตัดสินใจทางสถาปัตยกรรมได้', NULL, NULL),
  (238, 'EN-714-14040', 1, 'วิจัยและวิเคราะห์ความต้องการผู้ใช้ พร้อมออกแบบโครงร่างและต้นแบบส่วนต่อประสานสำหรับระบบปัญญาประดิษฐ์ได้', NULL, NULL),
  (239, 'EN-714-14040', 2, 'ออกแบบแผงควบคุมข้อมูลและส่วนต่อประสานที่โปร่งใสตามหลักปัญญาประดิษฐ์ที่อธิบายได้', NULL, NULL),
  (240, 'EN-714-14040', 3, 'ทดสอบความสามารถในการใช้งานและประเมินประสบการณ์ผู้ใช้ พร้อมออกแบบที่ครอบคลุมผู้ใช้ทุกกลุ่มได้', NULL, NULL),
  (241, 'EN-714-14041', 1, 'จัดการฐานข้อมูลเวชระเบียนอิเล็กทรอนิกส์และข้อมูลสุขภาพขนาดใหญ่ได้', NULL, NULL),
  (242, 'EN-714-14041', 2, 'พัฒนาตัวแบบการเรียนรู้ของเครื่องเพื่อการวินิจฉัยเบื้องต้นและพยากรณ์ความเสี่ยงทางสุขภาพได้', NULL, NULL),
  (243, 'EN-714-14041', 3, 'ประเมินประเด็นจริยธรรมและความเป็นส่วนตัวของข้อมูลผู้ป่วยตามมาตรฐานสากลได้', NULL, NULL),
  (244, 'EN-714-14042', 1, 'ประมวลผลข้อมูลภาพทางการแพทย์และปรับปรุงคุณภาพภาพเพื่อการวิเคราะห์ได้', NULL, NULL),
  (245, 'EN-714-14042', 2, 'พัฒนาตัวแบบการเรียนรู้เชิงลึกเพื่อตรวจจับ แบ่งส่วนอวัยวะ และวิเคราะห์รอยโรคได้', NULL, NULL),
  (246, 'EN-714-14042', 3, 'ประเมินประสิทธิภาพของตัวแบบและบูรณาการระบบวิเคราะห์ภาพกับระบบจัดเก็บและสื่อสารข้อมูลภาพทางการแพทย์ได้', NULL, NULL),
  (247, 'EN-714-14043', 1, 'อธิบายหลักการเทคโนโลยีทางการเงินและระบบชำระเงินอิเล็กทรอนิกส์รวมถึงเทคโนโลยีบล็อกเชนได้', NULL, NULL),
  (248, 'EN-714-14043', 2, 'พัฒนาตัวแบบวิเคราะห์ความเสี่ยงสินเชื่อและตรวจจับการทุจริตทางการเงินด้วยการเรียนรู้ของเครื่องได้', NULL, NULL),
  (249, 'EN-714-14043', 3, 'ประเมินกฎระเบียบและนโยบายด้านเทคโนโลยีทางการเงินที่มีผลต่อการนำระบบไปใช้จริงได้', NULL, NULL),
  (250, 'EN-714-14044', 1, 'วิเคราะห์ข้อมูลอนุกรมเวลาทางการเงินและสร้างตัวแบบพยากรณ์ราคาสินทรัพย์ด้วยการเรียนรู้เชิงลึกได้', NULL, NULL),
  (251, 'EN-714-14044', 2, 'วิเคราะห์ความรู้สึกจากข่าวและสื่อสังคมออนไลน์ที่มีผลต่อตลาด พร้อมบริหารความเสี่ยงและพอร์ตการลงทุนด้วยปัญญาประดิษฐ์ได้', NULL, NULL),
  (252, 'EN-714-14044', 3, 'สร้างและทดสอบระบบเทรดอัตโนมัติ พร้อมแปลผลและแสดงภาพข้อมูลทางการเงินเพื่อการตัดสินใจทางธุรกิจได้', NULL, NULL),
  (253, 'EN-714-14045', 1, 'ตรวจสอบตลาดและความพร้อมของเทคโนโลยี พร้อมกำหนดรูปแบบรายได้ ราคา และเศรษฐศาสตร์ต่อหน่วยได้', NULL, NULL),
  (254, 'EN-714-14045', 2, 'วางกลยุทธ์เข้าสู่ตลาด การบริหารโครงการนำร่อง และการจัดการทรัพย์สินทางปัญญาและข้อตกลงระดับบริการได้', NULL, NULL),
  (255, 'EN-714-14045', 3, 'จัดทำประมาณการทางการเงินและนำเสนอแผนพาณิชย์แก่นักลงทุนหรือพันธมิตรได้', NULL, NULL),
  (256, 'EN-714-14046', 1, 'วางแผนและจัดการทรัพยากรของโครงการที่ขับเคลื่อนด้วยข้อมูลและปัญญาประดิษฐ์ด้วยวิธีอไจล์และสครัมได้', NULL, NULL),
  (257, 'EN-714-14046', 2, 'ประเมินความเสี่ยงและระยะเวลาของโครงการพัฒนาตัวแบบ พร้อมจัดการวงจรชีวิตของระบบการเรียนรู้ของเครื่องได้', NULL, NULL),
  (258, 'EN-714-14046', 3, 'บริหารความคาดหวังของผู้มีส่วนได้ส่วนเสียและวัดผลความสำเร็จของโครงการปัญญาประดิษฐ์ได้', NULL, NULL),
  (259, 'EN-714-14047', 1, 'วิเคราะห์และแบ่งกลุ่มลูกค้าเป้าหมายด้วยการเรียนรู้ของเครื่องเพื่อวางกลยุทธ์การตลาดดิจิทัลได้', NULL, NULL),
  (260, 'EN-714-14047', 2, 'สร้างเนื้อหาการตลาดอัตโนมัติด้วยปัญญาประดิษฐ์เชิงสร้างและออกแบบระบบแนะนำสินค้าแบบเฉพาะบุคคลได้', NULL, NULL),
  (261, 'EN-714-14047', 3, 'วิเคราะห์ประสิทธิผลของแคมเปญและประยุกต์แชตบอตเพื่อการบริการลูกค้าและการขายเชิงรุกได้', NULL, NULL),
  (262, 'EN-714-14048', 1, 'กำหนดวิสัยทัศน์ กลุ่มผู้ใช้ คุณค่าที่เสนอ และผลลัพธ์ทางธุรกิจของผลิตภัณฑ์ปัญญาประดิษฐ์ได้', NULL, NULL),
  (263, 'EN-714-14048', 2, 'จัดทำแผนที่เส้นทางผลิตภัณฑ์ ตัวชี้วัดผลิตภัณฑ์ และตัวชี้วัดสมรรถนะตัวแบบ พร้อมออกแบบการทดลองแบบเอ/บีได้', NULL, NULL),
  (264, 'EN-714-14048', 3, 'จัดการข้อมูลย้อนกลับ การเลื่อนของตัวแบบ และต้นทุน พร้อมตัดสินใจขยาย ปรับ หรือยุติผลิตภัณฑ์จากหลักฐานได้', NULL, NULL),
  (265, 'EN-714-14049', 1, 'อธิบายเทคโนโลยีความเป็นจริงเสมือน เสริม และผสม พร้อมบูรณาการปัญญาประดิษฐ์กับสภาพแวดล้อมจำลองได้', NULL, NULL),
  (266, 'EN-714-14049', 2, 'สร้างเนื้อหาสามมิติด้วยปัญญาประดิษฐ์เชิงสร้างและออกแบบการโต้ตอบด้วยคอมพิวเตอร์วิทัศน์และการประมวลผลภาษาธรรมชาติได้', NULL, NULL),
  (267, 'EN-714-14049', 3, 'พัฒนาแอปพลิเคชันสำหรับการจำลองทางการแพทย์ การฝึกอบรมอุตสาหกรรม หรือการตลาดดิจิทัล พร้อมวิเคราะห์พฤติกรรมผู้ใช้ได้', NULL, NULL),
  (268, 'EN-714-14050', 1, 'จัดทำบัญชีระบบปัญญาประดิษฐ์และจำแนกระดับความเสี่ยงตามกรอบธรรมาภิบาลได้', NULL, NULL),
  (269, 'EN-714-14050', 2, 'ประเมินผลกระทบด้านสิทธิ ความเป็นส่วนตัว ความเป็นธรรม และความปลอดภัย พร้อมกำหนดบทบาทและการกำกับโดยมนุษย์ได้', NULL, NULL),
  (270, 'EN-714-14050', 3, 'จัดทำทะเบียนความเสี่ยง บัตรตัวแบบ และหลักฐานสำหรับการตรวจประเมิน พร้อมติดตามหลังนำใช้และรายงานเหตุการณ์ได้', NULL, NULL),
  (271, 'EN-714-14051', 1, 'อธิบายหลักการและสถาปัตยกรรมของเทคโนโลยีปัญญาประดิษฐ์ที่ศึกษา พร้อมสืบค้นแหล่งความรู้ด้วยตนเองได้', NULL, NULL),
  (272, 'EN-714-14051', 2, 'ทดลองใช้เครื่องมือและกรอบงานร่วมสมัย พร้อมพัฒนาชิ้นงานหรือกรณีศึกษาเชิงประจักษ์ได้', NULL, NULL),
  (273, 'EN-714-14051', 3, 'วิเคราะห์ข้อจำกัด ความเสี่ยง และความเหมาะสมของเทคโนโลยีกับบริบทเกษตร อุตสาหกรรม หรือองค์กร พร้อมประเมินแนวโน้มการนำไปใช้จริงได้', NULL, NULL),
  (274, 'EN-714-14052', 1, 'อธิบายหลักการและสถาปัตยกรรมของเทคโนโลยีปัญญาประดิษฐ์ที่ศึกษา พร้อมสืบค้นแหล่งความรู้ด้วยตนเองได้', NULL, NULL),
  (275, 'EN-714-14052', 2, 'ทดลองใช้เครื่องมือและกรอบงานร่วมสมัย พร้อมพัฒนาชิ้นงานหรือกรณีศึกษาเชิงประจักษ์ได้', NULL, NULL),
  (276, 'EN-714-14052', 3, 'วิเคราะห์ข้อจำกัด ความเสี่ยง และความเหมาะสมของเทคโนโลยีกับบริบทเกษตร อุตสาหกรรม หรือองค์กร พร้อมประเมินแนวโน้มการนำไปใช้จริงได้', NULL, NULL),
  (277, 'EN-714-16001', 1, 'วิเคราะห์โจทย์และข้อกำหนดจากสถานประกอบการ พร้อมวางแผนงานภายใต้ข้อจำกัดด้านเวลาและทรัพยากรขององค์กรได้', NULL, NULL),
  (278, 'EN-714-16001', 2, 'ออกแบบ พัฒนา ทดสอบ และส่งมอบระบบปัญญาประดิษฐ์หรือระบบอัจฉริยะตามบริบทงานจริง พร้อมใช้ข้อมูลขององค์กรอย่างมีจริยธรรมและรักษาความลับได้', NULL, NULL),
  (279, 'EN-714-16001', 3, 'รายงานความก้าวหน้าและนำเสนอผลต่ออาจารย์นิเทศและพี่เลี้ยง พร้อมทำงานร่วมกับทีมในสถานประกอบการได้', NULL, NULL),
