INSERT INTO plo_assessment (plo_id, method, evidence, mastery_point, assessor) VALUES
  (1, 'การวิเคราะห์โจทย์ปัญหา การสร้างแบบจำลอง และการเปรียบเทียบทางเลือก', 'รายงานการวิเคราะห์ปัญหา แบบจำลองทางวิศวกรรม เหตุผลสนับสนุนแนวทางแก้ปัญหา', 'EN-714-12019, EN-714-17002', 'อาจารย์ผู้สอน คณะกรรมการสอบโครงงาน'),
  (2, 'การออกแบบสถาปัตยกรรมระบบ การพัฒนาต้นแบบ และการทดสอบตามข้อกำหนด', 'เอกสารข้อกำหนด แบบสถาปัตยกรรม ระบบต้นแบบ ผลการทดสอบ', 'EN-714-12009 ถึง EN-714-12014, EN-714-12019', 'อาจารย์ผู้สอน คณะกรรมการสอบโครงงาน'),
  (3, 'การนำเสนอ การจัดทำรายงานเชิงเทคนิค และการสื่อสารต่อผู้รับสารต่างกลุ่ม', 'รายงานภาษาไทยและภาษาอังกฤษ การนำเสนอสัมมนา แผงสรุปข้อมูล เอกสารส่งมอบ', 'EN-714-12019, EN-714-17001, EN-714-17002', 'อาจารย์ผู้สอน คณะกรรมการสอบ พนักงานที่ปรึกษา'),
  (4, 'การวิเคราะห์กรณีศึกษาจริยธรรม การประเมินความเสี่ยง และการจัดทำหลักฐานธรรมาภิบาล', 'รายงานการวิเคราะห์ผลกระทบ เอกสารกำกับตัวแบบ บัตรความเสี่ยง แผนลดผลกระทบ', 'EN-714-12009 ถึง EN-714-12014, EN-714-12019, EN-714-17002', 'อาจารย์ผู้สอน คณะกรรมการสอบโครงงาน'),
  (5, 'การประเมินการทำงานเป็นทีมและการบริหารการส่งมอบ', 'บันทึกการทำงานของทีม แบบประเมินโดยเพื่อนร่วมทีม แบบประเมิน 360 องศา บันทึกการบริหารความเสี่ยง', 'EN-714-12019, EN-714-17001, EN-714-17002', 'อาจารย์ผู้สอน เพื่อนร่วมทีม พนักงานที่ปรึกษา'),
  (6, 'การออกแบบการทดลอง การวิเคราะห์ข้อมูล และการประเมินสมรรถนะภายใต้ความไม่แน่นอน', 'แฟ้มหลักฐานการทดลอง รายงานการประเมินตัวแบบ ชุดหลักฐานการทำซ้ำผลการทดลอง', 'EN-714-12019, EN-714-17002', 'อาจารย์ผู้สอน คณะกรรมการสอบโครงงาน'),
  (7, 'การประเมินแฟ้มสะสมการเรียนรู้ และการประเมินคุณค่าของนวัตกรรม', 'เอกสารเฝ้าติดตามเทคโนโลยี แผนการเรียนรู้ส่วนบุคคล หลักฐานคุณค่าและตัวชี้วัดบีซีจี', 'EN-714-12014, EN-714-12019, EN-714-17001, EN-714-17002', 'อาจารย์ผู้สอน คณะกรรมการสอบโครงงาน');
INSERT INTO ksa_pedagogy (ksa_id, teaching_strategy, how, assessment_method, artifact, is_tailored, source) VALUES
  ('K1', 'การสอนโดยตรง (Direct Instruction)', 'บรรยายเชิงโต้ตอบพร้อมตัวอย่างคำนวณ · มอบหมายแบบฝึกหัดรายสัปดาห์ · สรุปหลักการด้วยผังมโนทัศน์', 'ข้อสอบกลางภาค/ปลายภาค และแบบฝึกหัดที่ตรวจตามเกณฑ์', 'กระดาษคำตอบและสมุดแบบฝึกหัดที่แสดงขั้นตอนการคิด', false, 'authored'),
  ('K2', 'การสอนโดยตรงร่วมกับปฏิบัติการ', 'บรรยายทฤษฎีแล้วทดสอบวัสดุจริงในห้องปฏิบัติการเพื่อยืนยันผลการคำนวณ', 'ข้อสอบคำนวณ ร่วมกับรายงานผลทดสอบวัสดุ', 'รายงานการคำนวณและผลทดสอบที่เทียบกับทฤษฎี', true, 'authored'),
  ('K3', 'การสอนโดยตรงร่วมกับปฏิบัติการ', 'บรรยายสมดุลมวล–พลังงาน แล้ววัดจริงจากชุดทดลองความร้อน–ของไหล', 'ข้อสอบคำนวณ ร่วมกับรายงานสมดุลพลังงานจากข้อมูลที่วัดเอง', 'รายงานสมดุลมวล–พลังงานพร้อมค่าความคลาดเคลื่อน', true, 'authored'),
  ('K4', 'การสอนโดยตรงร่วมกับปฏิบัติการ', 'บรรยายทฤษฎีการวัด แล้วสอบเทียบเครื่องมือจริงและวิเคราะห์ความไม่แน่นอน', 'ข้อสอบ ร่วมกับใบรายงานผลการสอบเทียบ', 'ใบสอบเทียบและรายงานความไม่แน่นอนของการวัด', true, 'authored'),
  ('K5', 'การสอนโดยตรง (Direct Instruction)', 'บรรยายเชิงโต้ตอบพร้อมตัวอย่างคำนวณ · มอบหมายแบบฝึกหัดรายสัปดาห์ · สรุปหลักการด้วยผังมโนทัศน์', 'ข้อสอบกลางภาค/ปลายภาค และแบบฝึกหัดที่ตรวจตามเกณฑ์', 'กระดาษคำตอบและสมุดแบบฝึกหัดที่แสดงขั้นตอนการคิด', false, 'authored'),
